window.POEM_DB=window.POEM_DB||{};POEM_DB["qing_006"]={"n":"戴亨","dyn":"清","poems":[{"t":"听门人沈弹琴","f":"五言古诗","c":["朝雨生微凉，尘客绝来径。","枝上鸟声清，阶下苔痕净。","独坐小窗前，名花素磁瑩。","丘壑结遥想，清吟寄孤兴。","为我张鸣琴，澄心发真听。","泠泠太古音，天宇夜深静。"]},{"t":"乙丑秋孟颖仙告予贫甚质衣助之偶检文箧见其旧字感而赋此不必寄孟也","f":"古风","c":["南海有奇香，置诸崔嵬博山之金炉。","朱火扬其芳，光彩氤氲凌上都。","豫章楩楠在空谷，雨露之所濡，造物之所育。","坚理直干经千春，梁栋不为用，樵夫牧竖摧为薪。","君不见欧冶子，能因国君铜铁利，铸作金钟大镛器。","而令为身谋，不能自作一鼎觯。","园女拾宝戟，但用刈秋葵。","盲者得宝镜，不堪盖陋卮。","干将莫邪补破履，不如市头三钱锥。","君不见百里奚，鬻身仅直五羊皮。","陈平宰割天下奇，奉身安能烹只鸡。","古来贤豪遇合有迟早，其中不遇亦岂少。","遇则堪为帝者师，不遇但为蓬蒿老。","君不见唐时宰相张公镐。"]},{"t":"黄叶歌","f":"七言古诗","c":["严霜凛冽天泬漻，调调刁刁风怒号。","感兹黄叶歌且谣，黄叶未黄重阴交。","脱离根株随所遭，黄叶欲下风欲高。","旋看坠地旋青霄，风叶相激声萧骚。","此时孤客正寂寥，四海无著东西飘，怀乡倍觉关山遥。"]},{"t":"送艾明德入都","f":"五言律诗","c":["曾说君西去，初闻不作真。","徵车明在眼，别酒暗伤神。","愁极今谁侣，贫同独尔亲。","临歧重把袂，琐屑问回轮。"]},{"t":"雨后山行","f":"五言律诗","c":["宿雾收林薄，探幽兴不违。","过桥通蟹舍，卓杖立渔矶。","疏雨洒山麓，野风吹葛衣。","看云閒出岫，踽踽欲忘归。"]},{"t":"山雨","f":"五言律诗","c":["远峰深翠里，隐隐起轻雷。","石气蒸云上，山风挟雨来。","乱流争涧落，栖鸟破烟回。","明月东冈出，披襟坐钓台。"]},{"t":"孤雁","f":"五言律诗","c":["云路谁相导，先群众所推。","将飞行忽断，欲落意还疑。","影只惊弦及，霜寒奋翼迟。","阳回神自旺，高举迥难追。"]},{"t":"怀李廌青山居","f":"五言律诗","c":["邂逅盘阴叟，旋生栖隐情。","爰居惊海祀，黄鹤耻轩荣。","已沐烟霞久，悬知身骨轻。","高踪惭沮溺，结耦事躬耕。"]},{"t":"秋蝉 其一","f":"七言律诗","c":["秋来偏尔独知机，几处寒声咽落晖。","云树若愁时渐晚，市廛虽到迹仍稀。","但餐清露宁求饱，偶得閒枝欲罢飞。","节操如君何太苦，稻粱生性已全非。"]},{"t":"秋蝉 其二","f":"七言律诗","c":["清风凉露忽成啼，林远烟深望欲迷。","黄叶空山秋色里，断桥古渡夕阳西。","声闻已接犹难见，地步宁藏不肯低。","听汝去年曾醉后，黉宫松畔亦留题。"]},{"t":"偕同人过蔚千看荷","f":"七言律诗","c":["照眼花光露未乾，拂云槐荫覆杯盘。","世情多为荣枯累，吾辈从来礼法宽。","北海高风宾座满，炎天六月草堂寒。","十洲三岛谁能到，对此林塘足尽欢。"]},{"t":"哭陈石闾","f":"七言律诗","c":["北宋南施次第推，百年风雅久虺隤。","不从隆古争雄长，谁信文坛有霸才。","紫气虚瞻函谷尹，大招频上郭生台。","谩言三老辽东旧，郢技空存质已摧。"]},{"t":"东冈二章章十句","f":"古风","c":["东冈月出，照我薄衾。","商飙凛冽，蟋蟀哀吟。","中怀悒郁，起抚鸣琴。","一弹再鼓，悲弗成音。","明发不寐，涕泗沾襟。","东冈月出，照我北林。","关山阻修，江湖迥深。","云鸿孤往，过我檐阴。","持此远慕，托寄好音。","迅飞不息，伤哉我心。"]},{"t":"腊月四日六章","f":"楚辞体","c":["岁聿其暮，月届嘉平。","嘉平四日，曰为余生。","元阴蔽野，皓雪盈庭。","谡谡其风，有室如冰。","翳忽不乐，潸然涕零。","鱼亦有渊，鸟亦有陵。","以游以泳，载飞载鸣。","我来自东，孑然其形。","岂无他人，莫往莫迎。","父兮母兮，罔极深恩。","嗟余行役，倚闾倚门。","缅怀兄弟，朝烟暮云。","妇叹于室，子甫能言。","自我不见，于今三年。","静言思之，奋飞不前。","安得美酒，烦襟涤蠲。","有客叩扉，倒衣出迎。","左手提榼，右手携罂。","入门再拜，一举十觥。","十觥不辞，用感君情。","对酒高歌，君其我听。","人生几何，鲜满百春。","倏如蜉蝣，忽如飙尘。","既倏既忽，终窭且贫。","况在天涯，欢会岂频。","我思古人，熊经鸟申。","其生也劳，其死也均。","尔酒既旨，我饮如鲸。","且饮且醉，颓然欹倾。","不矩有死，焉知有生。","生死两忘，悲乐俱冥。"]},{"t":"立春闻雁","f":"古风","c":["伊兹春始，馀寒未融。","有雁哀鸣，过我房栊。","岂避南暄，眷此北风。","静言思之，似罹罦罿。","惊弦既脱，栖息靡踪。","提提鸒斯，载西载东。","维鹊有巢，亦以禦冬。","凡鸟有托，尔独孤穷。","我闻其声，翘首长空。","瞻望弗及，忧心有冲。"]},{"t":"高堂三章章八句","f":"古风","c":["建彼高堂，爰求豫章。","干霄踞地，为栋为梁。","为榱为楹，众材斯张。","秩秩其臧，大厦煇煌。","崇阶峻宇，碧瓦朱甍。","其正其冥，乃寝乃兴。","以延似续，以燕嘉朋。","钟鼓既设，鬼神其宁。","厥基既固，厥貌复恢。","哙哙哕哕，不崩不摧。","反是弗思，或倾或颓。","既倾既颓，追也可回。"]},{"t":"李徵君虚斋九十初度四章章八句","f":"古风","c":["鹤鸣于天，鱼跃于藻。","有美一人，冰雪在抱。","缟衣茹藘，于尘之表。","我欲觏之，蒹葭缥缈。","南山在宇，源泉在户。","税驾东郊，遵彼畎亩。","课我农人，欣觇禾黍。","非力不食，安兹乐土。","衡门之下，有书有琴。","爰居爰处，载鼓载吟。","天地其庐，万类其襟。","山高出云，庶几遐心。","优游泉石，九十其年。","云诡波谲，变历万千。","唯兹高蹈，德音不迁。","既寿且康，以笃后贤。"]},{"t":"山东朱中丞同年母程太君八十四寿","f":"古风","c":["麟游盛世，凤哕高冈。","造物所钟，邦家之光。","岂无其自，源远流长。","我公秉钺，惠厥海疆。","溯德唯旧，实由义方。","稽古贤媛，孟母共姜。","伊我太君，懿轨同芳。","秀毓名阀，性秉和良。","兰馨蕙馥，冬月秋霜。","嫔我太翁，琴调瑟张。","陈椒谢絮，歛藻韬光。","同善相勖，同患相将。","孝严寝膳，勤戒翱翔。","偕隐泉石，追踪孟梁。","诞生夔契，梦叶嘉祥。","盐梅舟楫，辅我陶唐。","八旬有四，既寿且康。","芝兰竞发，绕膝琳琅。","欣兹春茂，嘏祝遐昌。","纶诰自天，恩覃华堂。","钦承莱舞，锡福未央。","兴言述德，歌以侑觞。"]},{"t":"安化寺刻竹诗八章章四句","f":"楚辞体","c":["苔光瑩瑩，云影皑皑。","高窗雨过，落花飞来。","雨霁云沈，天光侵户。","趺坐观空，游心太古。","熏风书炎，飘萧疏雨。","日之夕矣，差池月宇。","清风荡飏，飒然襟开。","白云不去，幽鸟时来。","闇闇孤丛，落落禅宇。","载阴载晴，唯我与汝。","浓露零兮，林枯山老。","时兮奈何，青苍独保。","高节嶙峋，葆汝天兮。","霜风凛冽，吹汝寒兮。","尔心虚兮，德不尔孤。","尔节坚兮，时宁尔渝。"]},{"t":"人禽歌四章 其一","f":"楚辞体","c":["天地絪缊兮一气孔蒸。","肖厥形兮绳绳。","为龟麟兮为鸮鹰。","随大化兮生成。"]},{"t":"人禽歌四章 其二","f":"楚辞体","c":["龙飞潜兮咸知其灵。","人变化兮孰如其能。","为鸮为鸾兮此情。","龙之灵兮其形。"]},{"t":"人禽歌四章 其三","f":"楚辞体","c":["天局形兮心我操。","奴于物兮徒劳。","居有室兮禽有巢。","补葺缺兮风飘飖。"]},{"t":"人禽歌四章 其四","f":"楚辞体","c":["气备万物兮称人豪。","地并厚兮天争高。","随波流兮断蘋飘。","少壮几时兮岁月其慆。"]},{"t":"拟曾晰莫春唱答歌六章 其一","f":"楚辞体","c":["风和煦兮水容与。","偕童冠兮行蘧蘧。","万物得所兮吾亦乐吾初。"]},{"t":"拟曾晰莫春唱答歌六章 其二","f":"楚辞体","c":["春风融融兮沂水洋洋。","高天厚地兮供我相羊。","何思何虑兮与时偕行。"]},{"t":"拟曾晰莫春唱答歌六章 其三","f":"楚辞体","c":["物无心而成化兮觉天地之无私。","纷欣欣而茂育兮身亦游于化机。","人害匪徒兮地害匪宜。"]},{"t":"拟曾晰莫春唱答歌六章 其四","f":"楚辞体","c":["冠兮童兮浴且风兮。","夫何求兮与天游兮。"]},{"t":"拟曾晰莫春唱答歌六章 其五","f":"楚辞体","c":["群适其时兮余将奚待。","唐虞事业兮于焉斯在。"]},{"t":"拟曾晰莫春唱答歌六章 其六","f":"楚辞体","c":["望衡门兮日熹微。","随杖履兮归来。","琴瑟在御兮且鼓且嬉。","世莫我知兮将上质乎皇羲。"]},{"t":"岁暮歌三章 其一","f":"楚辞体","c":["若有人兮在山椒。","衣云锦兮佩琼瑶。","持芳芬兮犹豫，将谁赠兮心烦劳。","太息兮遐睇，路漫漫兮山嶕峣。"]},{"t":"岁暮歌三章 其二","f":"楚辞体","c":["若有人兮在山阴。","葛藟累兮石崎嵚。","阴阳摧兮岁暮，风萧萧兮猿狖吟。","皋兰萎兮不馥，谁余慕兮深林。"]},{"t":"岁暮歌三章 其三","f":"楚辞体","c":["若有人兮在山麓。","飘风发兮陨草木。","陟椒邱兮不返，高余冠兮被初服。","庸愚乐兮贤心悲，不我知兮谁告。"]},{"t":"圣人出","f":"古风","c":["圣人出，泰阶平。","麟凤来，川岳灵。","万汇昌，百谷登。","雨旸时，四海宁。","朝廷肃，牧守明。","蛮夷宾服，稽首殿庭。","刑罚省，赋役轻。","井里亲睦如弟兄。","上有政，下有情。","庶政熙，众情倾。","风俗美，治功成。"]},{"t":"君子行","f":"古风","c":["有玉者错，有刀者砻。","不错不砻，谁贳为功。","田甫田，莠乔乔。","思远人，心忉忉。","逐情欲，入禽门。","猎道义，躏圣藩。","贿玷精，乏易计。","境能移，实自弃。","倚孔门，弹卫章。","衣未成，转为裳。","弗捐弗壹，弗钻弗出。","一矢两禽，左右俱失。","弸其中，彪其外。","能则荣，否则败。","铸金铸人，孰贱孰尊。","宏深肃括，可以褆身。"]},{"t":"芳树","f":"古风","c":["桃李不言，下自成蹊。","中有芳树，众木生疑。","疑尔花不当春，叶不因时。","轮囷古干背绳尺，安知尔抱中心奇。","芳树之芳，众木之防。","芳树不芳，芳树之常。"]},{"t":"临高台","f":"古风","c":["临高台，豁双目。","心多忧，悲还续。","云敛长空雪销谷。","海不扬波，山升朝旭。","仰穹苍，俯众族。","喙息跂行，芸生并育。","有鹤苦饥，孤飞野宿。","天风四吹，哀鸣若哭。"]},{"t":"东门行","f":"古风","c":["出东门，慨以叹。","年如矢，去不还。","壮盛已过，出入无欢。","白日昭昭，不照游子颜。","雪霜悽怆漫荒原。","鸟无翼，河无船。","甘随草木，俯首凋残。","嗷嗷八口号寒饥。","赁舂作苦精力衰。","颓纵有所获难餔，糜思远出竞刀锥。","天黯惨，日西垂。","儿女罗列，跪奉一卮。","欲饮未饮心酸悲。","平明就道，妻子牵衣。","啼悯我老，问我将何之。","山有豺虎，水有蛟螭。","征途况瘁骨肉违。","安危莫测，魂梦惊疑。","男儿结志山不移。","邪赢秽窦圣所非。","遵古道以寻路，将安往而不迷。","停旅橐，解征衣。","从今以后，无复别离。","生相慰，死相依。"]},{"t":"远游篇","f":"古风","c":["天路高，不可步。","河水深，不可渡。","陇首飞云变朝暮。","冬采薇，日苦饥。","被败絮，难为衣。","风雨飘飖室将颓。","茫无策，告母将远之。","母谓儿，懦儿去，当告谁。","儿谓母，老母当自保持。","莫我儿，长苦思。","强欲无悲，悲不自知。","愁颜憯憯，清泪漓漓。","呼兄嫂与妻。","同至母前，且嘱且辞。","欲语未及发，气结声惨悽。","怀中黄口小儿闻父去，仓皇释乳握手牵衣。","举家哀哀号泣，刺骨煎脾。","知君此时难别离。","出郭门，路多歧。","行迟迟，中心悲。","道逢坎险，车怠马罢。","山鬼夹路，猛虎纵横来。","我肉瘦，虎腹饥。","山鬼迷人，忽笑忽啼。","仰天叹，发浩歌。","拯我者少，啖我者多。","茕茕孤客将奈何。","乱曰：思故乡，书断绝。","念慈帏，心碎裂。","清漏沈沈泪成血。"]},{"t":"战城南","f":"古风","c":["战城南，城南烽火促。","两锋相接鼓声死，将军帐前鬼夜哭。","锦衣朱襮，饮酒食肉。","生受国恩，甘殉溪谷。","我岂不同仇，我实不谷。"]},{"t":"长城歌","f":"古风","c":["猛虎肉，人可尝。","壮士心，不可伤。","猛虎虽猛犹能缚。","壮士心伤大难作。","君不见陇上夫，释耰锄。","斩棘荆，奋臂呼。","嬴秦宗社成荒芜。","长城筑怨非良图。"]},{"t":"饮马长城窟","f":"古风","c":["朝饮马，暮饮马，朝朝暮暮长城下。","长城秋高月色昏，哀笳吹月愁云屯。","阴风黯惨低不散，中有万古征人魂。","秦皇汉武勤远略，百万健儿委沙漠。","白骨纵横化鬼燐，尸尸闪闪惊羁魄。","封侯之愿久已灰，父母妻儿生死疑猜。","登高望，隔黄埃。","但闻窟中水呜咽，水流尽是当年血。","欲哭不成声，肝肠已寸裂。"]},{"t":"陌上桑","f":"古风","c":["执懿筐，遵微行。","掺掺女手，爰采柔桑。","桑萎蚕馁心徬徨。","蚕成茧，缫沸汤。","缫丝白，白于霜。","凭君染赤染黑染青黄。","蚕在釜中泣，唯愿天下黄耇台背，安且燠，无冻伤。","王侯贵介，衮衣绣绂，佩玉鸣珰。","威仪秩秩相煇煌。","纵死鼎镬职所当。","念之哉，勿但供娈童嬖媵，逞丽质，斗鲜裳。","吴歌楚舞断人肠。"]},{"t":"君马黄","f":"古风","c":["君马黄，臣马苍，臣马不如君马强。","君马强，臣马良，君马追风籋雷电，臣马低头蹀躞身摧藏。","身摧藏，背高价，绝足能，老枥下。","执辔如繻，载驰载驱。","越陌度阡，中有崎岖。","遵轨道磬控在手，骐骥驽骀皆善走。"]},{"t":"箜篌引","f":"古风","c":["不鼓雍门琴，不学牛山啼。","当尊歌慷慨，一曲箜篌词。","滔滔江汉水，东逝无还期。","少壮几日，倏忽衰颓。","人无贵贱，今古同悲。","翘首望神仙，精魂天外驰。","天风飘飘空中起，吹我蓬莱山之涯。","道经紫泥海，海水沾我衣。","欲往虞渊沐，日莫空迟疑。"]},{"t":"古别离","f":"五言古诗","c":["大义联夫妇，恩情岂中移。","既生亦已育，劳瘁妾所宜。","指天发明誓，皓首以为期。","新人颜如花，婉转扇微讥。","怜深情易入，听之甘如饴。","昔为比翼鸟，今为浊水泥。","水浊无时清，弃捐从此辞。","辞郎顾郎面，泪落眼中迷。","分明结同心，胡为永分离。","但言妾薄命，不怨郎乖违。","有始鲜克终，谁能不如斯。","百年金石交，各贵自保持。"]},{"t":"车遥遥","f":"古风","c":["车遥遥，将安之。","遵轨度，防倾危。","日易暮，仆夫颓。","人但见燕羽捷于凤翼，狐跃超乎麟驰。","岂复知舆行陆舟行溪，空则疾，重则迟。","车遥遥，将安之。"]},{"t":"野田黄雀行","f":"古风","c":["黄雀，黄雀，躯命何微。","田中水阔，无粟无乾泥。","黄雀饥，绕树啼。","黄雀栖，霜雪摧。","随风飘泊，忽东忽西。","瞥见大屋，屋底囷鹿累累。","黄雀下来，网罗高施。","雀飞投罗，宛颈低垂。","哀哀乞告罗者，我实苦饥。","苦饥奈何，我命当危。","饥不择食，我罪当治。","唯矜唯恤，仁者当念之。"]},{"t":"陇头歌","f":"古风","c":["陇头水，流汤汤。","疑是洪荒万古之血泪，流向边庭流不止，遂令征戍至今。","听此心恻伤。","心恻伤，心欲折，单于高台望明月。","明月台端思故乡，寒声傍耳偏呜咽。","拔刀割断胸中悲，蹲身磨洗刀头血。","刀头凝寒飞雪霜，雌雄誓向沙场决。","共道封侯骨相奇，水浑照面生猜疑。","慷慨向前去，吉凶非所知。","君不见汉家开边三万里，卫霍肤功照青史。"]},{"t":"陇头水","f":"古风","c":["陇水汤汤，塞草茫茫。","登高远眺，孤云南翔。","眷彼孤云，泣下沾裳。"]},{"t":"钓竿","f":"古风","c":["钓竿何修修，施于东海头。","巨鳞如山岳，乘风渡洪流。","岛屿深阔不可以垂钩。","沄涛荡激不可以方舟。","吁嗟乎，奈之何。","或谓夜光之珠，潜于灵蛇。","珊瑚木难，照耀金沙。","耸身濡首，珍宝盈车。","失身不测，徒虚誇吁。","嗟乎奈之何，若木生海东，丹水发其荣。","群真上下骖鸾龙。","千年如旦夕，至乐无终穷。","吾欲遇之将奚从。","吁嗟乎，奈之何。"]},{"t":"行路难","f":"楚辞体","c":["岂不知行路难，胡为乎复远适。","父母妻儿，欲留不住，泪下渫渫声悲恻。","人无贤不肖，出世皆有营。","多为饥所驱，遂使身命轻。","经历山陂，人困马饥。","虎豹来狰狞，舑舕忿怒纷攫持。","此时车不得转，力不得施。","仓皇却走，道逢故识，愿借尔力，导我出危。","急言未竟，掉臂疾趋。","欲语不相及，局蹐山坳，西日将颓。","林木深黑，中不可知。","秣吾马，膏吾车。","遵寻旧路，返我故时庐。","返故庐兮发长歌。","人生苦行役，世路多砍砢。","归来兮归来，安义命兮守岩阿。"]},{"t":"关山月","f":"古风","c":["关山月苦，如雪如霜。","照我羁人，憯憯心伤。"]},{"t":"门有车马客","f":"古风","c":["门有车马客，来自万里途。","峥嵘百宝装，昂藏双龙驹。","腰悬辘轳剑，兜辉明月珠。","入门惊四座，气宇凌九区。","问客何所能，问客何所求。","客亦无所能，客亦无所求。","但伤尘壒内，斯人无时休。","一朝意气尽，白骨堆荒丘。","蛆蜹穴枯腊，妖狐窃髑髅。","游魂苦无依，阴雨时啾啾。","谁解养玄关，而将奇龄修。","东海蓬莱山，五城十二楼。","上有飞仙居，吾曾与之游。","授我延年术，教我守中枢，专气而致柔。","阳昌阴魄，消缘督转，玄机渊镜恒内留。","得一万事毕，金水分恩雠。","天人互相盗，灵苗结县旒。","虚室渐生白，皓月当清秋。","神与太虚盟，形与元化谋。","万感斗其心，相刃复相劘。","鬼伯入虚舍，遂受阴阳欺。","生死操方寸，端倪尔自知。","再拜受秘箓，拳拳中藏之。","大道贵丧我，吾将祛滑疑。","安能同混浊，甘为异类摧。"]},{"t":"薤露","f":"古风","c":["薤上露，薤露何易晞。","歌钟未歇，倏忽悲啼。","骷髅作人语，欢乐不可以久稽。","鬼伯歛魂，苦难暂违。","汲汲将奚为。"]},{"t":"蒿里","f":"古风","c":["里中蒿，蒿已齐。","啾啾唧唧鸮夜啼。","鸮声悽，人心悲。","雪霜惨惨，萧苇离离。","生不能生，死复何追。"]},{"t":"莫打乌","f":"古风","c":["莫打乌，乌生八九雏。","巢中唧唧饥哀呼。","乌遭铩羽，众雏何辜。","莫打乌，乌能反哺人不如。","忘勤劬私妻孥，父母老病羁孤。","腹充粗粝，体无完襦。","儿则衣狐，白乘坚车。","朋从狎辟，陆博樗蒱。","归来醉饱，妻妾子女相欢娱。","父母求衣索食，言语龃龉拂袖去。","气结不语，展转长嘘。","莫打乌，乌能反哺人不如。"]},{"t":"妾薄命","f":"五言古诗","c":["乾坤钟灵秀，绝代产殊色。","容光竞明月，兰蕙萃为饰。","扎扎弄机声，文锦光击射。","怀贞不肯字，惧无萧史敌。","老父爨下炊，母借邻灯织。","拮据日不遑，不克谋朝夕。","妾心怆以摧，养女不得力。","含羞信蹇媒，情因菽水迫。","良人同此心，一身何足惜。","吁嗟轻薄儿，嘻游狎便辟。","锦衾遗巧笑，好逑而摈斥。","膏沐为谁施，幽房常局蹐。","展转不能寐，瑶琴怨终夕。","琴声一何悲，心伤柱促激。","既不成婚媾，又远去亲膝。","身心两不遂，悢悢不能抑。","明月照我怀，挥泪长叹息。"]},{"t":"爱妾换马","f":"五言古诗","c":["郎若空中云，变幻在倏忽。","妾若阶前草，去留从所欲。","自顾倾城姿，娇贵比珠玉。","蓄愿配君子，贮之黄金屋。","贞一誓死生，没齿以自勖。","岂谓他人心，视之如贱畜。","信誓方旦旦，弃蠲一何速。","讵忍千金躯，复受骊黄目。","捐生谢主人，此身难再辱。"]},{"t":"登高丘而望远海","f":"古风","c":["登高丘，望远海。","三神山，海中峙，长生大药竟何在。","安期生，羡门子，我从尔游，尔应我待。","情已奔，忧还起。","自顾顽劣躯，得无遇君君不礼。","波涛荡潏，陵麓施靡。","灵槎茫茫，引颈延伫，不知奚舣。","猿鸟啼风树凄其，窅冥西日颓，仙乎仙乎我心悲。"]},{"t":"杂咏 其一","f":"五言古诗","c":["炎精始隆赫，玄阴朕已萌。","圆魄丽中天，隔宿分亏盈。","斯理判洪荒，今古递相更。","神人握芦筦，寒律吹忽暖。","黔羸让其能，三五遂不远。","优游乘化机，升沈自流转。"]},{"t":"杂咏 其二","f":"五言古诗","c":["鸿钧旋大运，至道推隆古。","危微凛唐虞，胼胝亲神禹。","万类跻春和，一身何太苦。","所以耄倦勤，思以让天下。","许由抱幽贞，虚名何所取。","劳逸道且分，飘然问仙侣。"]},{"t":"杂咏 其三","f":"五言古诗","c":["一身劳万姓，万姓奉一身。","齐晋递争霸，今古判然分。","憸民一堕地，造物弛其权。","谋生计百出，奔趋各不閒。","吁嗟缝掖子，宁不苦饥寒。"]},{"t":"杂咏 其四","f":"五言古诗","c":["岁月忽已徂，鶗鴂相悲鸣。","霜霰作严寒，繁华伤伶俜。","美人隔云端，怅望驰远情。","光彩缅中夜，惝恍朝玉京。","精霸召玄感，鸾鹤骖群灵。","灿然启玉齿，含笑相逢迎。","钧天闻广乐，环佩解瑶璚。","授以不死药，一粒千万龄。","世罕冲霄骨，焉能测渊冥。","宝箓示不识，酣饮终馀生。"]},{"t":"杂咏 其五","f":"五言古诗","c":["高人无近情，仙灵多变化。","鉴别分高卑，器量难强加。","崔生冀冲举，白蜺忽委□。","亲手授丹药，惊怪挥长戈。","昭昭望天路，白日倏已暮。","大鸟飞不还，觌面空成误。","庸碌何足言，深为奇士怜。"]},{"t":"杂咏 其六","f":"五言古诗","c":["三月储刍粮，驾言适万里。","资斧竭中途，远道行将已。","熠耀散宵光，鼓翼亦自雄。","金气一朝至，零落随飘风。","所嗟躯命微，不复历春冬。","神鲲图南溟，谁能测始终。"]},{"t":"杂咏 其七","f":"五言古诗","c":["高楼临大路，上有妖冶子。","丽色耀朝阳，新妆何斐亹。","巧笑启朱唇，娇歌灿玉齿。","当筵试舞衣，纤腰矜旖旎。","东风吹芳菲，纷纷落红蕊。","红蕊落春前，徘徊怨罗绮。","长夜垂空帏，耿耿情缄髓。","讵知与士耽，弃蠲从兹始。"]},{"t":"杂咏 其八","f":"五言古诗","c":["贾胡利美珠，深藏剖其肤。","怀宝未及售，身命已先徂。","缅彼蓬藿士，终岁栖绳枢。","富贵等浮云，所乐非世图。","身贫遭鄙贱，蔑视如泥涂。","谁知百年后，名与天地俱。"]},{"t":"杂咏 其九","f":"五言古诗","c":["椅桐百尺柯，鸾凰资其实。","蓬藿灿枝条，当秋乃萧索。","寒暑更相递，岁月一何迫。","人生日不遑，终焉将奚得。","蓬室岂无谋，所宝非金璧。","百年会当尽，荣枯唯自植。"]},{"t":"杂咏 其十","f":"五言古诗","c":["螭珠晦其光，贾胡目亦盲。","青萍韬其锋，薛烛鉴亦穷。","被褐杂驵侩，谁知为韩康。","生意汨严寒，枯荄茁春阳。","蓄德贵玄同，迷阳乃无伤。","光芒众所指，跃冶惊不祥。","虽有万镒珍，用之何能臧。"]},{"t":"杂咏 其十一","f":"五言古诗","c":["进退能自权，道重身亦安。","鄙夫患得失，灾祸乃相干。","神龟曳其尾，泥涂甘自委。","迹远庙牺荣，所处无悲喜。","蜻蛉游天地，飞飞无已时。","胶饴一朝调，遂为童子欺。","贪者或不察，旁观尔应知。"]},{"t":"感怀 其一","f":"五言古诗","c":["西风夜作声，游子不能寐。","揽衣起徬徨，泪下沾衣袂。","黄叶坠高枝，蟋蟀鸣前墀。","玄阴结重霭，白月沈幽辉。","菁华暗销铄，所苦不自知。","良辰忽已晚，皓首含酸悲。"]},{"t":"感怀 其二","f":"五言古诗","c":["灿灿星河水，皦皦天衢月。","纵横不断流，盈亏何太疾。","碌碌淹恤子，奄忽成白发。","人生非草木，安能任枯茁。","神玥扼龙颔，奇翚探凤穴。","持此希世珍，冀邀美人悦。","缄袭历险艰，中道伤跛蹩。","跂足望所思，眷恋生悲凄。","惭彼鸾鹤侣，高骞厉羽仪。"]},{"t":"感怀 其三","f":"五言古诗","c":["初日照高楼，桃李争鲜妍。","皦皦彼姝女，挟瑟侍春筵。","流睇荡人心，顾盻自生怜。","佳人耻行觞，双手裂华裳。","甘心被麻葈，凛凛天雨霜。","霜寒岁云暮，玉颜增芬芳。","妖冶离为容，恻然为悲伤。"]},{"t":"感怀 其四","f":"五言古诗","c":["良冶铸吴钩，爱子投红炉。","器成不见宝，冤魂鸣呜呜。","精诚召神鬼，谁知此器殊。","匣中倚天剑，雌雄乏真鉴。","风胡去不还，锋锷长惨淡。"]},{"t":"感怀 其五","f":"五言古诗","c":["金蚕食柘叶，肝肠成五色。","吐丝制文锦，光辉相击射。","裁为绂衮裳，杂佩鸣珠璧。","被之可彰身，献之可华国。","金蚋一朝来，奄忽遭污蔑。"]},{"t":"感怀 其六","f":"五言古诗","c":["晨风扬北羽，秋鸿思南飞。","微生感虫豸，栖息各有归。","茫茫望四海，此身何所依。","岁月不我留，展转伤支离。","瑶琴膝上横，瞧杀激哀鸣。","初弹行路难，再弹冰雪凝。","移商忽变徵，狸首残其形。","飒然起风雨，黯惨天地冥。"]},{"t":"感怀 其七","f":"五言古诗","c":["矫矫海东青，奋翼思飞鸣。","出门铩羽翰，䙰褷非故形。","高骞阻云汉，雌伏悲巢倾。","风雨时见欺，众雏随飘零。","天地大无私，岂独遗生成。"]},{"t":"感怀 其八","f":"古风","c":["??云中鸿，唧唧窗下蛩。","招摇西北指，乃知岁将终。","遐情凌嵩华，客路伤飞蓬。","飞蓬逐旋飙，飘飖何所穷。","睍睆鸣春禽，奋翮腾高岑。","栖托既得所，安念昔同林。","已矣复奚求，金石皆虚浮。"]},{"t":"感怀 其九","f":"五言古诗","c":["神蛾吐冰丝，缭绕七朱弦。","琼玖排雁柱，金石激龙唇。","猗兰闻白雪，流风中缠绵。","太古留逸响，可以格神人。","阳春气不和，四壁阴风寒。","终日不成音，仰首坐长叹。"]},{"t":"感怀 其十","f":"五言古诗","c":["冉冉茑萝丝，煇煇丽乔木。","委身答蹇脩，谐和拟琴瑟。","弦柱一朝离，徽音中断绝。","白日不照颜，膏沐为谁设。","蓬首却婉娈，新妆工磬折。","芳兰杂众草，朱蕤覆霜雪。","馀香袭衣裾，幽情聊自悦。"]},{"t":"拟古","f":"五言古诗","c":["皦皦牛女星，东西隔明河。","跂足不能前，终岁长咨嗟。","金气障天路，停梭怨霜露。","纤腰濯凉飔，玉颜亦应故。","杂佩纫崇兰，飘飖飏云端。","怀芳散罗绮，馀香落尘寰。","幽思结襟带，长夜不能寐。","顾影自徘徊，持情空相待。"]},{"t":"古意二首 其一","f":"古风","c":["见郎真欲去，郎去携郎手。","问郎几时归，郎去念侬否。","灼灼桃李花，翩翩堤上柳。","去去日以疏，逐处留人久。","双泪从此枯，瘦骨?速朽。","任郎归不归，终当为郎守。"]},{"t":"古意二首 其二","f":"五言律诗","c":["嘉树郁中庭，上有双栖鸟。","好音相和鸣，飞止狎昏晓。","念子不能归，沈忧令人老。","岂乏欢娱场，日令颜色好。"]},{"t":"都门冬夜","f":"五言古诗","c":["惨雪失昏昼，慄烈冱乾坤。","朔风震陵莽，猎猎惊征魂。","朱火凝兰膏，重衾夜无温。","羁绪结悽怆，泪下声忽吞。","客身岂不惜，深怀罔极恩。","燕市寒如此，绝塞何堪论。","寄裘苦无资，况久缺鸡豚。","人生七十稀，宁不念晨昏。"]},{"t":"春望","f":"五言古诗","c":["陌上杨柳枝，几见春牂牂。","陟岵望白云，白云缈茫茫。","樊笼日苦羁，念之心忽伤。","螴蜳竟何成，心旌空中扬。","徘徊重徘徊，凄然泪沾裳。"]},{"t":"秋怀七首 其一","f":"五言古诗","c":["少昊司清秋，炎尽岁忽移。","清露结严霜，山山红叶垂。","黄鹄翔万里，寒鸟鸣追随。","四时更代谢，盈虚理亦宜。","耿耿抱隐忧，驰情茫所之。"]},{"t":"秋怀七首 其二","f":"五言古诗","c":["壮游适燕赵，绮丽相竞逐。","宝马灿金珠，纤罗杂露縠。","冶容耀春华，新声奋竹肉。","博欢竭妩媚，欢情岂终一。","嬖男不敝舆，嬖女不敝席。","色衰爱亦弛，劳瘁终何益。"]},{"t":"秋怀七首 其三","f":"五言古诗","c":["白石何凿凿，苍松何历历。","吁嗟世上人，崇朝不谋夕。","安能抱一经，终岁长局蹐。","高踞要路津，咳唾惊霹雳。","天威下严霜，须臾不可测。","华亭鹤唳悲，黄犬安可得。","膏明长自煎，泉甘每先竭。","何如保良贵，千秋谁复易。"]},{"t":"秋怀七首 其四","f":"五言古诗","c":["豕鬣虱所安，豕俎虱亦随。","荣华有憔悴，此义终告谁。","茂林阴且重，群鸟相因依。","秋风拔其根，歛翼各分驰。","所伤在缯弋，奋翮不能飞。","斯时富贵子，何如贫家儿。"]},{"t":"秋怀七首 其五","f":"五言古诗","c":["寒风吹广漠，白日忽西颓。","阴云起重阿，圆景暗无辉。","中夜聊行役，行行将何之。","高楼连大厦，击鼓吹笙篪。","鸣鸠偕旅燕，高栋相追飞。","吁嗟穷经子，宁不寒与饥。","烈士多悲心，发文每新奇。","恕己谅同志，谁能不如斯。","抱瓮徒自苦，桔槔心所非。","忘机憩蓬荜，海鸥谅不疑。","夙慕讵不卓，明发系吾思。","捲舒宁自必，此身权所持。","瑾瑜唯自保，积久贵不衰。","志士穷得已，遭遇安天时。"]},{"t":"秋怀七首 其六","f":"五言古诗","c":["天马产渥洼，累世偶一出。","云泼五花纹，权奇耸异骨。","驯德堪死生，风蹄追落日。","昭王筑金台，千金价空设。","散辔卧荒原，哀鸣震林樾。","岂慕驽骀荣，但伤知者汨。"]},{"t":"秋怀七首 其七","f":"古风","c":["神鹏高摩空，背负青冥游。","列宿充饥肠，银河饮不流。","千年一脱羽，瞬息八垓周。","四海等蹄涔，五岳如荒邱。","大物有大年，将与造化俦。","安能徇?鴳，下与蓬蒿谋。"]},{"t":"母病","f":"五言古诗","c":["伊昔生我时，家室遭颠倒。","我父罹祸罗，我母誓不保。","仓卒就长途，亲知惨避悄。","余生甫二月，仲兄年周小。","路险虑活难，存婴费襁褓。","谋夺乘危机，纷纭甜言巧。","曲折转柔肠，欲舍心懊恼。","怀幼仲卧膝，病弱声微渺。","车中严戒约，动息愁惊搅。","憔悴抵贞番，黄沙抱荒草。","家乡梦暂归，魂断哀笳绕。","永夜坐长叹，月苦霜天晓。","绝域无亲知，饥寒向谁道。","更遇年岁凶，沟壑转瘠殍。","力谋死中生，糟糠延昏早。","饥困不得乳，沿求向邻媪。","求之日以频，邻媪厌烦扰。","儿哭母亦啼，儿饥母岂饱。","手作口复哺，百计望儿好。","此事幼不知，长听心如捣。","欲报昊天恩，诗书奋雠讨。","寒灯敌塞雪，情奔忘集蓼。","一檄捧可干，冀亲长寿考。","昕夕力不辍，摛词渐古藻。","初试录黉宫，再试贤书标。","三试擢礼闱，声名振矫矫。","自分亦英奇，立可申怀抱。","事竟与愿违，羁愁若笼鸟。","三年饿病危，归省贫如扫。","感叹复欷歔，儿成母亦老。","四体抱病疴，骨立颜枯槁。","省问儿心伤，沈痛迫中肠。","含悲诘良医，蔘苓宜服长。","蔘价贵如珠，且复无私藏。","听之不能语，涕泪满衣裳。","医问余何悲，欲答心怆惶。","菽水且莫饱，安冀母病臧。","人生能几时，白日行天忙。","亲老不能养，亲病弮空张。","吁嗟不肖身，何以齿周行。"]},{"t":"鸿濛 其一","f":"五言古诗","c":["鸿濛辟大道，万类转贞元。","天地与螾蚁，劳劳局形神。","巨细虽悬殊，受造亦以均。","寄身泱漭中，藐焉杂众伦。","两间为我用，万物备一身。","始知维皇意，设局为斯人。"]},{"t":"鸿濛 其二","f":"五言古诗","c":["大道超形声，天地亦渣滓。","幽居谢人事，澄虚窥至理。","菁华具灵明，生机梏经史。","湛然绝外缘，天怀契无始。","仁义窃虚名，翻为庸碌耻。"]},{"t":"鸿濛 其三","f":"五言古诗","c":["违时多不祥，径情每弗惜。","造物与我雠，动即遭颠阨。","似欲驱之返，使蹈众行迹。","百折死不回，鬼神愕无策。","严酷缓我攻，暄燠回朝夕。","脂韦空辱身，反若喜我逆。","始知司命者，砺之成金石。"]},{"t":"鸿濛 其四","f":"五言古诗","c":["修名众所趋，造物每深忌。","今古无幸邀，终有物败弃。","桃李艳春花，苔藓延秋砌。","飘飖风雪交，奄忽伤憔悴。","所以贤哲人，孳孳唯自励。","天命变崇朝，人心求万祀。"]},{"t":"训士吟 其一","f":"五言古诗","c":["北方有潜客，性嗜兰蕙姿。","培根复诛蔓，汲清灌溉之。","吐芳出群卉，岂曰国香衰。","顾兹桂与茝，将随九畹滋。","枝叶峻以茂，采撷冀及时。","奉为君子佩，连茹以为期。"]},{"t":"训士吟 其二","f":"五言古诗","c":["野鹤失云侣，日暮各孤飞。","随风无定羽，栖息意何依。","彩鸾振六翮，高踞琼树枝。","璚树茂且崇，众鸟忘所归。","归飞托深荫，此荫谅不衰。","持此固绸缪，绸缪安可迟。"]},{"t":"训士吟 其三","f":"五言古诗","c":["种桑采桑叶，采桑养蚕子。","风雨忽纵横，叶尽蚕欲死。","抱蚕对蚕泣，泪落桑园里。","讵缘绵绣心，淹没遽尔尔。","所伤万人寒，不织从此始。","不织伤人寒，不修道则否。","所以古圣贤，殷勤诲不已。","一语不能行，万卷徒糠秕。"]},{"t":"训士吟 其四","f":"五言古诗","c":["猗嗟此一生，生难尽慧识。","幸不堕顽蠢，造物岂我啬。","况藉古初人，阐微先我力。","得每不践机，失亦难伪饰。","用转欺慊机，慎哉勿自贼。"]},{"t":"训士吟 其五","f":"五言古诗","c":["嘉鱼乐澄渊，好鸟鸣高枝。","德輶鲜克举，安宅旷弃之。","物微知有托，人胡不如斯。","生才不择地，自强安可期。","良工得奇木，丹雘亦应施。","委置任腐蠹，深负兹淑姿。"]},{"t":"训士吟 其六","f":"五言古诗","c":["置身在宇宙，担当复谁诿。","人心能不死，天地因之位。","广厦覆万人，交疏绮筵备。","所赖大匠能，经营使不坠。","草甲出勾芒，芟刈从此始。","荆棘忽成林，长镵不可治。","尔我固陋姿，仔肩成不易。","日月不停徂，反躬多疵累。","先师已有言，四十不足畏。"]},{"t":"训士吟 其七","f":"五言古诗","c":["探奇及牛渚，穷幽入鬼隙。","毕世谁能知，知之复何益。","春至花妍娟，春去花落魄。","花开复花谢，明明大道迹。","块然藐中处，但伤彼岸隔。","不传者已死，会心在晨夕。","豁然识此机，应悲逝者迫。"]},{"t":"训士吟 其八","f":"五言古诗","c":["羊质虎其文，虽美而不彰。","躬行苟不逮，何必徒文章。","笃论竦真听，摛藻阐德光。","立言固所重，饰伪弃厥常。","安得华与实，内外无低昂。"]},{"t":"训士吟 其九","f":"五言古诗","c":["原泉流不息，积水成巨川。","为山篑不辍，积土凌云烟。","积跬致千里，积善成圣贤。","孰微而不著，孰行而不前。","嗟彼器一满，不复增涘涓。","所以英俊人，虚受而德迁。"]},{"t":"训士吟 其十","f":"五言古诗","c":["灼灼盆中花，迎风故妖袅。","眄睐睫未移，倏忽成枯槁。","根株未能深，焉得长美好。","植彼栋梁资，岂不自弱小。","防之偶一疏，斧斤伺昏晓。","吁嗟眼中人，故物谁能保。","胡不一此心，孜孜至于老。"]},{"t":"训士吟 其十一","f":"五言古诗","c":["天运更代谢，气至物不遗。","芳树花忽发，好鸟鸣其枝。","流水清且閒，游鱼漾绿姿。","欣欣物各得，吾身亦化机。","物欣吾亦乐，坐此春风时。","宇宙何空阔，嗒然忘所私。"]},{"t":"训士吟 其十二","f":"五言古诗","c":["人匪道害依，交匪道害臧。","辅仁赖将伯，诡随警无良。","既载失善御，鲜不毁辕缰。","俗目悦萧艾，珵美或不当。","宁以直不回，不防参与商。"]},{"t":"训士吟 其十三","f":"五言古诗","c":["朝见槿花开，暮见槿花死。","非无一时荣，不久长如此。","猎猎谷中风，冷冷涧中水。","苍苍松柏姿，亭亭水风里。","凝寒讵不酷，贞性素所履。","良禽择木栖，戢羽欣来止。","托根贵托坚，永为岁寒恃。"]},{"t":"训士吟 其十四","f":"五言古诗","c":["步出城东门，徘徊歧路旁。","东门何所有，历历种白杨。","秋风自西来，飒然起悲伤。","嗟此泉下人，安知非侯王。","造物无妍媸，有生同丧亡。","富贵固所欣，贫贱事亦常。","斯人正鹿鹿，金乌不停翔。","人非金石固，谁能得久长。","胡不惜嘉名，及时自奋强。"]},{"t":"训士吟 其十五","f":"五言古诗","c":["求人人则贱，求我我自尊。","曷弗安所遇，反覆梏灵根。","缅彼空桑子，崛起自邱原。","不物而物物，抱道岂终沦。","苟子能自淑，文锦在结鹑。","捷径而窘步，福伏祸之门。","所重在自立，贵贱无定论。"]},{"t":"训士吟 其十六","f":"五言古诗","c":["日出扶桑阳，月落咸池阴。","日月不遍照，安问他人心。","明珠忽夜投，罕不按剑临。","琰琬持自粥，虽美吝其金。","所以古大人，潜迹甘泉林。","岂故却荣显，枉己非所钦。"]},{"t":"训士吟 其十七","f":"五言古诗","c":["鹪鹩托羽翰，载憩芳树枝。","栖托岂不稳，安能薄天飞。","裋褐裹珍玉，□晦待厥时。","神龟不受缚，曳尾甘涂泥。","朝云乘天升，膏泽沛无遗。","出处良有会，蓄德贵不衰。","玙璠唯自宝，没齿以为期。"]},{"t":"训士吟 其十八","f":"五言古诗","c":["人但知旦夕，志士争千古。","神禹惜寸阴，蓄念亦良苦。","花落不再春，羲驭岂长午。","吾业不增修，时去将焉补。","缠牵偶一长，不能行数武。","敬慎尔威仪，周旋有规矩。","勿谓隐可欺，勿谓狎可侮。","放闲恣游逸，如水趋远浦。","与子共勉旃，臧否唯自主。"]},{"t":"读书偶得七首 其一","f":"五言古诗","c":["元化无端倪，絪缊运野马。","动寂辟冥机，群肖递陶冶。","继善分天灵，贮形如传舍。","道近在胸臆，俗务纷来假。","祛扩叩本真，寂寞自陶写。"]},{"t":"读书偶得七首 其二","f":"五言古诗","c":["形存我有天，形解天有我。","性量反厥初，理真气不堕。","望月空中明，逐水月碎琐。","天人同一原，以此识担荷。","惜情但犹豫，流光悲石火。"]},{"t":"读书偶得七首 其三","f":"五言律诗","c":["经纶起方寸，所恃宁不危。","积微潜自引，灵辉扩无涯。","纤云蔽朗照，日月用以亏。","况乃汨嗜欲，自戕良可悲。"]},{"t":"读书偶得七首 其四","f":"五言古诗","c":["乾坤无息运，此实大道机。","至人握其要，惧与化育违。","纷纶物杂投，操之在几希。","几希争人鬼，内是外则非。","应者不拘方，受者各有归。"]},{"t":"读书偶得七首 其五","f":"五言律诗","c":["大业在宇宙，大用根虚无。","神以敛而照，智以用而疏。","所以古至人，容貌类庸愚。","妍媸形自现，渊镜仍其初。"]},{"t":"读书偶得七首 其六","f":"五言古诗","c":["造物吾慈母，厚生讵所惜。","诸艰笃儆策，素怀试不易。","安贫贞顺事，昧缺动忍益。","怨尤显逆情，神听不咫尺。","慎密饫道腴，足以验晨夕。"]},{"t":"读书偶得七首 其七","f":"五言古诗","c":["新花被和煦，娟娟发故枝。","好鸟应时来，翩翩浴清池。","感候会冥搜，触目物不遗。","大化运无心，孔契颜犹非。","日暮赴赊程，资用惧莫支。","敢吝耳目前，而矜道在斯。"]},{"t":"赠陈进士宪图","f":"五言古诗","c":["老鹤慕云侣，孤飞伤愿违。","翘然发厉响，日暮空迟疑。","六合不满意，所见非所思。","遐心宅霄汉，卑栖当告谁。","奇翮从南来，慰若平生知。","哀鸣相激烈，各言心中悲。","生死感古人，知音难再期。"]},{"t":"述怀六首 其一","f":"五言古诗","c":["家贫需禄养，审处唯司铎。","惭无启沃功，知足安素约。","老母年九旬，性亦甘藜藿。","藜藿虽不饱，庶免外患作。","妻孥愚无知，似能同索寞。","食未惯肥甘，粗粝亦踊跃。","文酒惜芳辰，同辈相酬酢。","西山秀色佳，秋高眺林壑。","时亦颇饥寒，欢颜长自若。","自问何能尔，俯仰鲜愧怍。","无求贱亦尊，无贪贫亦乐。"]},{"t":"述怀六首 其二","f":"五言古诗","c":["饥寒苦岩穴，驰情慕宠荣。","居此讵不乐，称此责非轻。","所嗟当途子，纷纷但奔营。","我岂耽苜蓿，度德素已明。","谈经迪英俊，足以娱我情。","春雨日已滋，兰蕙日已生。","馨香满怀袖，此非众所争。"]},{"t":"述怀六首 其三","f":"五言古诗","c":["晨兴审污秽，晷影忽上屋。","感逝惊复伤，来者去何速。","百年半已无，途遥怵幽独。","故情匿不祛，天倪汨深伏。","抉隐发灵辉，爱时以自淑。"]},{"t":"述怀六首 其四","f":"五言古诗","c":["天地储精辉，日月合其明。","纲常得朋友，讵不贵洁清。","砥砺质前代，万古同一情。","所愧无曲折，迂气多径行。","亦知非人事，枉己违素营。","中孚苟不窒，相与无虚生。"]},{"t":"述怀六首 其五","f":"五言古诗","c":["大业惜居诸，朝夕奋所营。","谋生忧覆餗，出处量重轻。","官閒如其材，薄禄免躬耕。","惧干圣贤训，耻徒厕公卿。","遭逢想古人，实大乃洪声。","畴昔不践言，恶在虚其名。"]},{"t":"述怀六首 其六","f":"五言古诗","c":["通塞非吾力，事贵与愿俱。","东作苦不胜，禄足代耰锄。","暇豫丰儒官，我还读我书。","微言竭智慧，陶镕天地初。","时或有所得，欣然盼庭除。"]},{"t":"和程侍御四首 其一 藤屋读书","f":"五言古诗","c":["绝壁苍藤深，虬条结精舍。","清籁激微飙，高云宿檐瓦。","悠然太古心，摊书北窗下。"]},{"t":"和程侍御四首 其二 听曲","f":"五言古诗","c":["靡颜娇上春，新声复清绝。","流睇逗层波，纤喉递缓节。","花茵落叶深，一曲回风阕。"]},{"t":"和程侍御四首 其三 持偈","f":"五言古诗","c":["枯偈持九年，心境长自照。","月落万川明，山禽时一叫。","抛却破蒲团，拈花忽微笑。"]},{"t":"和程侍御四首 其四 芦舫寻诗","f":"五言古诗","c":["虚舟载孤月，月浸芦花白。","天影浴澄波，波回漾空碧。","吟魂渺何依，烟霞久成癖。"]},{"t":"梦王贡九","f":"五言古诗","c":["昼想夜复亲，梦谈畅魂魄。","互惜十年馀，曾不如贾客。","志奢遂觉难，情怀各千百。","慷慨多苦心，奋激髯如戟。","携手不忍判，相对数畴昔。","世友孰君良，阅历思尤迫。","释耒起蓬蒿，贤路坦不僻。","高蹈勿庸言，乾坤此重责。"]},{"t":"梦杨澍三","f":"五言古诗","c":["故人来我梦，告我家垂死。","同生百年中，半生已如此。","圣贤漠不援，诗书徒空纸。","怜君愧我贫，泪下不能止。","精诚结中夜，欲别情逶迤。","轻肥遍市朝，蹭蹬君独尔。","古调乏赏音，庸碌多知己。","男儿不惊人，等伦直无耳。","经纶起屠钓，勉力愿无已。"]},{"t":"雨后陈道机招饮环翠亭","f":"五言古诗","c":["天净雨初霁，草木相新鲜。","碧水萦低槛，好鸟鸣树间。","浮云薄太虚，去去亦何閒。","开轩挹苍翠，秀色凌盘餐。","疏松动凉飙，萧然开我颜。","况有忘忧物，重觞累我前。","放情遗滞虑，良会非偶然。","落日散孤霞，墟里明炊烟。","何当复相寻，披襟弄清泉。"]},{"t":"题友人行乐","f":"五言古诗","c":["雄鸡断其尾，不罹庙牺网。","我虽风尘客，每动出尘想。","此卷知为谁，对之心神爽。","流水不肯住，终古但长往。","浮云荡虚壁，倏忽归渺茫。","有生畴不化，达士襟怀敞。","散发入山深，箕踞青苔上。"]},{"t":"太极","f":"五言古诗","c":["太极虚其中，森然万象具。","道裕形器先，乾坤受陶铸。","日月转神枢，往来成寒煦。","坱然气机流，群动非自由。","旋生而旋灭，灵蠢同一筹。","哲人识至奥，洁虑笃冥修。","手握天帝心，神与元始谋。","元始妙无质，阴阳岂能雠。","薪尽而火传，斯理宜潜搜。"]},{"t":"戒除草四首 其一","f":"五言古诗","c":["春风来几日，已绿窗前草。","造物露机缄，会心在微渺。","静念察始终，霁情验荣槁。","一草不忍锄，万卉从兹好。","真趣欲谁言，枝头闻啼鸟。"]},{"t":"戒除草四首 其二","f":"五言古诗","c":["天机运不息，往往汨庸儒。","东风敷至教，绿我窗前刍。","蒙茸方几日，倏忽盈阶除。","感兹惠雨力，殷勤与之俱。","荣枯以一息，我亦念其初。"]},{"t":"戒除草四首 其三","f":"五言古诗","c":["东风吹无私，有地皆芳草。","新甲拆勾萌，删刈恐不早。","恻然悯群生，生机何由保。","所乐因天时，欣欣向我好。","顾兹窗下荣，吾亦爱吾宝。"]},{"t":"戒除草四首 其四","f":"五言古诗","c":["鸢亦不在天，鱼亦不在渊。","飞跃察春草，窗下呈机筌。","大哉造化心，万类无私偏。","天怀畅无碍，适意尽目前。","荆棘起方寸，兰蕙色不妍。","此中识真趣，悠然悟前贤。"]},{"t":"秋雨不止步海涵百龄原韵 其一","f":"五言古诗","c":["柴门闭深昼，心境喜双寂。","凉气散疏襟，尘虑一时涤。","晚笋茂新条，萝筱挂颓壁。","远籁送微飙，清心闻夜笛。","淅沥响古烟，松窗翠雨滴。"]},{"t":"秋雨不止步海涵百龄原韵 其二","f":"五言古诗","c":["群葩苦烈日，生意因之短。","经旬惠雨滋，欣欣荣我馆。","顾兹庭砌幽，无事遂我懒。","移坐就芳丛，苍翠浸茗椀。","悠然忆岩栖，岩中白云满。"]},{"t":"秋雨不止再步前韵 其一","f":"五言古诗","c":["烈暑收灵澍，苍茫衡宇寂。","幽怀畅暇豫，芳翠喜新涤。","薜荔抱云烟，森黑下阴壁。","坐久竹风静，隐隐闻远笛。","散步抚前轩，西山翠欲滴。"]},{"t":"秋雨不止再步前韵 其二","f":"五言古诗","c":["苔草延阴砌，蕉叶新抽短。","所欲非幽深，会静疑山馆。","浮云知我心，归山意亦懒。","开瓮渥诗肠，独酌不计椀。","醉卧南窗下，衣受落花满。"]},{"t":"题赵经历宁侯红叶小照","f":"五言古诗","c":["孤坐生凉阴，庭砌转萧索。","气候物色俱，新花怅畴昔。","单车曲折轻，窅窕入林僻。","科头憩云根，霜姿结寒赤。","盈目炫朱霞，过时亦陈迹。","西风不断吹，摇落还叹息。","草色戴霜痕，苍然秀岩石。","石罅溜寒音，泠泠沁心膈。","簿领非閒曹，委蛇自公隙。","萧洒清秋怀，幽契尘埃隔。","顾兹炎热场，愧尔幽静客。"]},{"t":"再题红叶小照","f":"五言古诗","c":["幽赏索秋痕，轻车远城郭。","连磴玩回蟠，惊新非意度。","村墟阒见闻，踞石眺岩壑。","清泉越远冈，崎岖绕石落。","红叶挂寒条，参差绮云灼。","感此凌霜姿，赏心别有托。","阴霞生莫崖，归怀展领略。","追忆发奇吟，吟成独斟酌。"]},{"t":"自万松岭寻仙人洞","f":"古风","c":["松柏碍云日，■确石色古。","峰影入溪流，天水相吞吐。","蛇径萦乖厓，攀跻足莫主。","崱屴阅重冈，幽深窥洞府。","悬泉暗相激，䆵?溜石乳。","向背势超忽，移步不可睹。","入林疑昼昏，出林日尚午。","嘤嘤栗留鸣，前山不数武。"]},{"t":"种牡丹分得长字","f":"五言古诗","c":["积翠古名园，颓废无人赏。","荣华有憔悴，天香委榛莽。","我来宰兹土，搜奇怅已往。","念此绝世姿，移置瑶台上。","瑶台一何崇，榛莽一何枉。","殷勤灌溉心，重是百花长。","草木感知己，酬报情岂爽。","倍发来春花，高堂供色养。"]},{"t":"正石","f":"五言古诗","c":["苍翠辞高峰，背向人间立。","阅历几来官，相顾不相识。","我性耽冥搜，转移施微力。","众情诧改观，喧然叹奇辟。","邃穴欲生云，随风升虚碧。","位置失本真，顽蠢一拳石。","始知殊异材，多为世所惜。"]},{"t":"题长城驿姜女祠","f":"五言古诗","c":["新秋天气佳，群鸟鸣林木。","公事既云已，策杖越山麓。","是时雨初收，万象喜新沐。","高原扩奇怀，远迩纷来目。","古祠覆茅茨，修篁夹径曲。","云是秦时女，殉夫长城窟。","斯言似不经，史传无专录。","山海有高坟，余曾吊昔夙。","睹兹然疑生，错误沿流俗。","应是杞梁妻，夫死死于哭。","姑置无复道，徘徊眷遐瞩。"]},{"t":"司贞女二首 其一","f":"五言古诗","c":["斲彼冬青木，练兹冰蚕丝。","不奏合欢音，翻鼓别鹄词。","结缡自髫龀，没齿以为期。","不谓永决绝，乃在及笄时。","妾心非朝露，不为白日晞。","芙蓉负霜死，不作浮蘋移。","平生味凫藻，何以执妇仪。","愿言觌君面，为君守孤帷。"]},{"t":"司贞女二首 其二","f":"五言古诗","c":["郎若东流水，永逝无还期。","妾若茑萝丝，松折犹逶迤。","三日为君妇，未识君容仪。","含羞侍君疾，但觉心酸悲。","哀风出穗闼，夜夜啼羁雌。","白头自兹始，九死亮不移。","郎有堂上亲，郎有柩下儿。","仰事兼俯育，劳瘁妾不辞。","遂此区区心，愿赴黄泉期。"]},{"t":"喜年家子毛秋岑来自京师","f":"五言古诗","c":["昔别是何时，心悲安可论。","归来重握手，欲语复何言。","商飙起庭树，萧萧落叶繁。","萤火收夜光，椒榝已空园。","寒暄更代谢，荣悴变朝昏。","亭亭松篁柯，青葱今尚存。","相对成一笑，相劝酒盈尊。"]},{"t":"送秋岑还京师","f":"五言古诗","c":["君来慰我愁，君去愁如何。","慷慨结交欢，阅历已云多。","孰是际颠危，而能心靡他。","屏营济河侧，远水生寒波。","西风吹旅雁，嘹呖云中过。","感兹岁将晏，况复当离歌。","倏忽一尊酒，远隔云山阿。","云山缈难及，瞻望泪滂沱。"]},{"t":"感遇十首 其一","f":"五言古诗","c":["方柄而圆凿，龃龉讵相适。","所守诚拘墟，所遇宁不逆。","世情苦未练，疏懒成离索。","名虽擢礼闱，宦途实云隔。","承欢希禄养，黾勉就司铎。","官閒职易称，亦恐婴祸阨。","训迪匝六年，声誉渐隆赫。","蒙恩授剧邑，力辞不能却。","驽马蹶长途，弱材困重责。","事去方觉非，道穷唯自惜。"]},{"t":"感遇十首 其二","f":"五言古诗","c":["兰若生空谷，冉冉扬其香。","殷勤采华姿，将以遗远方。","不谓至中途，清露结严霜。","枝叶匆摇落，岁暮不成芳。","芳香自兹歇，谁知我心伤。","所伤王者瑞，将同秋草黄。"]},{"t":"感遇十首 其三","f":"五言古诗","c":["许由避天下，馆人疑窃履。","颜渊万世师，烟煤议诸子。","从古不相知，颠倒有如此。","浮云过我前，安能测起止。","祸福亦有天，人心胡为耳。"]},{"t":"感遇十首 其四","f":"五言古诗","c":["天马龙之媒，来自渥洼渊。","毛色灿云霞，饰以锦绣鞯。","四蹄疾于鸟，驯良尤足贤。","骖乘并騕袅，随宴昆崙巅。","羁靮不及转，中道成迍邅。","空有远驾能，谁复信其然。"]},{"t":"感遇十首 其五","f":"五言古诗","c":["虎视何耽耽，高负山之隅。","所性嗜食人，安择贤与愚。","牙爪非不利，积恶已盈辜。","蒐苗殄异类，除之不须臾。","虽无救所伤，报复快万夫。","凶顽适自戕，天网孰云疏。"]},{"t":"感遇十首 其六","f":"五言古诗","c":["妍媸苟不现，无盐诋西施。","贪廉苟不著，盗蹠罪伯夷。","人心岂尽亡，神鬼难久欺。","水浊不见月，水清石离离。","吁嗟转瞬间，儇诡何所施。"]},{"t":"感遇十首 其七","f":"五言古诗","c":["瑩瑩席上珍，什袭藏缄縢。","临渊忽堕水，终古悲沉冥。","晨鸡一失晓，歛翼耻再鸣。","琴材收爨下，焦尾有希声。","滕公活连敖，无知荐陈平。","知己一朝遇，功业垂千龄。","我无二子材，敢妄希身荣。","不如反初服，坎壈终此生。"]},{"t":"感遇十首 其八","f":"五言古诗","c":["佳人钟灵秀，抱性淑且忱。","容色倾帏闼，遂使众生惭。","群丑妒蛾眉，谣诼谓善淫。","偭规而改错，自昔不唯今。","众口鼓炎飙，能不乐其金。","曼倩蛇龙训，渔父波泥吟。","前言讵不卓，非余心所钦。","东海狎樵牧，逍遥散疏襟。"]},{"t":"感遇十首 其九","f":"五言古诗","c":["灵虬潜深渊，江湖任所逝。","常服易其初，风涛多滞泥。","哲人睹未形，愚者触机棙。","前途已云迷，回辙岂失计。","变化看浮云，失得塞翁谛。","祸福互为根，荣枯亦更递。","荷篑诚我师，深浅随揭厉。"]},{"t":"感遇十首 其十","f":"五言古诗","c":["埏埴随大造，结沫亦已危。","人命如朝露，人心若阳晖。","阳晖酷煎曝，朝露宁不晞。","蜉蝣延刻晌，蝼蚁营寸壤。","宁知不崇朝，方作百年想。","人生无智愚，同入梦中趋。","在梦无不有，梦去成空虚。","富贵乐难久，贫贱亦须臾。","万象不停睫，荣悴何足吁。","所以古至人，离幻保真如。","况我年半百，秋霜满鬓须。","此身非我有，身外何所须。"]},{"t":"留赠原长清张明府稼兰四首 其一","f":"五言古诗","c":["兰蕙同芬芳，枝叶故相连。","杰士慕道义，不在多晤言。","忆昔初遇君，平生昧周旋。","世人正欲杀，君情何缠绵。","岂为结交欢，急难心炯然。","慈闱老病笃，望子不得还。","中心握汤火，归我解倒悬。","我归见母拜，泪下如迸泉。","不谓生聚时，即为死别年。","锡类向微君，抱痛恨终天。","何以喻君情，深同九仞渊。","何以致余感，将与石同坚。","渊或有时竭，石或有崩骞。","唯此区区心，历劫永不迁。"]},{"t":"留赠原长清张明府稼兰四首 其二","f":"五言古诗","c":["濯濯新杨柳，当春扬芬芳。","秋风一夕起，枝叶尽萎黄。","世情一何脆，君情一何长。","情长令我感，亦令我悲伤。","冉冉京华道，历历仕宦场。","到处露肝胆，欢爱伏祸殃。","顺逆忽异势，拯溺固难望。","慷慨甫昨日，杀之何太忙。","意有所倚薄，宁为少徬徨。","交途饱阅历，世孰如君良。","昔未接杯酒，今赖恤存亡。","始知天下士，蓄念迥寻常。","愿定百年交，千里若同堂。","我心已匪石，君德信圭璋。"]},{"t":"留赠原长清张明府稼兰四首 其三","f":"五言古诗","c":["酌我盈觞酒，赠我河梁诗。","对酒不能饮，涔涔涕泪垂。","诵诗多苦言，言苦令我悲。","宦游十馀载，奉母未暂违。","昔与母同出，不见母同归。","长途三千里，哀哀哭灵輀。","念想平生恩，中夜魂依依。","我母见我拜，怪我来何迟。","恐我复离去，双手牵我衣。","见我颜色瘦，悯我腹中饥。","道路阻且长，虑我囊无赀。","悽怆床帏下，眷恋如平时。","鸡鸣惊我梦，倏忽缈难追。","号泣呼苍天，血泪洒齐衰。","呜咽促严装，霜笳晓寒吹。","边风利如刀，刺我骨与饥。","黄沙连雪捲，日暗天惨悽。","我马骨欲折，我仆痡且危。","回首望中原，此情君独知。"]},{"t":"留赠原长清张明府稼兰四首 其四","f":"五言古诗","c":["嘉会能几时，倏忽悲路歧。","仆夫宛已驾，势复难久迟。","行行更携手，不忍便分离。","情怀千万端，欲语先歔欷。","歔欷复何言，泪下不自持。","仰视云中鸟，历历相随飞。","俯察渊中鱼，游泳同陂池。","况当甫脱难，与君新相知。","从此一分手，会面未有期。","人生感知己，岂但惜离卮。","何以写中怀，兴言寄新诗。","新诗情缱绻，音节怆以悲。","上言长相感，下言长相思。"]},{"t":"再别稼兰","f":"五言古诗","c":["春云作灵雨，沾洒成膏泽。","琰琬得善价，声光日烜赫。","良材不隐世，君实任此责。","枳棘暂栖鸾，翀飞在晨夕。","况当明良会，朝廷正侧席。","努力崇明德，功业垂金石。","腐朽不足称，臃肿背绳尺。","永为盛世褫，时亦还自惜。","用舍虽殊途，持身贵自择。","去去从此辞，相期在贤哲。"]},{"t":"悲秋","f":"五言古诗","c":["良辰去何速，秋草绿已萎。","北风动地起，吹我单裳衣。","贾用既不售，曷久绁尘羁。","游鱼亦有渊，栖鸟亦有枝。","我母不我恃，游子寒无依。","食口日嗷嗷，冻馁气惨悽。","三岁乳下孙，日莫向母啼。","其母怒嗔喝，告母腹中饥。","哀声刺我耳，使我心酸悲。","人生如朝露，岁月能几时。","亲柩不能返，骨肉危天涯。","回身叫孙抱，泪下不可支。"]},{"t":"留别历城王明府古岩","f":"五言古诗","c":["旅馆闭昏昼，迥与世人隔。","凄凄破牖风，阴阴陋巷雪。","妇孺日号寒，炊烟屡断绝。","时读古人书，往往慕前哲。","高诣岂能追，固穷亦素悦。","志士蕴苦衷，沟壑非云烈。","顾兹母氏灵，乡关远难涉。","中心怆以摧，愁肠己寸裂。","自分祸患馀，久为人不屑。","讵知一遇君，义气动颜色。","游好非平生，情同麦舟切。","结契方自兹，谁堪倏离别。","赋诗未终篇，感君泣呜咽。"]},{"t":"赠原昌邑王明府二首 其一","f":"五言古诗","c":["蘋藻无定根，因风自来去。","人生无定遭，绸缪有散聚。","忆我初来东，识君倾盖际。","一见展殷勤，异姓联同气。","东西旋就官，先后遭时忌。","救祸各不遑，有情徒相思。","转瞬忽三年，变幻如梦寐。","风过花离披，雨收途路泥。","茫茫寻旧交，谁能不遐弃。","同病自相怜，君情无改易。","相怜复相亲，执手一歔欷。","君颜虽如初，我已发髭异。","得失何足论，人生且如寄。","慷慨付达观，耻挥儿女泪。","君家酒正醲，且尽今朝醉。"]},{"t":"赠原昌邑王明府二首 其二","f":"五言古诗","c":["我醉复何言，相期在终始。","削籍归故乡，我事已如此。","君才世所稀，蹭蹬偶然耳。","云来月无光，云去天如洗。","譬剑新发硎，寒芒若秋水。","骐骥历坦途，一日可千里。","君达不失望，我穷不失己。","他日若相逢，无忘下车礼。"]},{"t":"喜晤李复堂","f":"五言古诗","c":["自命天下奇，长怀天下士。","所遇或非期，惧浮此生理。","抱此已多年，相见但充耳。","菁华寓古今，迂儒泥经史。","孰是真不惑，畅谈略文字。","携手游太初，端居悟终始。","豁然开襟期，相顾洒然喜。"]},{"t":"与陈石农师徒讲学","f":"五言古诗","c":["木以绳而直，璞非凿不宝。","大道蕴渊深，立言非草草。","虚衷积众奥，灵府豁如扫。","新花发故枝，嘤嘤闻啼鸟。","眺听感芳春，当轩尽朋好。","妙绪触天工，经纶探怀抱。","万世尽浮云，所性贵自讨。","古人非无书，过信见亦小。","飞跃露机缄，迂疏但枯槁。","出言苦不经，君应恕我老。"]},{"t":"送门人杨赴乌程主簿何赴东乡县令尤赴鸡泽教谕","f":"五言古诗","c":["春风吹飞云，飘飖随所之。","交游岂长聚，亦知当乖离。","况君行就官，讵复能久羁。","行矣不可留，念我此何时。","弃妇归无家，览镜惜容仪。","出亦无所适，入亦长苦饥。","不谓同心友，各自东西驰。","征人慕前程，宁知我心悲。","心悲勿复言，且尽今日欢。","欢罢还成泣，愿君少留连。"]},{"t":"忆西山","f":"五言律诗","c":["春雨润苍翠，逦迤遍山麓。","野趣情所钟，泉石萦心目。","思将释尘劳，采兰涧之澳。","昨夜西山云，来我窗前宿。"]},{"t":"儿女","f":"五言古诗","c":["大儿怜余老，艰苦知自持。","小儿初学语，喃喃索饼饴。","两女强解事，绕膝向我啼。","问女一何啼，哀哀前致词。","无衣长苦寒，无食长苦饥。","况复当弱龄，值此深秋时。","严风杂浩雪，凛冽摧肌皮。","粗絺裹枵腹，性命安能支。","听之生惭赧，欲答心先悲。","心悲强欢笑，握手双提携。","抚摩为拭泪，甘言相戏欺。","缅彼蒙袂子，困阨尝如斯。","嗟来耻不食，沟壑分所宜。","奈何小儿女，亦同罹此危。"]},{"t":"劝农","f":"五言古诗","c":["喈喈仓庚鸣，阴阴膏雨滋。","田家勤力作，所惧违天时。","丁男事南亩，妇孺饷东菑。","烈日曝尔体，毒涝煎尔肌。","岂不悯劳悴，生人道在斯。","拮据幸有秋，衣食固其资。","时或岁不稔，室家良苦饥。","孰是任鲁莽，丰裕而能期。","欢言劝时务，壶餐聊尔遗。"]},{"t":"夏日偕云浦鹤亭郊外纳凉 其一","f":"五言古诗","c":["积雨负花期，雨霁兴难遏。","联袂出城闉，迎眸森翠列。","重荫晦平皋，茶瓜藉莎蘖。","莲净心亦清，清谈义超越。","凉飙度深香，烟霏互兴灭。","何必觅芳尊，己觉炎威歇。"]},{"t":"夏日偕云浦鹤亭郊外纳凉 其二","f":"五言古诗","c":["泽阅怀已澄，念复前山结。","引步缘沟塍，菰蒲度曲折。","流水淡容与，高云驻修樾。","披襟畅遐睇，西峰翠如涅。","羲驭顿阴厓，游情眷芳洁。","凉飔不断吹，惆怅林泉别。"]},{"t":"喜犹子秉瑛乡试报捷","f":"五言古诗","c":["夜眠不能寐，起视天未明。","少顷闻报录，云有瑛侄名。","听言色忽变，失喜心若惊。","欢呼旋默坐，呜咽泣有声。","妻孥怪趋问，不自得其情。","呼瑛执其手，双泪流纵横。","自尔丧尔亲，尔年甫弱龄。","万苦至今日，我语尔谛听。","尔祖隶辽东，家室久飘零。","年老望儿孝，赤手空经营。","尔父真克家，助我如鹡鸰。","我后捷南宫，三载留燕京。","独任力不支，亲重身命轻。","兼之教尔辈，冀望兴门庭。","积劳成沈疴，奄逝尔伶俜。","平生旧相识，生死不渝盟。","况是同怀子，岂不当力承。","伯母虽若母，唯恐异所生。","保护常自任，时与共寝兴。","梦中啼索父，感我同悲鸣。","携尔至河间，教育堪自凭。","岂意岁奇凶，饿殍填沟塍。","旋即得凶问，我父耄倦勤。","举室陷危地，肝肠碎裂崩。","众口且莫保，安顾膝前婴。","此境逾三年，万死势甫平。","继复屡遭难，延师力不能。","朝夕自训迪，提命尔能聆。","为长心愈苦，梦寐无时宁。","惧我年就衰，不获见尔成。","尔今幸举乡，天地非无情。","聊足谢吾责，亦慰尔父灵。","尔其重勉旃，慎勿隳厥行。","语罢命杯酌，欢饮浊复清。","颓然忽大醉，懵然天已暝。"]},{"t":"题采桑图","f":"五言古诗","c":["春日采柔桑，桑叶饲蚕子。","饲蚕蚕不食，举家愁欲死。","结茧酬辛勤，公私庶有倚。","练作万缕丝，织成一端绮。","绮罗遭僭滥，狼籍若麻葈。","谁念养蚕家，艰辛乃如此。","卖丝易斗升，粗褐不蔽体。"]},{"t":"赠陈石闾五首 其一","f":"五言古诗","c":["古乐久沦丧，抱瑟犹孤鸣。","宫商郁不舒，中含万古情。","情深世莫测，哀怨难为声。","孤鸾慕俦侣，翱翔遍九宇。","雌雄倘颉颃，高飞戢毛羽。","季女婉娈姿，出入长苦饥。","容华坐消尽，翻为嫫母嗤。","安能结同心，生死不相离。"]},{"t":"赠陈石闾五首 其二","f":"五言古诗","c":["灼灼春前花，袅袅路旁柳。","所遇非坚贞，欲折迟攀手。","日月如转丸，夙愿岁空守。","不恨契阔长，但恐此情负。","往者不可援，来者复何有。","宇宙渺茫茫，欷歔搔白首。"]},{"t":"赠陈石闾五首 其三","f":"五言古诗","c":["冥鸿翔圹埌，矰缴安得施。","神虬潜瀴溟，网罟空尔为。","仙人握鸿宝，举世谁能知。","缘崖拾璚蕊，披云采紫芝。","芬芳溢襟抱，郁为金玉词。","金玉无凡响，芬芳无已时。","愿言蹑高躅，遂此平生期。"]},{"t":"赠陈石闾五首 其四","f":"五言古诗","c":["騕袅鸣蓟野，万马喑不嘶。","鸑鷟飞摩霄，群鸟失羽仪。","南风久不竞，北里声卑迷。","引商杂流徵，音响入云悲。","翩翩鸾鹤下，冉冉神灵驰。","谁能为此曲，此曲知者稀。","君独向我弹，我情为君移。"]},{"t":"赠陈石闾五首 其五","f":"五言古诗","c":["赫赫五都璧，朗朗照乘珠。","光芒发蒙昧，惊怪委泥涂。","冲霄两龙剑，神物岂终疏。","邂逅延平津，精灵相趋扶。","高天悬明月，中有玉蟾蝫。","明月有盈亏，蟾蝫心不渝。","精辉照天地，万古同须臾。"]},{"t":"寄答李眉山五首 其一","f":"五言古诗","c":["大块钟名区，端为旷士宅。","所以千古人，往往在草泽。","世苦滞尘网，百年如有迫。","试问终何成，相顾唯太息。","始知巢许辈，渊衷不可测。","涧水流空山，孤云出虚壁。","于以陶性天，兼之识化迹。"]},{"t":"寄答李眉山五首 其二","f":"五言古诗","c":["朝随白云去，暮与清溪还。","有时不欲往，伫看门前山。","山色倏隐现，变幻常无端。","人事有得失，亦在须臾间。","冥鸿翔高云，巨鱼潜重渊。","岂故耽离群，百年心独閒。"]},{"t":"寄答李眉山五首 其三","f":"五言古诗","c":["苍苍盘山峰，蔼蔼罗村坞。","岩谷带茅茨，烟霞互宾主。","中有良田畴，卜筑安乐土。","时与植杖翁，欣瞻好禾黍。","归来掩柴荆，著书穷太古。","皓月同琴尊，孤云共寝处。","举世仰高风，襟期谁能睹。"]},{"t":"寄答李眉山五首 其四","f":"五言古诗","c":["我虽在风尘，性亦耽丘壑。","长怀陇亩民，穷耕有馀乐。","既足免饥寒，且少外患作。","中岁婴簪组，此志成瓠落。","孤鸟失林鸣，浮云无定著。","晚识田盘翁，高情侣鸾鹤。","企慕萦心神，出处增愧怍。"]},{"t":"寄答李眉山五首 其五","f":"五言古诗","c":["未见劳我思，既见思复起。","荏苒忽三年，私心常如此。","结交不相知，觌面仍万里。","所趋道既同，四海如邻比。","望云情远驰，存旧欣来止。","君来缺晤言，君归恨莫已。","嗣还遗我诗，开缄发狂喜。","三复冰雪吟，故人心尚尔。"]},{"t":"送孙在原回黔南龙泉县任四首 其一","f":"五言古诗","c":["群鸟游芳洲，同类自相呼。","和鸣成匹俦，岁久终不渝。","飘风一朝发，分飞万里途。","中心长不释，眷恋栖息初。","重云隔天地，山川邈难逾。","岂不思颉颃，鼓翼空踟蹰。"]},{"t":"送孙在原回黔南龙泉县任四首 其二","f":"五言古诗","c":["琼瑶久不宝，芝兰委萧荻。","翩翩夸毗子，慷慨联胶漆。","胶漆旦夕解，对面不相识。","感彼蜉蝣衣，变化生悲恻。","古人重结交，长恐非金石。","金石蕴坚贞，历久恒如昔。","磨亦不能磷，镕亦不改色。"]},{"t":"送孙在原回黔南龙泉县任四首 其三","f":"五言古诗","c":["猎猎朔风吹，萧萧黄叶飞。","嗷嗷雁南度，戚戚我心悲。","浮云西南来，聚散无长期。","君身若鸿鹄，我身若凫鹥。","鸿鹄将远翔，凫鹥恋涸溪。","能不感离群，引颈以歔欷。"]},{"t":"送孙在原回黔南龙泉县任四首 其四","f":"五言古诗","c":["愁云结重阴，游子将跋陟。","徘徊眷歧路，悢悢情难抑。","边风吹枯蘋，飘飖离本根。","食蓼长觉苦，怀冰长觉寒。","愁人多酸辛，况当离别难。","唯念复来归，慰我桑榆年。"]},{"t":"寿乔山人兆三八十初度 其一","f":"五言古诗","c":["美玉不受制，韬奇完太璞。","混沌凿未施，真机葆深蓄。","离俗清道心，亦藉烟霞沐。","化迹留空山，神悴知者孰。","会心岂在远，灵景生坦腹。","充然养天和，谁能量盈缩。"]},{"t":"寿乔山人兆三八十初度 其二","f":"五言古诗","c":["少小破尘见，结宇山之麓。","扶杖占天时，但愿桑麻足。","比闾释猜嫌，犬猫互收育。","时复邀邻叟，田家酒初熟。","鸡黍列盘餐，儿童工戏局。","归卧衡茅下，农经恒夜读。"]},{"t":"寿乔山人兆三八十初度 其三","f":"五言古诗","c":["翁年今八十，貌古发未白。","朝看原上山，暮看松间鹤。","泉石茹清贞，林峦资盘礴。","虽有岁功营，未能免力作。","即事多好怀，兼之忘城郭。","汉阴有淳风，于焉老栖托。"]},{"t":"寿乔山人兆三八十初度 其四","f":"五言古诗","c":["余久滞泥涂，心契岩栖乐。","世务不撄衷，庞眉友鸾鹤。","令子通殷勤，探奇有夙约。","望云结遥想，此意成离索。","豁见冰雪姿，驻尘聊称酌。","终当入深林，相随看丘壑。"]},{"t":"送王齐岳归里 其一","f":"五言古诗","c":["徬徨复徬徨，忽忆长安好。","决去无迟疑，老母惊持抱。","严冬十月交，此行道路杳。","冰雪挈空囊，性命何草草。","答言非浪游，饥寒势难保。","得志早归来，庶几赡昏晓。","想君昔时情，离别心如捣。"]},{"t":"送王齐岳归里 其二","f":"五言古诗","c":["长安名利都，才智纷纭聚。","豪家势熏天，嘘气成烟雾。","臧获被文锦，驽骀饰金璐。","奔趋望汲援，门庭日如鹜。","却望生惭赧，失路谁相顾。","既悔羝触籓，还伤舆脱辐。","行则不能前，退则羸其角。"]},{"t":"送王齐岳归里 其三","f":"五言古诗","c":["喔喔鸡初鸣，骊驹己在门。","临发检行囊，囊空无一钱。","慈帏日倚闾，注望游子还。","游子不得意，何以慰朝昏。","执手一歔欷，泪落秋风前。","秋风飒然至，吹尔衣裳单。","踟蹰不能判，悽怆摧心肝。"]},{"t":"送王齐岳归里 其四","f":"五言古诗","c":["君缘不得志，慷慨来京门。","京门徒偃蹇，忽复返家园。","进退嗟维谷，方知行路难。","璘彬蕴奇石，谁能戕其天。","游云弃灵岩，随风成播迁。","古来贤达人，身外非所干。","劝君守蓬庐，绕膝终天年。"]},{"t":"送同年戈絅公赴开化令","f":"五言古诗","c":["丛兰馥华堂，众宾集长夜。","酣歌曲未终，游子将远驾。","发轸自燕京，扬帆向开化。","慷慨临路歧，耻为儿女悲。","人生非鹿豕，聚散会有期。","雕鹗厉毛羽，乘风起高飞。","鹪鹩困六翮，枳棘潜卑栖。","污隆道各殊，努力贵自持。","相期在久要，岂必欢聚时。","愿为古松柏，岁寒无改移。"]},{"t":"题李于野秋夜对月图","f":"五言古诗","c":["天地变气候，万象澄幽光。","白月下野草，蟋蟀鸣东厢。","清飙乘因来，淅淅吹单裳。","感彼离根蓬，飘飖随风扬。","达人涤滞虑，独坐亲寒芳。","游目送孤云，遐心与俱忘。"]},{"t":"寄赠朱泗山","f":"五言古诗","c":["驱车游太行，诘屈历九阪。","世路多险巇，履道谁坦坦。","人心匪澄渊，乌能测深浅。","滤鬼潜身形，飞丸不闻声。","他人何足道，骨肉还相倾。","畴能笃至性，生死同一情。","冰雪作肝肠，贮之璚瑰罂。","皦洁映朝日，寒苦心所轻。"]},{"t":"寄赠许觐光","f":"五言古诗","c":["生民各有营，得失纷忧乐。","至味在简编，弃之如糟粕。","好修有嘉名，多为世所托。","微言惧终淹，阐幽祛束缚。","慨然慕隆古，渊情世岂度。","天畔灿朱霞，云中翔白鹤。","愿言觌斯人，胸臆一开拓。"]},{"t":"读鲍步江海门集却寄","f":"五言古诗","c":["神鲤甘泥淖，鸾凰伏莽榛。","岂无变化能，所惧戕其真。","原隰有游龙，灼灼耀光彩。","西风纵横吹，零落随萧苇。","名山有大猷，难与肉食谋。","男儿不矢志，何以垂千秋。","榛苓思美人，引领生离忧。"]},{"t":"送单青侅任龙门令","f":"五言古诗","c":["黄钟废己久，秋兰在虚谷。","古音谁复考，孤芳媚幽独。","人生不相知，深情向谁告。","榛苓望所思，道远隔川陆。","头白甫交欢，旋伤离愁续。","相遇一何难，相违一何促。","君歌游子吟，我奏离鸿曲。","歌曲声激昂，褰裳野踯躅。"]},{"t":"送杨子安任犍为令","f":"五言古诗","c":["霜雪凝严寒，随风飘孤馆。","登高送远人，萧条岁月晚。","云山相阴翳，游子去日远。","抗怀企古先，知音良独难。","缔交方几时，离情忽相干。","况我当迟暮，悬车照颓颜。","临歧欲有赠，泣下不能言。","愿寄瑶华音，慰我心缠绵。"]},{"t":"送李眉山挈眷南游二首 其一","f":"五言古诗","c":["云山高崔巍，中有太古琴。","歌声出金石，四顾谁知音。","奇响震天地，硠硠开我襟。","绿萝附松柏，缠绵遂至今。","杳杳潞河水，阴阴田盘岑。","音容偶不接，梦寐劳追寻。","况今远别离，山川阻且深。","宛转不能留，黯然伤我心。"]},{"t":"送李眉山挈眷南游二首 其二","f":"五言古诗","c":["我久客京师，欲归苦无家。","今君复远出，挈眷游天涯。","老为饥所驱，不得安岩阿。","去留同一情，相送发长嗟。","车舆宛在路，将发复延伫。","携手一为别，涔涔泪如注。","冰雪满前途，君应慎朝暮。"]},{"t":"送何检讨西岚出守凉州 其一","f":"五言古诗","c":["南州有奇鸟，戢羽昆崙巅。","渴饮沆瀣露，饥餐青琅玕。","翩翩唼兰沼，矫矫翔云天。","永与尘寰隔，翘首招群仙。","螭珠不隐世，湛卢不终沦。","美材收匠石，作栋清华班。","清华简贤俊，出守向函关。","函关腾紫气，诘旦谒玄元。","授以青云芝，服之可长年。","相期在万古，富贵何足论。"]},{"t":"送何检讨西岚出守凉州 其二","f":"五言古诗","c":["煌煌华灯悬，高堂罗佳宾。","歌筵饮正酣，起视众星阑。","送子将远行，欲赠非常言。","矫矫人中龙，结想在青云。","因风生羽翰，飞鸣翼紫宸。","盛满难久居，终当保其真。","朝著王乔舄，夕浴颖川滨。","携手觅烟霞，逍遥侣鸿鸾。","隐显从变化，谁能测其端。","冀君长识察，此志勿中沦。"]},{"t":"送李寿先南游","f":"五言古诗","c":["贫老嗜讴吟，郁郁长安邸。","风雅岂能当，愁怀聊自弭。","绕径塞蓬蒿，终岁绝行轨。","杰士求知音，访我数千里。","投赠非南金，相慕在兰茝。","翩翩以其邻，圭窦罗英伟。","秋风吹行云，奄忽隔山海。","已觉伤离群，君复戒行李。","名胜恣遨游，我情徒迤逦。","振衣蹑高岑，应悲在泥滓。","旅雁鸣高空，春北秋复南。","岂独避寒暄，江海有遐心。","今君欲远适，感我一何深。","百花竞时荣，芬芳发中林。","游云无滞迹，高飞慕幽岑。","平生抱微尚，五岳思追寻。","困顿不能前，跂睇徒悲吟。","对君写中曲，朱弦张素琴。","霜雪作春寒，凛凛天地阴。","仰首羡冥鸿，俯首悲陆沈。"]},{"t":"送刘编修殿虎出守九江三首 其一","f":"五言古诗","c":["孤云不出山，连绻抱奇石。","随风入九霄，变化成膏泽。","出处何容心，遭逢随所适。","君无甔石粮，结绶游远乡。","岂为誇荣显，颐养娱高堂。","奉身有良璧，皎皎生夜光。","前路夷且巇，愿君慎其防。"]},{"t":"送刘编修殿虎出守九江三首 其二","f":"五言古诗","c":["茫茫瞰四野，恻恻心忽悽。","皓雪盈天地，集树成枯枝。","中有皞寒禽，怀春声正悲。","悲声震聋瞆，赏音来何迟。","遇子风尘中，升沈途路歧。","孤松结盘石，寒暑心不移。","今将舍我去，作郡九江湄。","思欲远从之，褰裳复犹夷。","悠悠望南天，心与征云驰。"]},{"t":"送刘编修殿虎出守九江三首 其三","f":"五言古诗","c":["祖客饯将归，游子怀往路。","我何长叹嗟，徘徊独延伫。","远游背乡里，逢故即色喜。","况是人中龙，五载久知己。","会面虽有时，仓卒情难已。","明月沈深渊，茝兰散江涘。","抚躬还自伤，衰年逝如矢。","同气而远离，思心从此起。"]},{"t":"题沈尔介垂钓图","f":"五言古诗","c":["江水澄清波，水清石见底。","披襟绝俗营，垂纶兼洗耳。","此中滋味佳，不为得鱼喜。","渔子操轻舟，截纲横江汜。","渔利非娱情，风波有时起。","何如守一竿，心境淡如水。","淮阴终此身，宁悲儿女子。"]},{"t":"送国侍卫天峰","f":"五言律诗","c":["情语方夜终，徘徊怅歧路。","旭日升高冈，秋风满高树。","忧来白发生，谁解相思故。","茅檐鸟雀喧，独坐听朝暮。"]},{"t":"悲秋","f":"五言古诗","c":["惊飙振阴林，残萚纷零落。","荣枯动鼻感，酸风慄羁魄。","登高望所思，烟霜蔽广陌。","岂乏平生亲，眷恋五情灼。","群物囿鸿钧，藐焉何所托。"]},{"t":"怀远 其一","f":"五言古诗","c":["寒月照孤影，戚戚生怨嗟。","故人被奇服，远隔天之涯。","对此盈尊酒，独酌酣且歌。","歌声杂悲啸，感慨一何多。","精霸倘相召，舟楫渺江河。","叹息永终夜，天汉西南斜。"]},{"t":"怀远 其二","f":"五言古诗","c":["西南望不极，天汉谁能通。","欲致一纸书，远托云中鸿。","杳杳逝无凭，耿耿情所钟。","芳草委寒谷，严霜凋其华。","馨香时欲歇，岁晚纷欹斜。","怅望南归云，引领徒咨嗟。"]},{"t":"寿庆祠部松乔五章章十二句 其一","f":"五言古诗","c":["世情尚谀佞，祝嘏多浮词。","跨鹤蹑蓬莱，挥手拂云蜺。","否则愿荣贵，显赫耀当时。","发言涉荒谬，无乃识者嗤。","尔我敦道义，薄俗应所非。","新诗聊复吟，坚贞以为期。"]},{"t":"寿庆祠部松乔五章章十二句 其二","f":"五言古诗","c":["坚贞若松柏，崔嵬南山岑。","绿萝覆高枝，苍苍结浓阴。","古人重知己，德业每相钦。","缔交苟莫逆，和鸣如瑟琴。","弦柱偶不谐，安能扬清音。","我有大药资，可以成黄金。"]},{"t":"寿庆祠部松乔五章章十二句 其三","f":"五言古诗","c":["黄金药可成，愿君莫轻弃。","情殷责苦深，摛语斸肝肺。","被之荣心神，遭逢随所际。","彩凤摩霄盘，凡鸟奚能企。","寓形百年中，长怀千年计。","修短亦由人，金石可自励。"]},{"t":"寿庆祠部松乔五章章十二句 其四","f":"五言古诗","c":["自励祛俗情，菁华浚灵腑。","况兹大块春，俯仰供吾取。","枝上鸣新禽，窗前过疏雨。","默识造化心，幽室自太古。","妙剂饵微言，嗜欲纷斤斧。","性静心亦清，莫妄希翀举。"]},{"t":"寿庆祠部松乔五章章十二句 其五","f":"五言古诗","c":["翀举希凌霄，疾足争先驰。","岂不矜儇捷，劳瘁令人悲。","灵源竭深蓄，安睹清涟漪。","达非徒自荣，塞贵坚所持。","宝此寿世资，出处两不移。","悯彼荣竞子，自戕安足知。"]},{"t":"送尹四孝廉柏亭下第归里二首 其一","f":"五言古诗","c":["世何爱桃李，桃李多妖姿。","世何爱杨柳，杨柳多柔枝。","妖姿易消灭，柔枝易摧折。","遑复计岁寒，相见成怿悦。","华言互相倾，欺妄联同声。","赋性苟木讷，噂沓憎无能。","文词贵朴老，今人竞佻巧。","瑾瑜耻自衒，谁知是奇宝。","归去东海头，涤荡祛隐忧。","学品唯自信，努力事姱修。"]},{"t":"送尹四孝廉柏亭下第归里二首 其二","f":"五言古诗","c":["神鲤困泥沙，身命亦何轻。","风雷一朝会，飞腾众所惊。","盲俗无定见，毁誉随时更。","昔日谗谮子，身贵来佳名。","君当效鸾鹤，奋翼起高鸣。","郁郁守蓬荜，谁能谅其诚。"]},{"t":"孙烈妇 其一","f":"五言古诗","c":["人生如秋萚，随风递飘落。","年命如朝霜，倏忽晞骄阳。","人鬼互为邻，今古缩朝昏。","朝昏日哀哭，天地何不仁。","大义联夫妇，和鸣若琴瑟。","男儿重功名，安能免离别。","忍泪强相勖，柔肠暗摧折。","疑惧正徘徊，遽尔成永诀。","岂复贪馀生，展转空泣血。","何如觅泉台，犹得死同穴。"]},{"t":"孙烈妇 其二","f":"古风","c":["郎去京华道，妾望西湖滨。","功名旦夕成，欢爱亦相因。","情敬方缠绵，比翼忽乖分。","旅魂招不来，惝恍空留连。","庶几堕天?，山岳通精魂。","吁嗟年少妇，矢志金石坚。","金石不苟完，烈女不苟全。","携手游夜台，悲啸转欢言。","玉颜期速朽，贞性还乾坤。","幽足钦神鬼，明亦动九阍。"]},{"t":"节寿诗为邓主事锡礼伯祖母汤太孺人八秩初度","f":"五言古诗","c":["造物无缺陷，人生罕奇节。","万类转鸿钧，灵蠢递生灭。","秀气之所钟，树立迥殊绝。","邓君伯王母，赋性如冰雪。","百年笃坎坷，适以成贞烈。","十八丧所天，吊影啼孤鴂。","痛欲殉九京，高堂念方切。","俛首事翁姑，儿职代无缺。","犹子锡礼父，茕茕四龄孑。","保抱如亲生，注望隆阀阅。","恩勤未及立，遽尔随电掣。","太君偕幼嫠，性命相依结。","是时锡礼君，襁褓犹未脱。","众雏仰重慈，存孤互提挈。","天意酷诸孙，母氏复永诀。","柩下绕孩啼，索亲泪成血。","酸声剌慈耳，听之心惨裂。","哀哀寒无衣，未寒谋补缀。","嗷嗷饥求餐，未饥筹餔啜。","熊丸助精修，策励希英杰。","经史穷精微，诗文悬日月。","教育冀有成，劳肩庶可歇。","次第愿有家，襟缡联名阀。","新妇灿成行，云仍绵瓜瓞。","事事身自亲，勤劬心力竭。","戚里称贤淑，天家褒纯洁。","一生历崟崎，坚白老磨涅。","皇天鉴德操，昌后巍科掇。","铨部授分司，太君年大耋。","乞假被新荣，称觥承慈悦。","懿轨播京华，瑶草遍贤哲。","锡礼真贤孙，成名慰白发。","太君顾之笑，欢极反悲怛。","回首忆诸艰，泪下声呜咽。","鹤发映霞篁，玄芝采盈襭。","松柏色不寒，云鸾奋丹穴。","禄养正无疆，食报非饕餮。","伊余愧不文，巴词为细述。","岂足备风诗，表微励闺闼。"]},{"t":"国云浦来自辽东已四日矣不我肯顾郁思曷申欲往从之复愁道左聊述短章用达鄙意","f":"五言古诗","c":["客往辽东去，关山阻修越。","客从辽东来，奚囊贮冰雪。","见君诵君诗，兼之释饥渴。","胡为不我顾，令我增愁结。","我有一尊酒，足慰风尘客。","思欲携致之，歧路愁行迹。","既驾情已驰，徘徊复回辙。"]},{"t":"和云浦送春之作","f":"五言古诗","c":["浮生若梦寐，能得几时好。","况我年就衰，蜗居怅枯槁。","户外春忽来，欣然见庭草。","选胜携芳尊，花间坐闻鸟。","结念方未申，春去一何早。","韶华难久留，百年亦易老。","一觞聊自吟，念之伤怀抱。"]},{"t":"送国云浦之蓬溪县任二首 其一","f":"五言古诗","c":["岩冬风雪交，凛冽摧羁客。","念尔远行人，道路逾千百。","衰年多暮感，聚散何悤迫。","与子十年交，欢晤几晨夕。","伤离情倍亲，疏阔悔畴昔。","老泪向君弹，眷恋无终极。","邛郲虽云险，叱驭挥前策。","燕市有贫女，馀光候邻隙。","升沈道各殊，相期勖明德。"]},{"t":"送国云浦之蓬溪县任二首 其二","f":"五言古诗","c":["男儿抱伟志，富贵非所希。","因循竟无成，日暮伤路歧。","赖有青云交，时吐胸中奇。","今复去万里，再见知何时。","高馆列绮筵，纷纶进华词。","临觞不能饮，默坐含酸悲。","年老别离难，况是平生知。","束带候明发，宾众出郊畿。","行李已戒途，望望情远驰。","情驰结中夜，髣髴见容仪。","愿言慎始终，慰我长相思。"]},{"t":"连夜不寐因成苦调","f":"五言古诗","c":["玄冥作重阴，惨雪纷扬播。","冽冽交树风，凛凛侵书舍。","侧闻煖寒杯，欢歌动四座。","歌声遏行云，欢呼累长夜。","顾影自生怜，终宵不能卧。","万感结愁肠，默默对书坐。","出处两无能，生涯日趋下。","忆昨返家门，妻孥令我怕。","悴憔非人形，悬鹑仅掩胯。","战慄向我言，口噤艰出话。","室内静炊烟，盎底积尘堁。","绕膝黄口儿，苦道腹饥饿。","哀哀哭叫娘，顿足裂衣破。","相顾正徬徨，高呼索租课。","婉语丐迟期，嗔怒杂嫚骂。","身贫世所欺，非关性怯懦。","此境谁能堪，听者足惊讶。","皇天岂不仁，我独遭坎坷。","年衰悲道穷，八口任难卸。","炎凉迥分途，馀光耻相借。","逼处实在兹，展转增摧挫。","东方日不明，歌钟且未罢。","安得酒如渑，沈湎纵杯斝。","既令百情远，又令磈礧化。"]},{"t":"送王兼善之任黔南锦屏县任二首 其一","f":"五言古诗","c":["人生不相知，百年徒聚首。","声气偶一投，万里如左右。","往昔少壮时，慷慨慕良友。","献策来京门，疏狂纵杯酒。","酒酣诗亦成，往往在人口。","流传感君听，谓我才八斗。","抚躬虽自惭，思君愿携手。","客路每多歧，未免牛马走。","蹉跎出雄关，遂令此情负。","嗣复各一天，宦途岂能偶。","知己会良难，神交实已久。","去秋一邂逅，既见还疑否。","相对如梦中，相怜惜老丑。","所幸身尚存，相期各不朽。","岂谓事多违，离别随其后。","相送发长吁，寸心诚何有。"]},{"t":"送王兼善之任黔南锦屏县任二首 其二","f":"五言古诗","c":["世路随所遭，飘忽无定依。","欢会如浮云，聚散岂能知。","结思三十载，一见已酸悲。","晤言未几日，又值今乖离。","尔我况迟暮，谁复能堪兹。","蛮荒万里外，令我神魂飞。","重逢昧远识，初心贵不移。","与君慎厥终，百岁以为期。"]},{"t":"壬申三月三日李眉山招同人万柳塘修禊宁王喜闻其盛亲携杯茗肴核以助雅游 其一","f":"五言古诗","c":["三月月初三，品类畅以达。","幽人识化机，真想在林樾。","修禊联同声，尊俎待名哲。","晨出践佳招，襟怀顿披豁。","念子隔层阿，经时恨契阔。","良辰共褰裳，遵渚采芳洁。","迟暮感人心，兰英亦易歇。","眷兹文酒欢，嘉会岂中绝。","三五清辉圆，期君弄明月。"]},{"t":"壬申三月三日李眉山招同人万柳塘修禊宁王喜闻其盛亲携杯茗肴核以助雅游 其二","f":"五言古诗","c":["造物运无心，浩然化育流。","胡为古昔人，而能与天游。","真机畅胸臆，触景成奇搜。","况兹大块春，兰茝盈芳洲。","斯理苟不达，多为形迹留。","贤王具旷识，万物将同俦。","憺然忘物我，情与韦布周。","梁苑侣邹枚，陈思宴应刘。","惭乏数子才，安能扬其休。"]},{"t":"入安化寺诗社","f":"五言古诗","c":["夙昔抱微尚，丘壑结遥思。","一为尘网羁，此志终弗遂。","时每出郊坰，挈杖寻初地。","聊博少时欢，岂足酬幽憩。","不谓素心人，相期同把臂。","僧寮作诗坛，窅然忘尘世。","咫尺不见招，知非我遐弃。","误疑精力颓，而不耐劳瘁。","闻之即披衣，既见果无异。","阴阴苔雨痕，翛翛竹风籁。","流水清俗情，孤云淡尘累。","既不废游观，且联文友契。","遥谢沮溺翁，远遁诚非计。"]},{"t":"柬同社诸君","f":"五言古诗","c":["孤云久无依，倦鸟亦应返。","胡为迟暮年，而不思栖遁。","劳生会有营，泉石情空缅。","俗务讵能羁，人苦不自遣。","方外觅佳游，聊作尘世隐。","况兹同社人，襟期尽萧散。","相见无俗谈，淹留畅清眄。","触目各成吟，晚就斋厨饭。","入山何必深，会心不在远。","形迹谁能拘，越礼亦非善。","岂学嵇阮徒，山阳恣慢诞。"]},{"t":"癸酉上元后一日集安化寺续同明旧社","f":"五言古诗","c":["皓魄悬青霄，九垓照何广。","奔走汨嚣尘，有月谁能赏。","遂令太阴光，高空自来往。","都城城东隅，安化胜地敞。","卓哉山阴翁，襟怀超世网。","雄帜树词坛，应声纷肸蚃。","余虽老不才，振策亦趋向。","俗虑澄冰壶，新裁共抵掌。","鬼伯妒高明，变故生俯仰。","朱弦转哀些，阴风吹穗幌。","吟魂渺何追，风雅沈榛莽。","开春月复圆，流晖照人朗。","同辈集精庐，触景情惝恍。","山阳笛韵悲，泣下同慨慷。","因思续旧盟，兼之慰灵爽。","旧契燕名流，新知鲁夙养。","嗜好薄膏粱，章甫更鹤氅。","道机生静缘，奇情逗灵壤。","愿言笃久要，姱修懋远想。","天地有阴晴，明月递消长。","同盟期不渝，渣秽惭涤荡。","大业贵大醇，磋磨望吾党。"]},{"t":"题运使卢同年抱孙画屏十二首 其一 雅集图","f":"五言古诗","c":["通籍客京华，身显心仍寂。","耽吟聚名流，溪山亦生色。","春秋佳日多，尊酒谋良觌。","倚树听新声，涉露采芳泽。","振笔发高吟，奇情透金石。","欣赏倾众情，欢饮忘形迹。","日落各言旋，相思复相觅。"]},{"t":"题运使卢同年抱孙画屏十二首 其二 载酒图","f":"五言古诗","c":["群峰耸苍翠，延赏豁心目。","载酒呼朋俦，探奇向山麓。","登顿出云厓，烟霄聊置足。","俯躬拾琼玖，举手揽朝旭。","万象逞殊观，胸臆屡超忽。","凭虚发长啸，流声振林谷。","乘醉招鸾凰，高情逸埃俗。"]},{"t":"题运使卢同年抱孙画屏十二首 其三 试茶图","f":"五言古诗","c":["政简夜心清，明月照幽独。","春露泫杂花，微风扇芳馥。","崖窦溜鸣泉，泠泠漱疏竹。","掬之注精窑，活火煎虾目。","拭盏试龙团，芳香透毛骨。","采焙法羽刍，封题贮箱簏。","敬慎小臣心，涓滴沾殊渥。"]},{"t":"题运使卢同年抱孙画屏十二首 其四 看花图","f":"五言古诗","c":["在昔宋广平，世号铁石肠。","及其作花赋，彩藻何芬芳。","万物生有情，背之多不祥。","百花逞奇丽，大块情所将。","此身随化转，当春神明昌。","至道怀环玮，掸掞胸中藏。","日莫采兰归，佩之终不忘。"]},{"t":"题运使卢同年抱孙画屏十二首 其五 浚湖图","f":"五言古诗","c":["昔人盛游览，杭颖无低崇。","风雅久沦没，废为葭苇丛。","譬彼亿兆情，壅滞不得通。","虽有惠下心，政治难为功。","贤牧为疏导，众生欣相从。","天水望空阔，豁然开心胸。","中流一洒酹，怀古酬高风。"]},{"t":"题运使卢同年抱孙画屏十二首 其六 文宴图","f":"五言古诗","c":["美玉耻自炫，湮没岂初心。","同气不相求，吾道将中沈。","所贵忘势分，亦在真知音。","大名久自擅，诗酒偕登临。","遂令枯寂士，声誉驰古今。","此意良独厚，世罕测其深。","至今平山上，谁复能追寻。"]},{"t":"题运使卢同年抱孙画屏十二首 其七 北顾图","f":"五言古诗","c":["北固当金焦，京口为门户。","大江日夜流，滔滔自隆古。","万派此中分，千峰奔栋宇。","兴废感梁陈，苍茫辨吴楚。","广陵谢榷鹾，边庭将射虎。","男儿志四方，敢复怨行旅。","北顾心神伤，依依恋明主。"]},{"t":"题运使卢同年抱孙画屏十二首 其八 注易图","f":"五言古诗","c":["古人处忧患，著书长不朽。","出身膺世务，此事不暇有。","宽閒天付君，大业期担负。","旷渺无杂缘，神明通户牖。","心游法象初，道阐羲文后。","济蹇宜反修，默默验奇偶。","通塞何庸心，艰贞以自守。"]},{"t":"题运使卢同年抱孙画屏十二首 其九 喜雨图","f":"五言古诗","c":["滦水不上天，旱魃形狰狞。","小民惧无岁，嚣然遂不宁。","抚之失其道，何以销未萌。","奉诏起循吏，精祷格皇灵。","化雨应时来，枯禾尽回生。","发粟宥其愚，众庶歌欢腾。","天人相感召，斯理洵可凭。"]},{"t":"题运使卢同年抱孙画屏十二首 其十 授经图","f":"五言古诗","c":["魏相宰茂陵，文翁治巴蜀。","经术持化民，往往易成俗。","使君今名儒，建塾亲教育。","俗学每拘墟，糟粕转相勖。","岂知导肯綮，批却随心目。","况以身为律，宁不争自淑。","士气顿改观，英才待收录。"]},{"t":"题运使卢同年抱孙画屏十二首 其十一 观海图","f":"五言古诗","c":["中庭悬沧溟，云涛翻栋宇。","据厓者为谁，浩落须眉古。","仰看蜃市变，俯视蛟螭舞。","隐显虚无间，三山若可睹。","惝恍群灵来，杂遝偕风雨。","此际一乘槎，大药应相许。","望望驰心魂，飘然若空举。"]},{"t":"题运使卢同年抱孙画屏十二首 其十二 乐山图","f":"五言古诗","c":["达人无滞情，出处随所宜。","茫茫涉宦海，倦游亦应归。","况兹岁云迈，风波时有之。","缅彼山嵯峨，终古无改移。","山椒招白鹤，山麓采紫芝。","烟霞换身骨，岁久不自知。","乐山诚至计，勿为世所欺。"]},{"t":"题亡友史即山行乐","f":"五言古诗","c":["少壮游京华，驰骋声誉场。","王侯争识面，裘马趋道旁。","轻财重然诺，挥斥千金装。","阴风吹盛夏，呼吸变炎凉。","魑魅不匿山，行处难周防。","中年易名姓，归隐剡溪旁。","剡溪入空谷，猿鸟愿同行。","长林任偃蹇，流水清俗肠。","科跣挹凉飔，濯缨晞朝阳。","岁久毛骨换，因之乘鸾凰。","兹图俨在目，混俗岂云臧。","人事多错误，高蹈遂不遑。","荏苒时已逝，哀哉悲溘亡。","赍志不能遂，魂将返故乡。","诗名满畿甸，永为词坛伤。"]},{"t":"题乔氏家乘","f":"五言古诗","c":["亭亭百尺松，枝条森以茂。","洪柯岁月深，山灵亦阴祐。","源远自流长，斯理非虚谬。","四马兆高门，充闾德由旧。","苟无忝所生，亦足昌厥后。","锄兰莫锄根，锄根兰不秀。","培土莫培浅，培浅易倾覆。","生计讵不营，方寸宜耕耨。","立身期显扬，成名羞秽窦。","以此遗子孙，绳绳尽堂构。"]},{"t":"题刘至诚行乐","f":"五言古诗","c":["溪回荡云容，虬松势妖矫。","日月摩高巅，石瘦青苔老。","科头信芒鞋，临风恣幽讨。","箕踞憩云根，苍翠午阴悄。","触目与神谋，精理扩怀抱。","得意已忘言，隔涧闻幽鸟。","邃壑古烟深，呼童觅瑶草。"]},{"t":"题王郎中兰谷古槐堂二首 其一","f":"五言古诗","c":["好鸟偕其侣，同飞复同止。","志士抱奇情，慨然慕知己。","白璧委泥涂，光辉非始初。","遇者弃不顾，难言兹器殊。","伏枥上峻阪，老骥愁日晚。","伯乐一下车，众乃惊奇罕。","两物不相关，契合诚良难。","磁石与铁俱，安得不留连。"]},{"t":"题王郎中兰谷古槐堂二首 其二","f":"五言古诗","c":["兰谷居兰阳，高卧古槐堂。","堂中午梦醒，蚁视侯与王。","种槐槐成樾，培根根固结。","花叶荡清风，吹香香不绝。","上有鸾凰雏，栖托长自娱。","文彩华且丰，口衔瑞国图。","振翮辞故巢，高飞来上都。","上都罗俊彦，君子将豹变。","枉驾戾蓬蒿，遂此平生愿。"]},{"t":"题倚松观瀑图","f":"五言古诗","c":["高松摩穹苍，虬龙日吟啸。","飞泉激云厓，终古长浩浩。","高士遣俗情，倚松发长啸。","松老色不凋，泉清净怀抱。","爱此山中泉，熟兹松间道。","清兴嵓壑知，谁与君同好。"]},{"t":"燕山古迹四首 其一","f":"五言古诗","c":["昭王筑金台，折节延奇士。","乐毅感主知，功业从此始。","骐骥不见收，盐车困将死。","古来英俊人，零落随荒枳。","千春感我心，重士昔如此。","凭眺动遐思，落日下颓址。"]},{"t":"燕山古迹四首 其二","f":"五言古诗","c":["萧萧古易水，秋风吹白杨。","荒台恣遐瞩，日暮萦悲伤。","幽蓟多壮士，任侠险不臧。","轻身噬猛烈，白虹经天长。","报丹事不成，荆高空激昂。","吁嗟于期头，千秋谁复偿。"]},{"t":"燕山古迹四首 其三","f":"五言古诗","c":["严霜凋万类，鸱鸮鸣不止。","吁嗟文文山，柴市悲风起。","夸父化邓林，精卫填海水。","岂不知力微，寸心终不死。","读君正气歌，哭君作蒿里。","我哭君伤悲，君悲何时巳。"]},{"t":"燕山古迹四首 其四","f":"五言古诗","c":["夭寿多古坟，秋风草离离。","白日蔽高树，野鸟巢其枝。","终古窀穸下，世替岂知悲。","云仍渺何处，但见牛羊嘶。","吁嗟世上人，为乐安可迟。"]},{"t":"中途阻雨","f":"五言古诗","c":["行路难何如，中途雨不止。","欹侧车毂胶，马卧鞭弗起。","虎豹下崇冈，鸺鹠鸣荆杞。","惆怅日将颓，相顾颡流泚。","遣力觅耕牛，助挽出泥滓。","急遽赴荒村，情词彼已揣。","慢颜捋髭须，居奇横无比。","出险复罹险，日行不数里。","前路正迢遥，囊橐空如洗。","阴云晚复浓，中夜愁欲死。","吁嗟行路难，行路难如此。"]},{"t":"约游王园雨阻不践归而作此将希再聚也","f":"五言古诗","c":["人老春去忙，良辰倍珍惜。","王园秀色佳，新雨涤芳陌。","飞诗约同辈，文酒乐晨夕。","相与理轻舟，荷风引深碧。","或随细流声，泠泠探泉脉。","不则看西峰，偃仰冈峦脊。","山翠落我衣，松风吹我帻。","兴酣发高吟，篇章戛金石。","名胜括奚囊，莺花收蜡屐。","林亭觉增辉，烟霞瘳痼癖。","是夜鬼神惊，精灵骤奔迫。","抗手招雨师，连袂呼风伯。","丘壑忽被囚，芝兰亦妒斥。","巾车毂辐胶，蹇卫足颠踣。","吁嗟离垢场，遂敛高人迹。","归来坐书空，郁郁情莫释。","不分穷途子，清赏亦困阨。","为报山灵知，游兴还如昔。"]},{"t":"索秋吟","f":"五言古诗","c":["秋气尔何物，来亦乌能索。","鸿雁听无声，霜花尚非夕。","隔水望村墟，林色远烟白。","锦藻媚阶墀，离披莲欲落。","哀蛩鸣草根，疏萤度棂隙。","凉雨滴高梧，衾帱夜殊昔。","物色感人心，秋来有显迹。"]},{"t":"拟挽歌词三章 其一","f":"五言古诗","c":["我命自我立，不受阴阳欺。","夭寿无贰理，朝闻夕死宜。","所生诚不忝，造化岂能违。","舜文称寿考，颜冉非短期。","周孔终正寝，龙比死亦怡。","鼎鼎宇宙间，均之全所归。","生理苟不尽，龟鹤亦奚为。"]},{"t":"拟挽歌词三章 其二","f":"五言古诗","c":["性为形之主，形乃性所依。","二者不终聚，性尽形可遗。","所以古志士，生死唯自持。","敏皇若不逮，蓄念人岂知。","修短何足介，圣凡更共之。","肖形百年中，百年能几时。","奄忽溘朝露，此生亦虚縻。"]},{"t":"拟挽歌词三章 其三","f":"五言古诗","c":["四运递更代，精华暗销铄。","形神一夕离，遽尔成徂落。","相送出远郊，幽宫闭广漠。","丰肌岂暂完，蛇孙饱蹊壑。","华堂不复居，山魈款狐貉。","万鬼聚为邻，孤魂何所托。","平生营此躯，百计愁疏略。","绸缪未及终，转瞬随电掠。","人生畴不然，念之徒惊愕。","缅彼古英贤，千秋事如昨。"]},{"t":"雨后游金鱼池因述其事用戒诸生","f":"五言古诗","c":["雨歇云未开，出门泥淖满。","贪幽意兴浓，遑恤途路窘。","欹侧屐屡胶，猿臂时相引。","行潦限危桥，褰裳立展转。","懦者怯弗前，黠者誇捷敏。","方思接后人，超腾戒迟缓。","发言未及终，倏忽自颠陨。","嬉游虽偶然，得失理应辨。","行险难幸全，相期共黾勉。"]},{"t":"夏夜偕许虞辑对月口吟用广其意","f":"五言古诗","c":["日入炎暑消，松际月初起。","清露滴兰芽，幽香散筵几。","浮云淡所之，天容净如洗。","披襟临凉飙，对之洒然喜。","群动渐无声，草虫鸣不已。","岂必出郊坰，已觉忘尘市。","荣华世所希，贫贱亦应尔。","役役空劳生，盈虚有定理。","即此明月光，阴晴亦难恃。","况在天之涯，相对我与子。","与子且徜徉，勿为境所累。"]},{"t":"题柳下饭牛图","f":"五言律诗","c":["垂柳烟霏霏，甘霖沛昨夜。","乘时蓑笠翁，春耕喜初罢。","不闻叩角歌，心知望禾稼。","时复饭牛归，偃仰绿阴下。"]},{"t":"范家店遇雨","f":"五言古诗","c":["夏五岁将半，旱魃诚可危。","甘雨一朝霈，纵横泽无遗。","枯禾顿怀新，欣欣田园滋。","余时在中途，当之心亦怡。","岂不沾衣裳，慰众忘所私。"]},{"t":"喜雨","f":"五言古诗","c":["皇天屯其膏，骄阳烈若燬。","爆尪与焚巫，纷纷议闾里。","仰天望阴云，中夜坐复起。","父老妄奔趋，出入怨妻子。","室家不遑恤，租赋将何倚。","此时远近农，望岁心已死。","倏忽沛甘霖，欢声动远迩。","万汇回春姿，蔀屋纷举趾。","我虽无田畴，深为农人喜。","岁事固难知，已免家悬耜。","随风沾我衣，欣然立庭戺。"]},{"t":"新婚词","f":"五言古诗","c":["首夏熏风长，铿然调玉琴。","弦柱本异体，合并成佳音。","佳音出钧天，声作鸾凰吟。","雌雄相颉颃，听之欢同心。","和鸣自兹始，岁久还如今。","丝白胶复固，缠绵遂以深。"]},{"t":"寄怀眉山","f":"五言古诗","c":["白日下崦嵫，秋风吹广漠。","升高豁远眸，重阴蔽林薄。","愿言怀故人，謦欬俨如昨。","既来不久留，虚斋增索寞。","何当絷白驹，解此五情铄。"]},{"t":"送颜孝廉维聪旋里","f":"五言古诗","c":["世久厌真率，所遇宁不违。","相逢一握手，相聚情依依。","日夕商微言，襟期豁以披。","归怀迫至性，别我天之涯。","离情结春草，千里遥相随。","契阔非云久，胡为歧路悲。","索处寡良俦，惓惓不能辞。","西山有游约，莫负秋风时。"]},{"t":"读任东涧史论呓林等作赋此赠之并示同学","f":"五言古诗","c":["上世重立功，后世重立言。","此间关运会，穷达何足论。","玄圭锡大禹，万古流安澜。","姬公洪制作，能令百代遵。","下此虽乘时，时移绩已沦。","况复但素餐，崇高以自尊。","韦布潜草泽，胸臆罗星辰。","俯仰阅今古，万载如朝昏。","淑身为世范，抱道忘贱贫。","当时莫能用，括囊葆其真。","时复发所蕴，出语惊天人。","幽隐莫能遁，众象穷精魂。","书成世莫识，自足雄千春。","流传如日月，赫赫光乾坤。","造物位奇士，岂与寻常伦。","轩冕膺旦夕，安足荣其身。","立言诚至重，吾辈宜邅迍。"]},{"t":"题郊游听僧弹琴图","f":"五言古诗","c":["山净涤秋霖，皋兰被清露。","时与山僧俱，鸣琴坐幽处。","聪耳涧声流，息虑松风度。","一曲听欲终，精义妙超悟。","天际孤云生，心与孤云去。"]},{"t":"答金仁趾 其一","f":"五言古诗","c":["阴阳旋大造，贤愚杂其中。","纷纭各有营，谁复念所终。","逝者日不息，来者仍悤悤。","逐欲何时已，转盼咸虚空。","哲人遗细务，涤荡开心胸。","立言期利俗，亦足昭洪功。","百年有时尽，垂休将无穷。"]},{"t":"答金仁趾 其二","f":"五言古诗","c":["先民摅奇抱，往往托讴吟。","精华寓糟粕，万古传其心。","婉转诵微言，感我一何深。","岂非发至性，喧以金石音。","余始学吟哦，拳拳遂至今。","变化虽殊端，轨范夙所钦。","非曰乏绮丽，与世相浮沈。"]},{"t":"答金仁趾 其三","f":"五言古诗","c":["咸池久不考，经首遂已沈。","瓴甋竞新响，比户方追寻。","岂不悦众耳，听之伤我心。","大乐溯隆古，高唱驱浮淫。","春雷震大地，万汇出幽阴。","方圆岂能周，所遇成商参。","异道而求安，深非我素襟。"]},{"t":"答金仁趾 其四","f":"五言古诗","c":["大物须大勇，力用方不穷。","苟以径寸莛，叩彼万石钟。","所持既微弱，发响安能洪。","良农无水旱，频年不辍耕。","播植或鲁莽，仍复无秋成。","尔我慕前修，收穫希丰赢。","操狭而望奢，亦防稂莠生。"]},{"t":"乙亥二月望前二日观察卢同年雅雨招同牛真谷沈沃田江松泉游真州潘园","f":"五言古诗","c":["一室閟官署，偪侧忘寒温。","东风洒然至，俄见庭草新。","万类欣向荣，生意陶洪钧。","孤吟寄遥想，畅观大块春。","驰情整巾屐，欲出还逡巡。","观察驻旌节，惠然存故人。","折简治丰膳，邀我游潘园。","杂花烂丘壑，修竹森琅玕。","登楼豁远眸，遥见江南山。","山色带长江，烟水罗青天。","飘忽悦高鸟，胸臆超云峦。","主宾况名辈，歌咏凌谪仙。","直令造化机，蓊勃摅毫端。","兹游洵足乐，俾我情屡迁。","还期理舟楫，一泛西湖滨。","归来握诗卷，重访平山巅。"]},{"t":"雨后读吴好山诗刻","f":"五言古诗","c":["晓风散微凉，阶前昨夜雨。","浅草新绿滋，佳禽隔窗语。","独坐闻皋兰，幽香度远渚。","展读好山诗，萧然涤尘虑。","仰首见孤鸿，遥向前峰去。"]},{"t":"赠吴好山","f":"五言古诗","c":["庞公隐鹿门，申蟠潜内黄。","岂乏用世才，实为廉耻防。","灿灿繁华子，奔趋日不遑。","一朝矜所得，顾盼生辉光。","高人慕云鹤，摩霄振六翮。","宇宙任逍遥，时与飞仙约。","回首望尘寰，纷纷叹销铄。","同声每相应，山川失寥廓。","偶来武陵城，邂逅钦述作。","相与一把臂，足以慰离索。"]},{"t":"邀张封君建宇金孝廉棕亭门人诸生施铁如国学陈竹香潘园看桂花","f":"五言古诗","c":["秋日天气佳，斗酒邀近局。","同志四五人，联袂趋名囿。","缘径匝修篁，涧户纷纡曲。","海棠娇向人，秋心若相属。","桂树隔重廊，芳馨远迎扑。","坐久凉风生，纷纷落金粟。","忆昨酷炎晖，看荷爱清穆。","几日未开扃，商声动林谷。","感兹岁月驰，登楼畅襟目。","连峰翠障深，中有高人宿。","长江终古流，帆樯日争逐。","喧寂虽殊趋，百年从所欲。","我老无奢营，所愿亦易足。","随时惜良辰，鸡黍聚文族。","谈笑狎樵渔，登眺无拘束。","重阳节复临，还期醉篱菊。"]},{"t":"挽词二首 其一","f":"五言古诗","c":["荣名众所希，得失有天意。","奈何辱其身，辛苦工献媚。","官骸失所司，精神竭寤寐。","喜怒伺奴颜，丧心倾所忌。","词色一相假，欢跃矜同辈。","妻孥不忍闻，旁观耻无地。","自谓巧入神，崇高可立致。","孰与鬼谋能，变更出意计。","转福为祸胎，历历诚可畏。","荣竞无时休，恻然悯众慧。"]},{"t":"挽词二首 其二","f":"五言古诗","c":["美利众所歆，称心有止极。","天道恶盈满，贪夫长戚戚。","金玉积邱山，贫者望涓滴。","邻里死饥寒，亲知行乞食。","哀声听不闻，黎颜见岂识。","逐臭无时休，昧厥死期逼。","馋鬼啸萧墙，祸变难意测。","荆棘上华堂，蜗涎遗断壁。","似续苦无依，转幸他人泽。","烱鉴悬当前，仁者为悲恻。"]},{"t":"题棕亭秋江拥棹图","f":"五言律诗","c":["木落秋气深，江声日东泻。","扁舟独往情，岂为耽休暇。","旅雁唳霜皋，孤月耿遥夜。","时发游子吟，暂泊枫林下。"]},{"t":"咏史七首 其一","f":"五言古诗","c":["中山飨朝士，子期忽不与。","忿怒搆楚师，国亡何悤遽。","壶浆悯饥人，事亦偶然遇。","危急徂厥亡，仓皇绝生路。","讵知饿夫儿，赴难无转顾。","怨亦不在大，恩亦不在小。","生死判一餐，报施亦何巧。"]},{"t":"咏史七首 其二","f":"五言古诗","c":["始皇愚黔首，焚书坑诸儒。","扶苏谏不纳，远使西防胡。","鲍鱼一朝臭，贤嗣遭枉诛。","元凶得肆志，万姓怒已张。","英雄起草泽，嬴族遂灭亡。","祸机之所伏，天人岂渺茫。"]},{"t":"咏史七首 其三","f":"五言古诗","c":["宋国有义士，父子目俱盲。","天道祐良善，此理疑荒唐。","楚人逞兵威，杀戮填沟隍。","失明者不役，遂得安其常。","人世有迍邅，勿遽云不祥。"]},{"t":"咏史七首 其四","f":"五言古诗","c":["名利中人心，父子且相啖。","乐羊伐中山，食子事已惨。","犹曰忠其君，绝恩露肝胆。","列鼎烹而翁，分羹语何险。","英雄不顾家，言出事幸寝。","敌倘不受欺，大恶将奚掩。"]},{"t":"咏史七首 其五","f":"五言古诗","c":["汉祚至桓灵，气节竞相尚。","处士操权衡，贤愚尽倾向。","矜誇标俊厨，置身千仞上。","谁甘处卑污，侧目兴群谤。","党锢祸遂成，国脉因之丧。","岂若申屠生，与世不相抗。"]},{"t":"咏史七首 其六","f":"五言古诗","c":["英雄抱伟略，徘徊营四海。","卖畚向田家，举世谁知己。","中原正陆沈，怀才忍坐视。","杖剑诣军门，献策赤须子。","扪虱但空谈，瞻乌竟何止。","飘然西相秦，中心岂得已。","人生感意气，功名偶然耳。","千秋谅其衷，初念不及此。"]},{"t":"咏史七首 其七","f":"五言古诗","c":["阴阳相剥蚀，龙战血玄黄。","唐祚遘阳九，四宇纷抢攘。","忠良死无类，盗贼为侯王。","事理不能穷，天地疑荒唐。","我欲咎真宰，仰视但苍苍。","已矣勿复言，纰缪自鸿荒。"]},{"t":"题陈懿章照","f":"五言古诗","c":["清溪涤炎威，披襟坐危石。","好风吹我衣，荷香度深碧。","目送归山云，冉冉越高壁。","聊舒离俗情，淡尔出尘迹。","松泉伴幽栖，苔径谁通屐。","稚子戏膝旁，天机随所适。","瑶琴设不弹，知音世难觌。","道书不去手，冥心唯自绎。","归来一局棋，山月挂檐隙。"]},{"t":"题冯玉轩纳凉小照","f":"五言古诗","c":["朱明耀炎威，局蹐诚难度。","临水敞华轩，披襟坐晴曙。","万象澄氛埃，方塘夜初雨。","莲净生昼凉，轻风散高树。","芳气袭人衣，閒情缓舟趣。","延乐玩鱼禽，天机偶然遇。"]},{"t":"题陆用九行乐","f":"五言古诗","c":["郁郁长安道，心境久不清。","时复探丘壑，翛然怡我情。","幽憩发遥想，之人渺云层。","觏君倾坦率，君意如渊澄。","身世亦尘市，山林托孤鸣。","山中何所见，历历苍松青。","林中何所闻，寒泉声泠泠。","苍松多劲节，寒泉非俗营。","乐此远人境，将同鹿豕盟。"]},{"t":"题友人秋郊野望图","f":"五言古诗","c":["萧萧庭树鸣，嗷嗷雁鸿度。","倾耳尽秋声，秋容邈何处。","呼童携尊罍，缓辔郊原路。","芳菲节已非，凝霜结寒素。","红叶遍山明，朱霞媚烟树。","西风作新凉，披襟野延伫。","云色杂阴晴，山容递回互。","清瑶落远椒，鳞鳞杳东注。","空翠湿人衣，林深失昏曙。","瞩兹秋景佳，畅君泉石慕。","驻马索大觥，雄饮不知数。","暝色带栖鸦，归吟白雪句。","绘作西郊图，超然出尘趣。"]},{"t":"茶宗室八十初度","f":"五言古诗","c":["乔松何不凋，苍根结深谷。","老鹤何长年，霜毛戢幽麓。","缅彼遐龄子，韬机寡营逐。","世苦纷自戕，心悴形讵淑。","盈缩不在天，达人解真福。","祖烈晋王封，丕承隆帝族。","富贵等秕糠，抱道甘岩宿。","静寂可忘年，真机畅幽独。","耆德表群公，教育董天属。","忠孝督童蒙，敬慎儆夕夙。","圣意眷方隆，虚怀忧覆餗。","告休缱绻衷，岂为侣鸥鹿。","三凤声闻高，风翮九霄速。","继述尽英奇，烟霞遂贪欲。","轩车下蓬蒿，迂儒荷青目。","忘分交情深，坦白露真朴。","值君杖朝期，称觥惭苜蓿。","何有罄交欢，荒词为君祝。"]},{"t":"胡母王孺人寿","f":"五言古诗","c":["亭亭老松柏，苍苍抱贞坚。","深根盘厚地，秀色磨高天。","阴阳不能囿，蓊郁巢云烟。","中有鸾凰雏，荫此百尺巅。","振翮属霄汉，文彩凌星躔。","衔图瑞邦国，因风起联翩。","顾瞻高堂上，松柏无改颜。","造物之所钟，谁能测偏全。"]},{"t":"庆母赵恭人节寿","f":"五言古诗","c":["凝膏有馀光，朱火扬其辉。","幽兰有馀馨，清风播阶墀。","繄母裕伟节，造物显其奇。","淑慎自生初，内则娴弱笄。","嫔为君子配，翱翔警房帏。","相助历官阶，廉能声誉驰。","一旦失所天，砺节如金石。","奉尊代良人，甘脆竭心力。","高堂逾大耋，慰若儿侍膝。","糜鹿衔芝草，呦呦鸣其麛。","双双巢中雏，引羽习高飞。","教育各成名，辛勤侔断机。","文孙服母诫，一一皆国器。","鸾凰奋阶前，联翩纷接翅。","宰辅旧家声，箕裘昌厥继。","维皇笃坚贞，锡予大年岁。"]},{"t":"冯玉轩六十初度","f":"五言古诗","c":["灵椿膺殊钟，逍遥傲寒煦。","春秋以八千，大物此其固。","磐石亦何奇，幻历万烟雾。","坚贞者不华，人罕知所务。","涉世难孤清，蓄意轶朝暮。","滞虑涤歆戚，休拙迥殊路。","冯公道合兹，淡尔世情慕。","古貌屏腴谈，丰植若寒素。","今当甲子周，一阳萌初度。","须发耀漆光，精神抗松簬。","岩鹤戢霜翎，冰胎结梅树。","称觥敞歌筵，貂锦宾姻聚。","巨觥共八仙，还各持一具。","旋饮旋复添，赴喉如泉注。","虚疑力不胜，观者咸惊怖。","须臾尽百人，周旋仍故步。","既发老者叹，还生少年妒。","即事徵遐龄，岂局阴阳数。"]},{"t":"尤母金孺人七十寿","f":"五言古诗","c":["源泉澄幽深，浑浑流清白。","巨岩蟠洪柯，亭亭茂松柏。","缅彼尤子母，平生抱奇节。","生子能文章，幽光讵磨灭。","七十寿小春，寄言心素折。","淑质育名门，懿行践贤迹。","妇德钦夙成，于归卜尤吉。","浙东联北平，门楣缡远结。","舅时副总戎，桓桓列棨戟。","族盛家政繁，坐理无纷剧。","先意承朝昏，器使良楛别。","舅曰妇贤能，母心愈凛慄。","盛衰多倚伏，卓识超巾帼。","相夫终明经，高蹈乐泉石。","愿偕冀缺妻，韬光馌阡陌。","所天遽不禄，素志增呜咽。","痛欲随九京，肝肠免碎裂。","顾兹柩下儿，大义难决绝。","习苦励熊丸，画荻寸阴惜。","阀阅惧衰谢，督责心转迫。","齑粥潜辛酸，寒灯照孤孑。","坚此铁石心，冀子成名切。","孟仁激母教，感痛奋自策。","精理研纤微，摛毫祛诡谲。","忆昨战秋闱，立可彰母烈。","风翮碍九霄，霜蹄偶一蹶。","造物位杰士，不拘寻常格。","学使采笃行，排众独超擢。","行当荐九重，功业难意决。","有子既不群，足以慰畴昔。","况母寿无期，甘脆陈瓜瓞。","积厚自流光，谁曰非母泽。"]},{"t":"进学篇寄坦居五弟","f":"古风","c":["君不见东鲁泰岱高绝淩青天，磨厓日观穷跻攀。","扪萝披石蹑危磴，耸身直上云霞巅。","又不见黄河穿塞决昆崙，排山倒海驱蛟鼋。","冲波逆折不畏险，扁舟直抵银河边。","仰止胁息坐长叹，望洋惊阻空流连。","邱阜之堤，沟浍之水，亦将听其嵯峨而潺湲。","君不见仲尼没后圣道孤，奸臣贼子无日无。","辟杨排墨正人心，子舆生将天地扶。","干戈扰攘递狂秦，文运否极遭屠诛。","董子崛起烈焰馀，天人义利非龃龉。","承先开后赖此人，诚哉不愧为醇儒。","自汉以还千馀年，出玄入空纷驰驱。","择焉不精语不详，茫茫道脉悲荒芜。","五星聚奎炎宋兴，名儒辈出微言明。","人知尧舜皆可学，日月丽天江河行。","天生大人何巍巍，赋性不异我与而。","男儿奋兴能自立，邵大周精安足齐。","君不见一篑为山平地中，累累不绝起高峰。","疋缯将完丝忽断，机轴空劳不成练。","地易崩摧天易老，日月禅代无昏晓。","人生百年能几时，朝如春花暮秋草。","青年乘时不早图，倏忽万类同枯槁。"]},{"t":"题王母蟠桃图","f":"古风","c":["青鸟□书过西海，祥光瑞霭腾蓬莱。","紫电鞭龙役鬼神，鸾旗绛节排天开。","排天开，天乐发，飞琼曲度流云遏。","纤罗雾縠焕云霞，羽盖飙车驻承华。","承华殿上谒天子，缥缈仙音清入耳。","云是九灵太妙，龟山金妪。","先天地生，阴阳未布。","转辰枢，立鳌柱，曾见日浴金乌月生兔。","纵横八极播洪钧，出入九重紫微步。","迩乃衍乎阆苑憩昆崙，瑶池翠嶂漫烟雾。","弱海洪涛万丈深，影灭轮回安可渡。","明星玉女供玉浆，麻姑搔背指爪长。","三千岁结蟠桃香，钱铿小儿未及尝。","老二仪，凋三光，独有刀圭不死之神方。","蟠天际地任翱翔。","语阕玄灵忽迓空，神云飘举回鸣珰。","武帝玄霜终不得，金掌高擎空断肠。"]},{"t":"宝剑行","f":"古风","c":["洪钧陶铸昆吾冈，木厉遁辟山精藏。","腾雷滚电揉阴阳，天神惊愕来趋跄。","海岳为锷日为光，星辰的烁森锋芒。","莫邪焚身干将亡，精魂幻结双龙翔。","大江水阔磐石厚，淬砺寒光贯牛斗。","团金镂玉献明王，旷代奇功垂不朽。","割下银河天上水，大沛苍生无冻馁。","割去太虚云与霞，天容日月增光华。","割去泰岱嵩衡千万山，尽教大地成良田。","剸蛟截兕魑魅惊，海不扬波陆路平。","旋取人间心与胆，割去险巇留平坦。","那堪终岁壁间悬，吴钩卞匣尘埃满。","空教簏簌灿流霞，龙藻龟文气亦短。","昨夜风雷匣中吼，千人辟易惊却走。","天高路远鸊鹈稀，铜花锈紫镡龙口。","叹息抽看破牖光，飞跃神威脱吾手。"]},{"t":"题刘道官画像","f":"古风","c":["冠峨带博杂金玉，厚貌丰髯气蓊朴。","方士不受衣冠羁，胡不黄冠不野服。","自言十五初学道，脚踏天根攀月窟。","眼前富贵等秕糠，澄怀明月秋潭浴。","赤松黄石指顾招，轩冕偏将许由辱。","漆吏原不碍天倪，八口饔飧享天禄。","城隍宫阙尘市中，世守神器饮神福。","尘寰放逸即蓬壶，何必幽深入空谷。","露洗春花月洗霜，浇花听月呼?醁。","邀欢一饮动十旬，不许韶华空去速。","掀髯鼓掌酣且歌，身心直跻神仙族。","始知曲糵胜灵丹，九转刀圭徒自毒。","所贵神仙在欢娱，谁能此身同槁木。","古来熊经复鸟申，劳瘁谁拘死谁促。","眼中如君真达观，余曾跻堂接清穆。","对雪开樽酒政严，罚杯大于市头斛。","三载微名羁帝乡，重访崆峒驾鸿鹄。","凛凛遗貌留人间，眉睫如生观者肃。","赭颜犹带旧酒痕，昔日欢呼俨在目。","何年化鹤复归来，天鸡晓唱蟠桃熟。","此时金樽让绿云，糟邱嵲屼为君筑。"]},{"t":"醉歌行赠叶圣嘉医士","f":"古风","c":["辽海海厉鞭疫魔。","驱风鼓浪注滂沱。","鬼语呼人幻丽娥。","调笑夜月邀女萝。","阴风潜袂舞傞傞。","浃人肌髓成沈疴。","叶生橘种城东阿。","疲癃到处回春和。","独我痼疾奇且颇。","痴癖钝礧填胸窝。","纵使阴阳掌握搓。","十人九视咸吟哦。","力疾曾经冒雪过。","但言沽酒且高歌。","园蔬剪摘春婆娑。","侯■不羡天酥酡。","盍簪玉树珊瑚柯。","分曹对阵列鹳鹅。","争雄树鼓击灵鼍。","酒政恣意生烦苛。","酬酢杂遝挥仙螺。","目眩狂华朱颜酡。","参差众醉声喧啰。","避席欲逃遭主诃。","罚杯大叫金叵罗。","叵罗注酒何其多。","众宾魄夺惊倒戈。","振颈独效长鲸呵。","举觥倒泻倾江河。","二竖错愕争搬挪。","百窍尽为浮蚁窠。","安能纤悉容其他。","天地混沌低昂讹。","胸怀澒洞生洪波。","六腑重结鸣相摩。","毛髓洗伐膏盲瘥。","人生岁月易蹉跎。","少壮几时奈老何。","愁戕虑贼纷逶迤。","当之鲜不磷于磨。","逢场痛饮真神科。","刀圭玄霜尽祸囮。","安得与君百年三万六千日日饮中山之酒三百金卷荷。","糟丘曲车高筑罗列相嵯峨。"]},{"t":"题谢某画像","f":"古风","c":["严风吹空声凛冽，摧肌砭骨须眉磔。","入门呼酒索大觥，指直唇结喝不得。","主人持杯向口倾，手足渐融寒渐释。","绣囊绮匣出真容，丐余呵冻题其额。","展卷霜髭朴貌迎，锦毹云屏俨贵客。","我问主人今何为，面颊生赪气忽噎。","积年旧忿一时来，欲言不言旧嗗呐。","遥遥派系出东山，襄平世职传先烈。","天厌旧德群寇兴，乾坤万象重胚结。","兴朝定鼎有驱除，蛟龙争向朱门活。","飙回影附迹非初，纵是骅骝任驽劣。","语罢呜咽泪沾巾，满堂宾客色不悦。","饮酣狂叫问青天，满地霜华延霜月。","我归出门谢主人，丈夫遇合难豫决。","君不见卫青将相出平阳，史册千秋昭壮节。"]},{"t":"投赠任邱袁明府坼","f":"古风","c":["梅岩翁后虞邱长，耳热长安动远想。","繄予寒毡来郡城，霢霂濛濛昼莽苍。","泥淖酿途行人稀，心衋咫尺不得往。","阿香碾空车忽蠹，轮翻倒海雨如注。","雷公头触天关摧，石迸娲皇补天处。","地轴震仄久不安，渔人网触蛟龙怒。","扬鬐掉尾决滹沱，波涛澒洞迷朝暮。","桑麻尽为鳞介居，万倾良田叫白鹭。","我正兀兀愁卑栖，上官羽檄纷飞驰。","七十二村命查验，壮者逃亡老弱啼。","此时披云得见君，痌瘝民瘼真英奇。","民瘼痌瘝起凋弊，有田无田均其利。","叹息与君一夕筹，父母斯民真不愧。","别来荏苒数月间，君名啧啧我丁艰。","五内崩裂死复活，血泪迸洒衰麻丹。","老母促归归不得，去留展转摧心肝。","万里茫茫隔烟雾，生死天涯两难顾。","满室嗷嗷日苦饥，梦魂夜夜辽河路。","经旬不见突中烟，男啼女号命岂度。","男儿生不能养死不葬，何惜此身沟壑丧。","父丧未奔母在堂，迟回未可轻肮脏。","圣贤守身不受怜，事急亦或酌其权。","出门四顾心茫然，投诗赠君君心酸。","赙我百贯青铜钱，此身不死报应先。","上有青冥之皇天，下有浩渺之长川。"]},{"t":"题苏武牧羝图","f":"古风","c":["苏卿奇节古所无，丹青为写当年图。","手持汉节节旄落，驱羝就牧阴山枯。","朔风如刀砭肌骨，瀰漫浩雪埋穹庐。","蚩尤愁惨作妖雾，老狐叫啸群邪趋，孤臣万里将何如。","鸾凤罹笯龙受缚，久?肝脑涂沙漠。","阴阳为炭天为炉，险阻巅危笃攻错。","陶铸伟器撑乾坤，讵比凡材任销铄。","终教皓首复归来，千秋万祀声隆赫。","君不见李陵歌送褰行裾，仰天泣血空欷歔。"]},{"t":"张侍御平魏阉墓碑歌","f":"古风","c":["自古阉竖倾朝纲，前有刘汉后李唐。","受祸无如明代烈，蒙尘土木汪刘猖。","列卿将相尽名士，称功颂德甘奴婢。","党籍诛罗作爪牙，一时英俊难逃死。","熹庙复宠魏忠贤，烈火毒燄熏高天。","醴交势合走东厂，东林善类坑炎烟。","磔死何足蔽毫末，铜驼石马高硉矹。","粪壤壮丽侔桥陵，名胜何辜遭污蔑。","我朝定鼎日华开，曲江风度居兰台。","西山偶停骢马足，秽碑镌列何崔嵬。","孝男孝孙尽勋戚，一瞬空山飞霹雳。","凛然铁笔吹霜风，百年凶臭俄溅涤。","吁嗟乎，当年身首已加刑，即今撮土犹夷平。","后来貂珰应震惧，张公灵爽山林凭。","碧云寺前好云树，去年曾踏盘纡路。","振藜穿翠坐高轩，月照千峰俨凝素。"]},{"t":"云峰歌","f":"古风","c":["自古夏云多奇峰，奇峰乃在山之中。","披襟临风向山坐，山峰云峰争插空。","初如群仙戏山麓，山中有石若琼玉。","初平叱之欲成羊，崭然石上生头角。","鬼物狰狞杂遝来，飙轮火炬空中排。","紫焰光，腾赤蛇，仙灵奄忽遭焚摧。","目眩心摇骇奇绝，淅淅凉飙起天末。","怪形诡状须臾间，纷纷落落归澌灭。","我因述作云峰歌，云峰变幻亦何多。","眼前荣悴速如此，古来万事复如何。"]},{"t":"题阎佩升为卢公亮写岁寒图","f":"古风","c":["天台雁荡绝人境，沧洲渤澥无纤埃。","身婴俗务不能去，目断神游心往来。","阎公逸兴挥毫素，驱风走石沧溟开。","不绘赤城霞，不绘桃与李。","赤城霞色多变端，桃李繁华难久恃。","泼墨写作岁寒图，凝云浩雪纷满纸。","炎天凛凛肌粟生，眼底萧萧朔风起。","何处高人抱膝吟，左有高山右流水。","数点梅花亦可怜，冷艳幽香散庭戺。","秃顶苍松不畏寒，槎枒老干巅厓里。","深山大泽余所思，凤吟鸾啸天为低。","但觉高吟玉屑飞，姓字不愿王侯知。","我今泪尽梁山操，天涯僵卧复谁告。","微名深愧鹤氅尊，东郭先生望晴曜。","削籍归来悲白头，投閒空被山灵笑。"]},{"t":"长城歌题红瓦店壁","f":"七言古诗","c":["日出沧海洪涛里，崷崒千山万山累。","严墙蜿蜒盘峰巅，长城万里从此始。","东连碣石北居庸，西走陕益临洮中。","一道生将天地割，防边设险心何雄。","谁知皇天无私好，四海穷愁戍卒叫。","万世不传二世休，千秋史册空遗笑。","当年筑此胡为乎，祖龙力政非良图。","白骨撑填饮马窟，至今鬼哭声呜呜。"]},{"t":"赠锦府张太守樵客","f":"古风","c":["襄平才子锦城守，政治不异陈太邱。","间关薄宦二千里，企慕但有神交游。","披云一旦昤謦欬，襟怀朗月悬高秋。","诗情突兀轶开宝，落笔耻与黄苏俦。","余曾读君医闾山人雪景歌，大雅独奏谁能酬。","眼前作者徒纷稠，当之不异鸣蝉蜩。","我亦吟哦三十载，曾无一语干诸侯。","钦君大匠运斤斧，愿将良楛从君谋。","洋洋千顷波涛阔，不能利涉增烦忧。","吾闻青芝赤箭兼牛溲，良医药笼罕不收。","茫茫宦海悲白头，徘徊六合谁青眸。","文章有神交有道，少陵此语非虚浮。","龙门快意针芥投，旋随征雁生离愁。","呜呼旋随征雁生离愁。"]},{"t":"索竹诗简庆松乔","f":"古风","c":["阳燧烧空烈炎毒，倒喝亲看人代速。","芭蕉短尽桐叶焦，使我窗前草无绿。","愁死不遑遑计他，惊魂定后思娱目。","浣花老翁平生居，到处先栽数竿竹。","子猷不教一日无，坡仙宁可食无肉。","为爱虚中节复坚，森萃凉飙戛寒玉。","亭亭翠干齐荣枯，精神不畏霜风酷。","我性爱竹逾诸公，尘垢兼须竹浣浴。","相对静夜两忘言，明月高秋伴幽独。","苍根亲许移上林，讵有成言久不复。","君不见眼前繁卉渐枯凋，萧萧飒飒随狂飙。","老夫对此心烦劳，安得劲节排云霄。"]},{"t":"雨中移得秋色十馀株种竹侧意更欲种菊花数十本复简松乔","f":"古风","c":["种得阶前数竿竹，连朝霢霂频浇沐。","檀栾争效婵娟姿，但恨孤丛少联属。","雨中荷锸过西家，移来秋色如春花。","耐寒俗称老少年，不与柔脆同欹斜。","菊花能仙亦能寿，霜姿露质丰台有。","篱边拟种三百株，苍翠隐映成三友。","人生岁月能几何，君颜少壮我发皤。","安得终年局蹐不称意，四时佳景成虚过。"]},{"t":"正气歌为节妇王母单孺人作","f":"古风","c":["乾坤有正气，絪缊磅礴无终始。","铸人形，载人理。","纲常不立，熙熙攘攘，如此而已。","天地虚生亦虚死。","兹气之所钟，不独在男子。","黄鹄思故雄，柏舟悲天只。","铁骨坚刚火莫镕，玉质晶瑩泥不滓。","死者复生，生者弗耻。","精诚可以变天地，梁山一哭城崩圮。","絅先之妇单孺人，矢心砺节无乃是。","结缡岁甫更，良人命忽倾。","愿随地下袪蝼蚁，不愿局蹐贪馀生。","腹中有子难决绝，大义不合鸿毛轻。","夫死三月儿出腹，一线呱呱延似续。","手作口哺傍穗帏，鬼语吹窗枭夜哭。","抚畜廿四年，辛勤难备述。","儿成母责终，贞魂含笑归幽谷。","事达九重苦节彰，寒泉幽壤褒天章，阴灵皓月同辉光。","君不见木槿花，朝始娇娆暮泥沙。","君不见新杨柳，濯濯春条倏枯朽。","陇畔有乔松，亭亭翠盖无春冬。","涧底有磐石，怒涛崩奔不改色。","人生百年瞬息间，砥节不如此，天地虚生亦虚死。","呜呼不及此女子。"]},{"t":"还马歌","f":"七言古诗","c":["塞上长途走原野，蹑蹻趑趄愁踵踝。","事促囊空唤奈何，仓皇借得公侯马。","此马饰鞴玉雕鞍，矜宠刍粮饲大厦。","觔挛骨弱肉空肥，鞭策未施人未跨。","况我书生体不尊，一见骄嘶两瞳赭。","昂首咆哮怒正凶，屈身低辕岂甘下。","决衔裂靷恣奔腾，舆人错愕惊跃冶。","自分寒酸非等伦，迟回牵送主人者。","始知身贱物亦轻，呜呼世路谁相假。"]},{"t":"谢马歌","f":"古风","c":["借马还，走无力，更向谁家干栈枥。","国氏昆季今仲由，轻肥与共常不惜。","投辖留我饮深宵，脱骖赠我真良匹。","此马若识主人心，甘就寒儒受羁靮。","雄姿崷崒岂凡才，气象深沈稳无敌。","间关万里往且还，过都历块无欹侧。","主人德粹马亦驯，讵比从前性猛烈。","始知交友有道物亦然，不称其力称其德。"]},{"t":"题画竹","f":"七言古诗","c":["我性爱竹老成癖，客寓常栽伴孤宿。","为君独抱岁寒心，雨干霜条看不足。","今来塞上无此君，幽梦遥情绕深谷。","我欲披图作卧游，画师今谁能画竹。","与可已没仲圭死，卫风淇水空三复。","玉翁好画古所无，画师为写潇湘图。","展卷琅玕崒森爽，株株卓立根苍梧。","湘娥昼泣天黯惨，呜咽幽涧流清渠。","怪石狰狞立山鬼，云涛烟海相模糊。","炎天挥汗一对吟，凉风谡谡吹蓬庐。"]},{"t":"广西义宁令倪懋公尽难诗","f":"古风","c":["孝廉倪公成都豪，出宰义宁控有苗。","苗性凶顽不可抚，结巢深箐如猿猱。","赤脚腾跳善奔走，杀戮连年到鸡狗。","懋公建议立兵威，当事逡巡畏尾首。","但令亲谕劝，不必事征战。","持重谓能收众心，养晦妄冀凶徒变。","贤宰受檄初踟蹰，拔刀崛起英风徂。","马革裹尸臣子分，但恨谋国非良图。","身探猛虎窟，委作馁兽肉。","未及交一言，蚁聚蜂腾恣芟戮。","手提墨绶血模糊，振臂一呼天为哭。","宁甘寇盗求生全，昂藏八尺蠲溪谷。","杀身成仁未足奇，百计千磨事惨酷。","埋身敲齿截其舌，噀血嗔目犹骂贼。","从者歼尽无一归，沈尸潭底谁能识。","赫然忽动万乘威，雷霆下击成灰飞。","忠魂披发来助战，白昼袒裼为前麾。","寇平事达九重耳，睢阳奇节差可拟。","叹息褒忠异数加，难荫恩荣及儿子。","天家不识颜平原，临难忠丹乃若此，呜呼懋公终不死。"]},{"t":"题观海图为张同年蔚千作","f":"古风","c":["崇明县治海中起，贤宰升高望海水。","元气茫茫浸坤轴，波涛泻入胸怀里。","此中有螺蚌，咀喔浊泥滓。","此中有神鲲，水激三千里。","此中复有三神山，缥缈虚无住仙子。","陶铸尧舜但秕糠，灵风扇物物不死。","天吴效顺蛟龙驯，螭珠烛夜虺蜮徙。","洪濛开辟留大观，生物之奇乃如此。","秦皇汉武一何痴，长生大药空劳思。","圣王有道不扬波，遐荒重译纷来驰。","烟消雾净氛沴灭，日轮照耀扶桑枝。","须知利涉要舟楫，安澜亦借经纶持。","前代此间为要害，设险翻为盗贼资。","余观此图心骇愕，鳌掷鲸呿安可测。","身老飘荡畏风波，每欲浮家苦无策。","何人为我舣灵槎，孤岛群鸥是安宅。"]},{"t":"寄年家子毛秋岑兼广其意","f":"古风","c":["吁嗟毛生酒酣击剑慷慨悲沈沦，臣之壮也不如人，头白犹作诸侯宾。","胸中礧块吐不出，长短讴吟感鬼神。","岂果儒冠多误身，请君听我言其因。","人生休佑仰苍昊，富贵才学兼寿考。","丰兹啬彼理固然，清浊久暂非草草。","君不见长安道上轩盖纷纶驰，坐享庞禠亦岂少。","问谁才名震世高，问谁造诣真奇矫。","一代之中不数见，千人万人可尽扫。","始知世所重者天所轻，人所忽者神所宝。","君今道重身亦尊，君今才大气骨老。","声光万古且长新，讵比世俗营求但目前，朝见荣华暮枯槁。","遭遇自应长坎坷，粗粝自应常不饱。","假使生儿有目不识丁，妄希荣贵希丰赢，轻裘肥马相骄矜。","以其所有易所无，毛生毛生甘心乎。"]},{"t":"为蔚千张同年寿","f":"七言古诗","c":["世人垂老心不灰，谁肯蚤赋归去来。","世人束带走炎午，谁肯脱冠挂神武。","钦君惠政被吴松，至今蔽芾歌村农。","钦君贤名动黼座，井田复古宣仁化。","酬勋三载擢曹郎，惧与胥吏同奔忙。","岂知大厦要梁栋，抽簪啸傲风月场。","风清月朗出泥滓，浮世升沈若流水。","局外閒观十五年，朝荣夕悴纷难纪。","惭余世路遭危颠，无钱难买归山田。","白首寒毡苦不放，海鸥空负前贤篇。"]},{"t":"题乔兆三观荷小照","f":"七言古诗","c":["乔翁入山不入城，烟霞吞纳身骨轻。","久占名山作山主，山中但见鱼樵行。","长安少年誇疾走，汗透衣冠貌尘垢。","升沈得丧岂由人，坐看白衣变苍狗。","遁迹高踪数十年，探幽选胜胸怀宽。","芝草菖蒲岂仙药，甘与苦李安天全。","晚节嗜好同濂溪，芳塘写作芙蓉姿。","芙蓉亭亭水清浅，白鹭閒鸥纷近远。","渔子轻舟时出没，身与烟霞共隐显。","举头天外见群山，芙蓉乱插青云端。","水面娇姿遥映带，樵歌渔唱生宾筵。","披图顿觉心神开，会须对饮三百杯。","高斋四壁无氛埃，香风淅淅空中来。"]},{"t":"题蔚千荷庭 其二","f":"七言律诗","c":["浦鸟呕哑杂渔语，葭菼苍茫失幽处。","荡漾新荷透碧纱，烂漫清瑶洗烟绪。","桃笙含风生昼凉，匡床高枕游羲皇。","閒看浮云任舒卷，棹歌欲下闻沧浪。"]},{"t":"浩歌","f":"古风","c":["既不能招手立挽瀛洲来，又不能骑鹤直上蓬山去。","百尺红尘滚滚中，老弱颠连目空顾。","仙乎仙乎尔独远居缥缈之丹邱，琼阶玉宇结为楼，哀乐不闻心不忧。","呜呼哀乐不闻心不忧，使我盼望生离愁。"]},{"t":"仲夏科东岩招饮并阅近作","f":"七言古诗","c":["山中玄豹深雾藏，化作斑斓云锦张。","丹穴鸳雏戢修羽，彰身瑞彩呈奇章。","君秉丰年良玉质，但加追琢成圭璋。","爱才慕道及衰朽，为君往往酣华堂。","志士立心岂凡近，世间纨裤徒辉煌。","别来三月功力进，摛词造意皆老苍。","骐骥旦暮可千里，讵同驽钝羁辕缰。","况有名师廉衣子，随珠卞璧腾祥光。","袖出数篇曾示我，雷电震绕蛟螭翔。","燃犀照海鬼胆裂，小儒色阻惊且僵。","轨范当前有如此，亦趋亦步名飞扬。","千秋大业期不朽，再与李杜争光芒。","余老才尽不足数，但知君家酒瓮香。","他山之石不我弃，赏奇痛饮呼大觞。"]},{"t":"题教猎小照","f":"古风","c":["不愿学迂儒，终岁朱墨涂。","残书不愿腰金紫，蜗角浮名撄祸枢。","不愿长生学枯槁，不愿选佛髡髭须。","爨下无薪盎无米，妻子呻吟愁欲死。","身中无衣囊无钱，壮士低眉无好颜。","首阳饿夫何足道，端木货殖称高贤。","但能规利博温饱，铸冶洒削人争传。","埋照韬精每相抑，英风有时难自戢。","雕鹗横秋厉羽翰，劲气抟空思攫击。","昔曾写作郊猎图，角弓羽箭神龙驹。","风沙萧萧原野阔，一日怒杀三封狐。","今复绘图坐秋野，丹穴双雏随上下。","秋水为神玉为骨，环立渥洼汗血马。","昂首嘶风若待驰，指授射御何潇洒。","王济爱马谢爱山，马有神骏山幽雅。","旷士襟期烈士胸，欲将二子归陶冶。","莫但拘牵纸上文，坐谈经济成虚假。"]},{"t":"题徐文长败荷画轴","f":"七言古诗","c":["徐生一生任狂率，泼墨有时恣涂抹。","败荷残叶状秋容，挺立泥污伴孤月。","老夫见此心感伤，可怜岁晚徒芬芳，荒江零落缠风霜。"]},{"t":"题王外史昆霞小像","f":"古风","c":["黄鹄飞飞薄霄起，健翮徘徊营四海。","排风捲雾任翱翔，南北东西无定在。","徜徉世外全其天，虞罗至老无患殆。","长安市上繁华郎，裘马照耀生辉光。","坎险当前昧不识，欢娱往往潜悲伤。","兰蕙遭刈岂由人，琬琰器美多自戕。","簪我切云冠，披我芰荷裳。","朝看钱塘水，暮游荆楚乡。","芒鞋竹杖遍天下，遇君燕市结客场。","高楼沽酒说兴废，阴云倏起天苍茫。","钱镠霸业今安在，屈原词赋沈沅湘。","黄金台畔骨已朽，荆高击筑空激昂。","人世沧桑顷刻耳，吊古悲今动流涕。","呕吟长短括诗囊，餐霞茹芝随角绮。"]},{"t":"题查承斋九石图歌","f":"古风","c":["瀚海海涸唯沙砾，地脉钟灵产奇石。","瑰异堪为席上珍，边人顽劣目不识。","元戎秉钺如鹰扬，匈奴遁迹宁边疆。","功成振旅作台辅，囊橐归束巉岩装。","巉岩海石来远服，齐州九点俨在目。","峰峦突兀生烟云，阴森满室精灵伏。","令公一朝欲捐馆，九石如闻鬼夜哭。","旧物飘荡无一存，唯馀此石遗儿孙。","劫火烧质质不坏，至今光怪淩璜琨。","传家至宝非丰殖，无用之用唯青白。","坚金良璧行世间，祸患每为人不测。","君不见藏金坞，燃脐炬发成焦土。","又不见郁林太守贤，至今有石人争传。"]},{"t":"苦雨行","f":"古风","c":["四月五月风怒号，骄阳肆虐田园焦。","放牛悬耒不得种，农家奔诉声呶呶。","群龙忽驾沧海起，昼夜掀翻坤轴洗。","眼前大路成江湖，河决堤崩村落徙。","兆姓披发随洪涛，皇天疾威势方始。","我幸城居免此厄，昏垫途穷阻行趾。","惊闻邻屋时崩摧，中夜哀呼声震耳。","披衣走立不能眠，屋漏淋漓遍床几。","妇孺饥馁难出谋，沾湿欲炙无乾机。","昏昏兀坐仰天愁，掣电惊雷殊未已。","我欲骖神虬乘飞，飂排阊阖陈闵忧。","天高路远无羽翰，耸身奋步行复休，于戏耸身奋步行复休。"]},{"t":"张烈女歌","f":"古风","c":["古今人物之生，尽仰天地慈，天地亦赖人支持。","男儿百行不能践，纲常往往钟闺帏。","闺帏之所钟，难易亦不同。","琴瑟既调弦忽断，捐躯殉夫事每见。","虽云顾义不顾身，犹有恩情中系恋。","岂若亲迎礼将成，合欢顿折孤鸾惊。","凶问骤至不展转，泰山一掷鸿毛轻。","夜台不识良人面，安知儿女情缱绻。","但奉完璧还乾坤，贞魂岂冀旁人鉴。","同时更有烈妇殷，身殒惨酷人佥闻。","奇节真堪作俦匹，精灵携手同芳芬。"]},{"t":"博浪行","f":"七言古诗","c":["沧海壮士勇无敌，博浪沙中奋狙击。","一声霹雳从天来，独夫仓皇丧魂魄。","海内英雄尽惊起，黄石老人心不喜。","涵养新朝佐命才，圮上从容教纳履。","大人举事应天人，堂堂吊伐光乾坤。","尚父渭阳且屠钓，阿衡莘野潜耕耘。","诸离盗贼偶然中，荆高效之空杀身。","黄石黄石知是谁，令我再拜思丰仪。"]},{"t":"沙邱行","f":"七言古诗","c":["荆卿匕首失便利，博浪挥椎复空计。","脱死游魂虐愈张，茫茫莫测穹苍意。","惨酷身兼桀纣行，求仙沧海希长生。","肘腋大憝昧不察，书儒何罪遭焚坑。","悯怓不受扶苏谏，天夺其聪机兆见。","一朝鲍臭走沙邱，矫诏杀兄胡亥篡。","积恶盈辜祚乃终，斩蛇狐啸兴群雄。","族先自赤身授首，子婴馀孽收重瞳。","假使当时刺击死，九有神器归贤子。","干蛊反正迓神庥，天报奇凶岂若此。"]},{"t":"陇上行","f":"七言古诗","c":["沙邱载臭祖龙死，二世流毒势方始。","谁知陇上有英雄，狐啸一声鸿鹄起。","男儿决志四海惊，水深火热援群生。","指挥大权能自握，诸侯听命皆蛇行。","揭竿倡义真豪杰，一夫首难强秦灭。","奈何成败论前贤，吊伐唯称高祖烈。"]},{"t":"题佟钟山先生画松","f":"古风","c":["吾闻黄山之松天下奇，奇物自荷神扶持。","夭矫轮囷岂臃肿，梁栋不用谁残摧。","深山邃谷自千古，唯与猿猴鹤鹿相攀跻。","画师如林苦未见，濡毫惨淡空迟疑。","佟翁健笔古莫比，泼墨淋漓为我拟。","梦中开口群龙趋，幻作精灵出肘底。","阴森鳞鬣蟠樛枝，半似飞腾半枯死。","松根抱石石倔强，石势欺松松谲诡。","松石相争不相让，雄挐怒攫来撑牴。","离奇迥出永嘉僧，健挺空传毕庶子。","茆堂展挂心神开，苍涛声逐清飙来。","惝恍如申夜义臂，杈枒空际排云雷。","又疑老怪潜身骸，遂令晴昼生阴霾。","昨日庭前风雨作，苍茫满壁流烟雾。","呼童收捲复缄藏，恐化神龙向空去。"]},{"t":"题扁舟归钓图","f":"古风","c":["丈夫及壮当封侯，峥嵘气概淩九州。","所如龃龉不称意，飘然一笑回扁舟。","扁舟垂钓锦江涘，万树梅花香国里。","日落收纶每得鱼，烹鱼开酿亲芳菲。","掀髯起舞仰天歌，解曲娥眉弹绿绮。","一阕关山月渐高，少年呜咽伤流水。","流水滔滔去不归，韶华荏苒苍须眉。","绝足名驹志莫展，纯钩黯惨无精辉。","何如饮醇醪嗜甘肥，且歌且醉玉山颓。","美人如花拂枕簟，绣帏香煖留春迟。","男儿读书万卷终，无用耽酒好色谁。","云非我亦长安老羁魄，茫茫四海身无托。","览兹图画动遐思，羡尔浮家祛世缚。"]},{"t":"题猛虎惊群图","f":"古风","c":["君不见辽东东北数千里，连峰叠嶂烟云紫。","中产苜蓿丰且肥，春夏青葱冬不死。","夷王牧马任胡儿，毛色缤纷散锦绮。","填沟委壑自为群，牝牡骊黄难数纪。","扬蹄翘尾嬉天和，雪落冰飞朔风起。","朔风萧萧胡地寒，草枯木槁徒荒原。","饥兽纷驰肆攫猎，虓虎震吼声摇山。","万马詟伏缩如猬，凶挐猛噬充贪残。","群兽因之尽馀肉，岂解驽骏分憎怜。","九方皋徐无鬼相，马真能入骨髓此。","中岂无超群绝足，材埋没荒原杂泥。","滓纵教履尾幸全生，谁解惊奇献燕市。","吾闻道逢老骥脱盐车，仰天嘶沫感知己。","世间伯乐不长生，龙媒困顿应如此。"]},{"t":"早春行","f":"古风","c":["歌早春，歌思窈。","春光可怜亦可伤，词兼哀乐情颠倒。","春过已是二月中，却忆初春春日好。","此时君相正调元，恩及孩虫答苍昊。","繄余野老复何知，但解扶筇事幽讨。","寒风冰雪尚盈途，柳色莺声亦杳缈。","几点梅花天地心，生机勃勃萌芳草。","万类将随大化春，吾辈因之畅怀抱。","欢乐情正酣，忧心忽悄悄。","高谈四座罗佳宾，众中未有余年老。","回首韶华骨暗惊，旧事蹉跎岂堪道。","寄语吾徒少壮人，修名建立应须蚤。","君不见新杨柳，几日秋风倏枯朽。"]},{"t":"觉罗八姑贞孝诗","f":"古风","c":["吾尝披卷读蒙庄，天有所全形可忘。","至人委体若遗土，菁华内运神明昌。","相刃相斗万感集，官骸虽具中先戕。","谁能外形笃至性，祓濯灵府生辉光。","觉罗有八姑，派系出天潢。","父为大宗伯，兄秉节钺膺封疆。","姑生幼伤背，天欲厄之人则强。","世人重貌不重德，恶能低头宛颈希颉颃。","兰蕙甘心在幽谷，不与凡卉同芬芳。","瞻依怙恃永朝夕，天伦无忝乐且康。","研经练史发精蕴，陈椒谢絮殊虚张。","冰作肝肠玉作骨，贤媛自古谁能方。","安得长留此姑作轨范，尽化天下闺阁咸端庄。","奈何维皇不佑善，年未三十旋中殇。","慈闱白发呼孝女，兄亦蹀躞悲雁行。","残编摭拾在人口，将与日月争辉煌。","八十六则圣贤髓，熊熊瑞焰腾篇章。","男儿读书万卷骋才骏，几人肯搆颜曾堂。","见此？","眙应阻丧，抚躬翻觉形摧藏。","吁嗟嘻，我亦具此堂堂七尺之丰仪，嗜古岂屑矜文词。","即今因循忽衰老，不觉汗下惭须眉。","熏沐反覆还自叹，纵能愤激时亦迟。","我朝德化如关睢，公族公姓多歧嶷。","讵意残驱弱质一女子，姱修直与名儒齐。","支离疏，申徒嘉，古人立说非吾欺。","天全真觉形可遗，于戏天全真觉形可遗，高山仰止穷攀跻。"]},{"t":"题聂松厓印谱","f":"古风","c":["君不能身佩长剑趋明光，又不能手提孟劳开八荒。","郁郁蓬荜不得志，慨然嗜古穷轩苍。","一艺精专可千古，何须奔走荣名场。","但持昆吾五寸铁，直探隆古龟龙穴。","阴晴寒暑四十年，心摹手拟精神结。","天不雨金鬼夜哭，魂招斯籀来奔谒。","长安文苑多英奇，挥毫洒墨咸繇□。","偶得邀君为篆刻，便觉名姓生光辉。","陋我逢君苦不早，晤言欢若平生好。","为我购石镌数方，但觉鸿黄气邃窈。","印谱传为希世珍，谱中人识辽东老。","文三桥，何雪渔，高名已并前贤驱。","劝君怀宝且归去，烟霞啸傲栖蓬庐。","蓬庐之乐乐莫比，琬琰休向街头市。","君谓绝技可赢饶，千里辞家客燕邸。","时方重利较锱铢，真赏于今竟谁是。","况君负郭有良田，丰歉不至啼妻子。","劝君早赋归去来，我实饥寒不得已。"]},{"t":"赠乐秀才汇川","f":"古风","c":["伊余削籍游京华，畴昔知交绝来往。","踽踽孤踪近十年，邂逅石闾非梦想。","高才逸气淩九霄，冰雪奇文共欣赏。","眉山即山相继来，睥睨今古分雄长。","三人磊落天下奇，世求一见恒难期。","况与交游日把臂，此生此世诚一时。","年来知己尽凋丧，诗文到处含酸悲。","群鸱聚族争腐鼠，安知溲渤潜蛟螭。","一椽索处类屈蠖，谁复问字来卑栖。","乐生青云客，慕我如饥渴。","月明乘兴叩荆扉，疑是山阴夜中雪。","金尊绮馔玉作盘，邀我醉饱灯元节。","爱我作大书，不惜绢素供涂污。","爱我作长句，频催屡促如追逋。","自愧才同白头豕，何能扬鬣倾江湖。","感君意，为君讴。","滔滔陇水去不休，各自南北东西流。","纷纷草木无坚性，几日飘荡随残秋。","与子共采明月珠，与子共宝荆山瑜。","男儿立身贵不朽，莫教岁月空荒芜。","我今愿作他山石，攻金攻玉成琏瑚。","君不见少年慷慨酣杯酌，移山倒海轻一诺。","口血未乾盟已寒，星移雨散何浇薄。"]},{"t":"真州九日偕署中诸友游吴园舟中燕集二首之一","f":"七言古诗","c":["吴囿游回日将暮，解缆随流认归路。","炮虾劈蟹聊具觞，临觞缓领舟行趣。","须臾璧月丽中天，照见长江隔江树。","满目秋光尽画图，中流击楫为君赋。","魏主诗台久已颓，壮观亭子空烟雾。","白沙江村不可寻，青莲高楼在何处。","但见江声日夜流，征鸿又向江南去。","江乡传舍今独存，我辈登临畅遐顾。","褰裳远引且未能，旷怀每借江山吐。","况复尊中酒不空，良辰恰与名园遇。","诸君此日须尽欢，莫使林峦笑空度。"]},{"t":"题沈敬轩秋江归棹图","f":"七言古诗","c":["宦海茫茫浩烟雾，破浪乘风不能渡。","片帆高挂大江秋，指点家山畅归路。","江上閒云任捲舒，江上浮鸥自来去。","门前松菊未荒芜，陇上桑麻足租赋。","较雨占晴学老农，农家伏腊相劳苦。","一尊酒对鸳湖滨，烟雨楼中阅朝暮。","岁月閒消天地宽，精神老受烟霞铸。","回首名场一笑看，富贵真同草头露。"]},{"t":"咏水仙花","f":"七言古诗","c":["洛川川上淩波子，蹁跹弄影烟波里。","环佩声沈几度秋，幻作春花爱春水。","素貌亭亭冰雪姿，争春耻并妖红紫。","空谷兰英品亦尊，叶长犹恐拖泥滓。","尔独尘居不受尘，清泉养质随乌几。","我将携之与俱飞，褰裳飘缈空中举。","瑶琴海上招成连，万载千秋长不死。"]},{"t":"题金仁趾秋风出塞图","f":"古风","c":["君不见井中蛙，但解盘游乐井水。","安知溟渤有蛟龙，洪波一击三千里。","大块芸生岂能齐，巨细悬殊类如此。","金生仁趾全椒雄，缥缃万轴罗心胸。","奇情伟抱不能遏，吐气喷薄如长虹。","纵横艺圃慑俦辈，笔峰高峻淩华嵩。","神驹伏枥志千里，岂同驽劣局蹐辕下嘶酸风。","江南江北尽水国，天吴海若纷出没。","烟霞变幻入奇怀，洋洋挥洒波澜阔。","犹道齐梁旧习非，淮扬歌管声悽迷。","南风久不竞，不能卓绝开襟期。","岩疆巨镇动遐想，北走荒外探雄奇。","秋风匹马桑乾道，连峰突兀烟云绕。","秦关西去亘长城，跨海包山势窅窎。","关山月照陇水寒，塞马骄嘶猎枯草。","卫霍丰功壮士歌，苏卿奇节羌人表。","明妃青冢吊贞魂，李陵台畔妖狐扰。","登高四望野茫茫，回看反觉中原小。","从此襟怀顿豁开，从此诗思增奇矫。","酒酣击节一悲歌，歌声激壮风骨老。","慷慨编成出塞吟，吟同白雪知音少。"]},{"t":"题吴好山采药图","f":"七言古诗","c":["胸中万卷罗经济，世不我知将焉逝。","方袍箬笠入深山，孤情冥结烟霞契。","松巅老鹤盘空青，石上流泉濯流秽。","还随鹿豕历崟崎，采斸灵苗调沆瀣。","此时已觉身骨轻，无待仙真授缄秘。","那知名早列丹台，灵风导引虚无际。","耳边密语世稀闻，指点天根在西兑。","归来闭户养玄关，得一堪矜万事备。","始知大药非外求，个中自有真天地。","从此儴佯作散仙，提筐荷锸原儿戏。"]},{"t":"拜岳王墓","f":"古风","c":["钱塘门外岳王墓，群山重绕西湖路。","循湖西去展祖坟，坟上归来见高树。","夕阳斜照向南枝，枝头哑哑乌正啼。","对墓踉跄忙下拜，老泪迸落心酸悲。","血战中原思雪耻，天子深愁不利己。","十二金牌听桧谋，风波亭上忠臣死。","据此名胜且欢娱，弃捐君父如芒屣。","丹诚虽并日争光，国雠未报忠魂伤。","时闻风雨万灵走，戈戟夜半声玱琅。","石马嘶风毛鬣竖，还如酣战黄龙冈。","繄余拜罢日将泯，远近明湖目光骋。","南屏山下见高坟，忠肃先生复堪悯。","吁嗟乎有才用世岂良图，罗刹江东好归隐。","海气茫茫岛屿深，海上千峰捩孤隼。","月出天地浸冰壶，流光荡漾三山影。","何如此去学长生，缥缈仙槎相导引。"]},{"t":"题金孝廉棕亭诗册","f":"古风","c":["高天明星丽东壁，照临下土司文章。","精华陊地化才子，上与朝日夕月同辉光。","大块不语赖宣泄，灵奇窅眇咸森张。","冥搜造化入阃奥，陶镕万象分否臧。","但觉毫端百灵集，谁知呼吸通天阊。","篇终有时一吟啸，天地震惊鬼神夜哭。","波涛倏忽翻江湖，蛟龙腾踔摇山谷。","诗人之笔隐显变化乃如此，岂与蛙吟蝉噪争申缩。","何人颓其风，相趋入樊笼，遂令风雅大道埋没荆榛丛。","我欲鼓洪钧、煽大冶，铸万石之金镛，登高一撞惊群聋。","又欲高泻黄河之水昆崙峰，洗伐毛髓之疲苶浩浩元气流心胸。","自顾才气短，老马力尽日复晚。","吁嗟乎吁嗟，万钧之任谁能挽。","金子逸才真出群，身骑鸾凤翔风云。","行将上界朝紫氛，丰隆列缺纷来宾。","口吹昭华云璈之玉琯，手执金支翠羽之朱竿。","指点英奇导仙路，担当巨任将属君。","呜呼担当巨任将属君，慎勿降心屈节希悦乎凡耳之听闻。"]},{"t":"题张建宇富春垂钓图","f":"古风","c":["男儿居世间，蓄志贵坚贞。","自待苟不重，遂为世所轻。","古人立身期不朽，出处去就何分明。","君不见严子陵，万乘之尊不能屈，足加帝腹星辰惊。","甘心垂钓终此生，清风千载高崚嶒，呜呼清风千载高崚嶒。","张君卓识慕野服，扁舟遁迹临海屋。","售世岂乏经济才，心不希荣身不辱。","人间得失不关心，钓竿日对溪山绿。","閒看鸥鸟浴江天，云霞过眼纷相逐。","江光山色变阴晴，聚散升沈骇倏忽。","日夕收纶喜得鱼，床头有酒腹有书。","高歌一曲声呜呜，饮酣歌罢呼妻孥，庄光高节今何如。"]},{"t":"题滇藩宫怡云七柏图","f":"古风","c":["大璞不畏戕，遂尔成奇珍。","男儿顺逆不中变，始能涉世称完人。","山左孝廉宫怡云，挟策万里官南滇。","循声屡著屡迁擢，天家重赖为屏藩。","钧陶万姓甫三载，颂声尸祝将千年。","那知泸水出妖蜮，能使阴晴变朝夕。","含沙吐气生毒霪，潜身射人人不测。","炎天呼吸成严冬，当之草木凋青葱。","我公植身如古柏，根蟠厚地枝撑空。","独能历险不受剥，长留黛色参苍穹。","归来对镜须眉白，荏苒行年已七十。","回首荣枯境屡更，持身终始无改易。","黄生为写七柏图，状君坚节生年符。","丹穴鸳雏受密荫，老干中有神灵扶。","从兹日月任流转，亭亭屹立高山隅。"]},{"t":"题方竹楼画竹","f":"七言古诗","c":["县署西偏地疏豁，琅玕森翠千株列。","离立潜通江上云，青苍不畏严冬雪。","眼中繁卉任荣枯，岁晚奇姿挺孤洁。","我时乘兴步亭林，微吟徙倚扪高节。","千亩何须傲列侯，三径矜能款明月。","静对幽丛妙悟生，爽聆清籁天机发。","自昔文人爱此君，我亦钟情若饥渴。","方生为我作画图，雨干烟梢尽奇绝。","黄筌与可未为工，潇湘淇水悬蓬室。","盛夏摊书作卧游，中有凉飙扫炎热。"]},{"t":"旅怀","f":"五言律诗","c":["孤馆萧条日，严霜酷烈时。","乡关凭梦寐，潦倒剩须眉。","事业愁中酒，文章醉后诗。","百年如过隙，宁不感羁迟。"]},{"t":"客牛镇","f":"五言律诗","c":["月破残云出，清光上几筵。","溪喧鱼唼藻，窗暗柳垂烟。","花气熏深酌，泉声入夜弦。","身安忘在客，倍觉主人贤。"]},{"t":"岁暮返里","f":"五言律诗","c":["经岁羁京国，隆冬返塞垣。","严霜翻白昼，饥虎猎黄昏。","面削风尘悴，身归皮骨存。","老亲惊拭泪，艰苦到衡门。"]},{"t":"烽台秋望","f":"五言律诗","c":["惨淡黄云戍，阴森白骨堆。","望乡无故识，吊古有荒台。","海月三更出，悲风万里来。","愁心当此夕，鸿雁不胜哀。"]},{"t":"送车宜年复入都门","f":"五言律诗","c":["才释经年恨，旋看腊月行。","一杯今夕酒，千里故人情。","边塞此何地，诗书岂卫生。","知余唯赖子，相送泪纵横。"]},{"t":"赠赵南村二首 其一","f":"五言律诗","c":["离索怀良侣，逢君宿愿伸。","论交倾肺腑，落笔幻蛇神。","边塞风尘际，冰霜酷烈辰。","一尊相晤语，应订百年身。"]},{"t":"赠赵南村二首 其二","f":"五言律诗","c":["著述空前代，经纶屈盛朝。","沈怀甘水石，野服近渔樵。","龙剑秋长啸，螭珠老未凋。","莫贪禽尚隐，苍赤望甄陶。"]},{"t":"春望","f":"五言律诗","c":["天涯登眺泪，滴滴堕清笳。","雪汨峰头树，春迟塞上花。","滞辽归雁少，望越暮云赊。","心境同庄舄，哀吟为丧家。"]},{"t":"山行","f":"古风","c":["险路行山坞，阴风聒土囊。","大云帱厚地，寒雨洒穹苍。","侧足淩?崿，提心畏虎狼。","将投何处宿，翘首望茫茫。"]},{"t":"宿新城","f":"五言律诗","c":["百战兴亡地，千秋眺望情。","荒溪量白骨，明月吊空城。","霜冷鹰秋击，灯昏鬼夜鸣。","平生履险惯，当此亦魂惊。"]},{"t":"公车入都留别蔡宗鲁","f":"五言律诗","c":["脂辖龙沙道，悲风怆客神。","饥寒离二老，冰雪去孤身。","绝域谁堪告，倾囊尔又贫。","壮怀思急遂，不敢畏艰辛。"]},{"t":"春日过赵氏山庄 其一","f":"五言律诗","c":["野树缘溪密，欹桥一径通。","枝低衣坠绿，花落鸟争红。","山忽开云出，村仍隔水中。","主人吟望久，携手步林东。"]},{"t":"春日过赵氏山庄 其二","f":"五言律诗","c":["久厌嚣尘秽，晴郊豁旅颜。","荡胸春水活，涤虑野云閒。","径曲偏宜竹，窗低不碍山。","贪吟林色暮，带月返柴关。"]},{"t":"春感","f":"五言律诗","c":["旅眼经春色，翻生物候悲。","禽声呼旧侣，花蕊破新枝。","怀土情难抑，吟诗句不奇。","片云天际远，望久意俱驰。"]},{"t":"友人简邀踏青诗以谢之","f":"五言律诗","c":["迢递犹为客，乾坤空复春。","禽声增别恨，草色总伤神。","苦被愁中境，频摧病里身。","谁堪还出郭，携榼坐花茵。"]},{"t":"读书丁家洼杂咏","f":"五言律诗","c":["不出繁华境，焉知避世心。","泉清消俗虑，云淡静尘襟。","鹭浴盘涡浅，莺巢接叶深。","物情欣自得，相对惜春阴。"]},{"t":"携尊","f":"五言律诗","c":["花开千树锦，柳亸一林烟。","鹿过溪留迹，云归月满川。","携尊乘逸兴，扫石俯流泉。","苦被微名束，空知靖节贤。"]},{"t":"雨后偶成","f":"五言律诗","c":["微雨新晴后，高轩独坐秋。","众峰拔地起，远水接天流。","诗有江山助，吾来汗漫游。","疏狂成野性，甘狎海中鸥。"]},{"t":"掬月溪","f":"五言律诗","c":["一带烟光合，柴门隔岸开。","乍离尘市远，顿觉利名灰。","溪鸟不飞去，山云欲下来。","忘机终日坐，幽意自潆洄。"]},{"t":"邃壑","f":"五言律诗","c":["策杖孤村北，携尊邃壑前。","席阴云出谷，溪响石流泉。","鱼跃开蘋叶，莺啼过柳烟。","物微知有托，吾道亦从天。"]},{"t":"整屧","f":"五言律诗","c":["整屧缘樵径，柴门日色低。","鸥行分水叶，燕语落檐泥。","藉草杯常把，閒吟杖每携。","古来恬淡者，多半乐岩栖。"]},{"t":"午睡","f":"五言律诗","c":["竹轩贪爽豁，高卧与峰齐。","枕上梦初觉，檐前日已低。","野花开绝壁，山鸟浴晴溪。","识得浮生理，閒云过岭西。"]},{"t":"山晓","f":"五言律诗","c":["花气熏残梦，禽声唤宿醺。","冈头一瀑下，村落数家分。","樵牧人皆出，飞潜物自群。","惭余行役子，终觉羡耕耘。"]},{"t":"山行","f":"五言律诗","c":["每至幽栖地，长怀出世心。","缓随流水去，渐入白云深。","墟里淡斜照，烟萝生暮阴。","道逢樵牧侣，閒坐话中林。"]},{"t":"秋日都门感怀五首 其一","f":"五言律诗","c":["商声摧木落，生意在松柯。","大化已如此，孤贞奈若何。","采芝山邃窅，捧檄岁蹉跎。","出处悲身世，秋风感慨多。"]},{"t":"秋日都门感怀五首 其二","f":"五言律诗","c":["漠漠孤云细，遥连渤海东。","日光吞野马，山色悴秋风。","骨以怀亲瘦，囊因绝俗空。","归心千里外，飘转逐旋蓬。"]},{"t":"秋日都门感怀五首 其三","f":"五言律诗","c":["世情浓极处，偏喜绝无闻。","彻骨贫应尔，谋身事岂群。","苍松寒啸雪，孤鹤健淩云。","败叶经风雨，萧萧落正纷。"]},{"t":"秋日都门感怀五首 其四","f":"五言律诗","c":["万物逢秋杀，荣枯此日看。","回风山骨慄，落叶雨声乾。","炼炭炊长馁，悬鹑衣自安。","敢云贫亦乐，颇惜后凋难。"]},{"t":"秋日都门感怀五首 其五","f":"五言律诗","c":["迂儒投俗尚，那得好怀开。","野性从人议，刚肠每自回。","归鸿冲塞入，苍隼刷天来。","吾道唯安拙，呼朋纵酒杯。"]},{"t":"旱","f":"五言律诗","c":["风鼓边声劲，尘埋日色悬。","但看阴匝地，不见雨垂天。","割下银河水，应沾万顷田。","自惭无羽翰，惆怅意茫然。"]},{"t":"微雨忽晴","f":"五言律诗","c":["正喜甘霖沛，旋看螮蝀东。","断云携雨黑，落日散江红。","鸟湿愁深树，鱼归会晚风。","独饶忧国意，沾溉望年丰。"]},{"t":"与诸同人泛舟天桥湾得骸字磨字二首 其一","f":"五言律诗","c":["呼艇缘城角，移尊向柳涯。","棹回天忽破，帆正浪空排。","野景开晴旭，高云补断厓。","中流同啸咏，真觉忘形骸。"]},{"t":"与诸同人泛舟天桥湾得骸字磨字二首 其二","f":"五言律诗","c":["雨暗昨霄月，烟开此日波。","阴晴时不测，天地意如何。","云色风头静，天光水面磨。","悠然若有会，山鸟忽来歌。"]},{"t":"再至红桥","f":"五言律诗","c":["再至曾游处，山家熟更宜。","迎人村犬狎，入室野云随。","地僻孤峰秀，天空独鸟迟。","坐深心境静，忘却夜归时。"]},{"t":"都门喜晤方问亭旋送出关凭达家书三首 其一","f":"五言律诗","c":["昔别龙沙道，同悲异域身。","长安重破涕，故国未归人。","事业频虚岁，衰强互问亲。","平生关切意，患难觉尤真。"]},{"t":"都门喜晤方问亭旋送出关凭达家书三首 其二","f":"五言律诗","c":["七年才一晤，一晤复分襟。","辛苦成何处，乾坤共此心。","梦中乡国杳，天外海云深。","岁月惊虚掷，吞声塞上吟。"]},{"t":"都门喜晤方问亭旋送出关凭达家书三首 其三","f":"五言律诗","c":["话旧君能主，君行愧我贫。","交虽形迹外，倍觉怆离神。","陟岵天涯子，倚闾塞上亲。","一函凭远达，心逐渡辽尘。"]},{"t":"三至红桥","f":"五言律诗","c":["频来幽赏地，林壑意相迎。","倚杖缘溪立，晴云隔水生。","吟情随处远，野性觉名轻。","得意忘言说，松风拂面清。"]},{"t":"宿镇安堡","f":"五言律诗","c":["惨雪搏风急，阴云覆野宽。","马羸思辙卧，身病怯衣单。","猎虎饥来惯，羁人梦未安。","祇愁途路塞，不敢夜冲寒。"]},{"t":"春望","f":"五言律诗","c":["云捲千峰翠，烟消万壑晴。","欲看春景丽，翻使客心惊。","鸿雁抟风健，鹪鹩托羽轻。","雄边望不尽，归意若悬旌。"]},{"t":"将至房山先寄寄斋先生","f":"五言律诗","c":["客舍频迁次，飘零愧腐儒。","愁来唯仗酒，囊尽不能沽。","翠嶂晴云细，清溪浩月孤。","思君吟赏处，早晚就菰蒲。"]},{"t":"邃壑","f":"五言律诗","c":["已远孤村北，还过邃壑南。","云峰腾峻岭，天影浸空潭。","入世情何淡，看山性颇贪。","几时沾薄俸，归去觅烟岚。"]},{"t":"袒腹","f":"五言律诗","c":["解衣挂萝薜，袒腹净尘氛。","幽意惭高鸟，烦心羡白云。","何时祛世务，终岁出人群。","结屋同泉石，襟期一證君。"]},{"t":"再过佛氏山庄","f":"五言律诗","c":["尘寰意不惬，策杖问莓苔。","桥断依山曲，溪流碍石回。","苍烟樵子径，老雪故人梅。","坐我春风里，谈深发旧醅。"]},{"t":"查验任邱被水山庄","f":"五言律诗","c":["永夜不能寐，晨兴信仆夫。","人烟衰草白，秋色暮云孤。","野艇冲冰入，残黎隔岸呼。","皇恩来救汝，不是吏催租。"]},{"t":"宿里长","f":"五言律诗","c":["里长昏投宿，浮邱见水灯。","柴垣一破寺，鸠面两枯僧。","禦腊缝山□，充饥晒水藤。","自誇逃窜尽，生计有馀能。"]},{"t":"书怀 其一","f":"五言律诗","c":["韬精超俗虑，幽想洽岩栖。","结屋峰千仞，侵篱月一溪。","耸身霄汉近，放眼白云低。","此际堪逃俗，相观物性齐。"]},{"t":"书怀 其二","f":"五言律诗","c":["戴笠理荒秽，晨兴出露垣。","诛茅培屋宇，移石让松根。","收柿工书翰，分泉灌竹园。","百年长此役，今世即羲轩。"]},{"t":"须白","f":"五言律诗","c":["吾须方四十，白间黑中丝。","精力衰何遽，平生境可思。","学惭余未进，老逼尔先知。","辛苦年年事，殷勤怯岁迟。"]},{"t":"发白","f":"五言律诗","c":["对镜惊霜雪，丝丝入鬓新。","忽思千古事，转虑百年身。","不老亦无术，长存自有神。","颜彭今日看，修短定谁真。"]},{"t":"送秦妹丈之中江县令","f":"五言律诗","c":["十年膺一命，此去自难留。","叱驭蚕丛道，怀亲燕市楼。","江声流万古，风叶下残秋。","知尔中途泪，潺湲不可收。"]},{"t":"梅","f":"五言律诗","c":["草木凋枯日，冰霜酷烈时。","香深天地苦，花发古今奇。","岁月嗟何暮，风光占未迟。","孤芳谁独赏，应与野人期。"]},{"t":"寄中江秦妹丈","f":"五言律诗","c":["蜀道虽云险，中江政不繁。","民因招募聚，官赖抚循恩。","云栈悬丹嶂，松涛撼夜猿。","专心思报最，乡泪莫潺湲。"]},{"t":"须白","f":"五言律诗","c":["须白已多日，无如近转添。","蹉跎成底事，寂寞感华年。","修慝频看镜，扶衰不学仙。","数茎留警惰，吾道岂从天。"]},{"t":"石琴步屈悔翁原韵 其一","f":"五言律诗","c":["一与青峰别，居然绿绮横。","古风吹壁冷，幽谷响泉清。","谁解临厓听，空令逸韵生。","知音如可遇，天地有新声。"]},{"t":"石琴步屈悔翁原韵 其二","f":"五言律诗","c":["他山蒙在御，雕琢已无辞。","轻薄怜胶漆，风尘岂磷缁。","霜峰寒雁落，哀峡断猿迟。","别调成孤赏，空山雨雪时。"]},{"t":"再叠前韵 其一","f":"五言律诗","c":["山川藏不住，斸作紫琼横。","身带波涛润，音传岩壑清。","庙堂虽不御，苍翠觉长生。","堪惜米颠拜，何知听此声。"]},{"t":"再叠前韵 其二","f":"五言律诗","c":["不知补天用，聊传清庙辞。","柱徽殊习玩，坚白涅难缁。","霖雨鸣崖细，松风度陇迟。","高山今在望，识曲慕当时。"]},{"t":"三叠前韵 其一","f":"五言律诗","c":["兹琴非近乐，不许膝前横。","本以重难御，兼之音太清。","风霄玄鹤下，丹穴彩鸾生。","应与鸣球贡，熏风一奏声。"]},{"t":"三叠前韵 其二","f":"五言律诗","c":["解鼓神人格，知稀弃不辞。","绝无凡指弄，翻少俗尘缁。","挂壁侵苔古，游鱼出水迟。","昔贤成此意，应不悦当时。"]},{"t":"仲夏过红桥阻雨次日寻幽至暮 其一","f":"五言律诗","c":["耽幽忘溽暑，特地到君家。","草色分行鹿，莺声老落花。","于陵逃俗远，陶令去官赊。","野性偕孤鹤，相随看早霞。"]},{"t":"仲夏过红桥阻雨次日寻幽至暮 其二","f":"五言律诗","c":["阴云留过客，携雨到柴门。","杯酒谋邻叟，园蔬乞近村。","深灯连曙柝，幽梦绕山樊。","自古唯萧索，方知重友伦。"]},{"t":"仲夏过红桥阻雨次日寻幽至暮 其三","f":"五言律诗","c":["葛衫朝觉爽，宿雨夜初还。","溪涨来新鸟，云开见远山。","偶凭丞相圃，暂豁旅人颜。","回首燕城内，风尘咫尺间。"]},{"t":"仲夏过红桥阻雨次日寻幽至暮 其四","f":"五言律诗","c":["饭后复来坐，清风开我襟。","山云低度涧，溪鸟不归林。","日色回峰影，诗情惜柳阴。","春风沂水后，怀古一何深。"]},{"t":"仲夏过红桥阻雨次日寻幽至暮 其五","f":"五言律诗","c":["欲窥群物理，非独爱村晴。","临水知鱼乐，看山识鸟情。","天机真自畅，幽绪亦旋生。","游衍閒居地，荣名顿觉轻。"]},{"t":"仲夏过红桥阻雨次日寻幽至暮 其六","f":"五言律诗","c":["避日频移席，残尊落照间。","农人归陇犊，樵爨隐云山。","佳景随时得，劳生贵自閒。","还将无尽意，乘兴叩松关。"]},{"t":"香山看红叶得黄字秋字二首 其一","f":"五言律诗","c":["山寒经宿雨，树树杂丹黄。","名士耽幽胜，新诗寄草堂。","偶依流水坐，翻叹俗尘忙。","嘉会还期再，秋风引兴长。"]},{"t":"香山看红叶得黄字秋字二首 其二","f":"五言律诗","c":["几载尘劳梦，名山得暂留。","杖藜探绝壑，云树状高秋。","野性看飞鸟，寒声听夜流。","凭将幽僻兴，携手问同游。"]},{"t":"宿来青轩","f":"五言律诗","c":["已览香山胜，还寻胜地眠。","阴崖连户竹，疏磬出山烟。","月色缘阶上，泉声到枕边。","夜来魂梦冷，身在白云巅。"]},{"t":"晚至永安寺迟海涵百","f":"五言律诗","c":["竟日历巉岩，耽幽不觉艰。","远烟归鸟路，清磬夕阳山。","石磴云霞引，松门铁锁攀。","主人相失后，徙倚暮崖间。"]},{"t":"再游香山","f":"五言律诗","c":["一从游赏后，念此意何殷。","伏枕梦流水，开窗想白云。","林峦经再过，烟月会平分。","几日浓霜下，丹枫落叶纷。"]},{"t":"卧佛寺","f":"五言律诗","c":["虚空天地外，清冷对金仙。","已證真三昧，应参不二禅。","尘劳何所得，登眺忽茫然。","心契幽香妙，筌蹄欲弃捐。"]},{"t":"再游卧佛寺七首 其一","f":"五言律诗","c":["西风吹杖履，来往亦无端。","山色飞晴翠，钟声过远滩。","鹤巢双树老，鹿径一僧寒。","佛卧何时醒，阶前落叶丹。"]},{"t":"再游卧佛寺七首 其二","f":"五言律诗","c":["云起从遮簟，风来任落花。","溪光摇户牖，山色浸袈裟。","一入希夷境，金消世俗哗。","忽思遂初服，身卧白云赊。"]},{"t":"再游卧佛寺七首 其三","f":"五言律诗","c":["我来寻眺听，慈眼自朦胧。","顿觉见闻寂，真教色相空。","虚窗通远翠，高树下秋风。","心境浑无著，悠然念始终。"]},{"t":"再游卧佛寺七首 其四","f":"五言律诗","c":["云霞随过客，泉石绕香台。","大块梦谁觉，空王睡不回。","野花开欲歇，溪鸟去还来。","静验浮生理，孤亭坐藓苔。"]},{"t":"再游卧佛寺七首 其五","f":"五言律诗","c":["大千同一梦，佛卧亦何因。","恍接无言教，旋多有累身。","霜蛩鸣晚砌，风箨坠寒筠。","岂是维摩病，西来大义真。"]},{"t":"再游卧佛寺七首 其六","f":"五言律诗","c":["松窗雕槛外，日日下朝暾。","一榻空今古，深山冷梦魂。","云阴侵座湿，鸟语入林昏。","众衲何多事，经声响暮村。"]},{"t":"再游卧佛寺七首 其七","f":"五言律诗","c":["望佛佛犹卧，还寻旧路回。","野禽随上下，流水亦潆洄。","来处云何在，归途日已颓。","回看深翠里，瞬息隔尘埃。"]},{"t":"自洪光寺至说法亭","f":"五言律诗","c":["说法人何在，探奇性颇贪。","九盘松磴石，双乳石泉甘。","鸟道随云入，霜林坠叶酣。","几时深树里，添得一茅庵。"]},{"t":"宦竖张鲸墓","f":"五言律诗","c":["岧峣阉竖墓，松柏上云霄。","凿翠开山穴，淩空跨石桥。","攀萝寻旧碣，拂藓认前朝。","惆怅夕阳下，萧萧红叶凋。"]},{"t":"过朝阳洞遂登朝阳绝顶 其一","f":"五言律诗","c":["洞口朝阳寺，山坳日色曛。","佛天开鬼斧，石窟护神云。","偶结林泉侣，高瞻鹳鹤群。","探奇聊憩息，峰顶望氤氲。"]},{"t":"过朝阳洞遂登朝阳绝顶 其二","f":"五言律诗","c":["振策猿猱径，身跻翠巘崇。","涛声惊地轴，人语落天风。","宇宙收双目，苍茫立太空。","桑乾东去疾，舟楫海门通。"]},{"t":"听泉","f":"五言律诗","c":["幽涧听泉声，山中约二更。","野风生竹□，孤月入怀明。","俗虑一时净，閒心永夜清。","转愁明发去，尘市若为情。"]},{"t":"别香山二首 其一","f":"五言律诗","c":["已命归途驾，犹看旭日前。","山容增烂缦，我意倍流连。","泉石别今日，莺花想隔年。","再游愁不遂，把酒嘱林泉。"]},{"t":"别香山二首 其二","f":"五言律诗","c":["殷勤倾浊酒，与尔结幽情。","已快连朝赏，还申后日盟。","白云常在眼，流水莫收声。","题遍岩间石，君应更著名。"]},{"t":"过马氏园林","f":"五言律诗","c":["虽未出城市，来兹意己欣。","小庭初过雨，密竹暗通云。","鱼鸟咸知乐，嚣喧静不闻。","暂偷忙里暇，亦觉远尘氛。"]},{"t":"自福建接富氏姊来齐河官署","f":"五言律诗","c":["昔别辽河畔，今来济水滨。","寻常一分袂，二十七年人。","兄弟尚谁在，存亡各怆神。","高年思骨肉，庶一慰慈亲。"]},{"t":"题画壁和同年子毛秋岑原韵 其一","f":"五言律诗","c":["沧海谁仙隐，飘然去不还。","天容空映水，云气暖蒸山。","老屋升沈外，扁舟出没间。","浮家计未遂，心向画图閒。"]},{"t":"题画壁和同年子毛秋岑原韵 其二","f":"五言律诗","c":["远水浮天地，孤舟日往还。","到门唯白鸟，举目即青山。","遥忆风尘际，谁知住此间。","相期婚宦毕，身入个中閒。"]},{"t":"历下亭怀古","f":"五言律诗","c":["历下亭犹古，昔人曾此游。","我来寻胜迹，霜冷荻芦秋。","万卷藏书屋，干霄白雪楼。","徘徊风雅地，山色远含愁。"]},{"t":"自雒镇放舟回县","f":"五言律诗","c":["归舟耽自在，晚兴觉偏浓。","渔火惊栖鹭，柴扉闻夜舂。","烟笼寒渚月，风度远村钟。","柔橹菰蒲外，前山隔几峰。"]},{"t":"生日书怀","f":"五言律诗","c":["寂寞成何事，蹉跎忽至今。","聪明过壮岁，道德负初心。","斜日延疏竹，寒花逗晚林。","昌黎箴自在，读罢一沈吟。"]},{"t":"瓶中腊梅","f":"五言律诗","c":["不随梅竞白，迎腊吐芳菲。","于道色唯正，先春气不违。","暗香闻静夜，幽室发清机。","意趣忘言说，寒窗对月晖。"]},{"t":"雨后省耕过刘氏山庄","f":"五言律诗","c":["觇农出东郭，林壑夜初晴。","春雨既云足，田家各有营。","窗虚通燕语，花暖聚蜂声。","民物欣如此，相看慰我情。"]},{"t":"书感","f":"五言律诗","c":["故国田园尽，无谋奉老亲。","迂疏希用世，俯仰学随人。","十载空劳瘁，残生尚汨陈。","终愁经事浅，有玷白华身。"]},{"t":"倚槛","f":"五言律诗","c":["春风轻拂袖，倚槛一开颜。","宿雨朝初霁，孤云淡未还。","菱歌生极浦，鸟语话青山。","何必沧洲去，悠然意自閒。"]},{"t":"归自长城驿经刘园小憩","f":"五言律诗","c":["芳径转幽僻，孤亭净俗氛。","檐花风静落，人语竹深闻。","滩响疑来雨，松阴欲下云。","渊明曾试仕，野性卒离群。"]},{"t":"雨后忆西山寄海涵百边识珍赵珍兄弟","f":"五言律诗","c":["独坐新晴后，官清忆昔閒。","西峰偕旧侣，采药驻衰颜。","红叶林中寺，斜阳雨后山。","别来幽赏地，胜事孰追攀。"]},{"t":"和毛秋岑济上之作","f":"五言律诗","c":["济上春风暖，临流畅我情。","长桥分甸服，一水界齐清。","泰岱云来近，虚空雨易成。","田家八万户，沾洒遍深耕。"]},{"t":"编篱","f":"五言律诗","c":["编芦成小圃，篱落近农村。","野蔓萦新叶，绿云垂满园。","渐能罗蝶翅，疏不碍花魂。","领取幽栖意，閒吟坐竹轩。"]},{"t":"长清县道中","f":"五言律诗","c":["轮鞅虽云瘁，溪山兴颇浓。","炎蒸消澍雨，云壑作秋容。","禾黍知民力，棉机校女佣。","百年生计足，萧洒是桑农。"]},{"t":"夜至长清县","f":"五言律诗","c":["雨收云尚在，泥淖阻官程。","随役呼相应，肩舆歇复行。","野香生夜露，荒径逐虫声。","比至严城下，谯楼报二更。"]},{"t":"崮山望岱","f":"五言律诗","c":["岱宗何处是，崮顶正当冲。","登眺豁双目，苍茫隔数峰。","云来疑作雨，心寂若闻钟。","何日磨崖上，高寻历代踪。"]},{"t":"立秋前二日夜坐怀屈悔翁边识珍海涵百","f":"五言律诗","c":["露下消烦热，清言欲二更。","桐阴延夜月，虫语作秋声。","触景情何远，怀人句忽成。","兴心飞鸟上，离思觉旋生。"]},{"t":"初秋过五峰山 其一","f":"五言律诗","c":["不是因公至，何知此境仙。","奇峰争插汉，秋水远浮天。","老衲藏深峪，疏钟出曙烟。","到来心境寂，觅胜且流连。"]},{"t":"初秋过五峰山 其二","f":"五言律诗","c":["云构盘空邃，仙源入境清。","过桥通鸟道，穿竹忽泉声。","峰壑阶前秀，山禽时一鸣。","林梢风叶落，点点动秋情。"]},{"t":"初秋过五峰山 其三","f":"五言律诗","c":["素性耽丘壑，兹游畅我情。","野花随意发，山鸟不知名。","圭组心俱淡，烟霞念颇生。","携筇閒眺望，缓步觉身轻。"]},{"t":"初秋过五峰山 其四","f":"五言律诗","c":["坐久花时落，风轻水自纹。","松阴寒欲雨，石罅暖生云。","山寂樵歌起，风霄静里闻。","忘机亲牧竖，鸥鹤亦同群。"]},{"t":"初秋过五峰山 其五","f":"古风","c":["斜阳催返驾，无计复淹留。","好鸟啼将别，清泉咽不流。","霜催红叶曙，山养白云秋。","再至幽栖地，应?信宿游。"]},{"t":"过灵岩寺","f":"五言律诗","c":["铁缕袈裟旧，虬松枝干长。","神僧归寂寞，林壑望苍茫。","野鸟啼空谷，虚堂闻妙香。","筌蹄何处觅，心向静中忘。"]},{"t":"过里峪泉","f":"五言律诗","c":["巉岩循僻路，窅窕入林邱。","见水知村近，看山识岁秋。","鸟啼幽涧竹，人倚夕阳楼。","安得关橦手，相随记胜游。"]},{"t":"灵岩寺夜步","f":"五言律诗","c":["日入兴难尽，看山夜若何。","寒潭生月小，空谷受云多。","樵唱出萝薜，禅灯下芰荷。","疏钟声远近，隐隐隔岩阿。"]},{"t":"再过灵岩寺","f":"五言律诗","c":["松窗侵翠霭，经案接旃檀。","疏雨度高阁，轻风生暮寒。","再来禅院净，真远俗尘干。","莲社开何日，青山不厌看。"]},{"t":"访余隐居久候不遇","f":"五言律诗","c":["觅胜来幽境，兼之访所思。","到门寒绿绕，隔岸落花迟。","浅草归村路，斜阳罢钓时。","徘徊原野上，芳躅暮何之。"]},{"t":"咏佛手柑","f":"五言律诗","c":["霜柑悬色相，佛手是耶非。","伸屈皆禅谛，骈枝亦悟机。","掌应摩顶现，香逐散花飞。","静味拳拳妙，西来大意微。"]},{"t":"咏方镜","f":"五言律诗","c":["虚中生皎洁，静里察微茫。","照老须眉热，菱花心事凉。","万端无定象，随应不拘方。","纤翳防亏鉴，摩挲为发光。"]},{"t":"题千佛山精舍二首 其一","f":"五言律诗","c":["磴道历残雪，攀援陟翠峦。","诸天龛石穴，清梵落云端。","妙谛閒中悟，尘寰世外看。","万家烟雾里，攘攘正冲寒。"]},{"t":"题千佛山精舍二首 其二","f":"五言律诗","c":["晴日扩奇胸，崖端卓瘦筇。","高城浮片水，平野耸三峰。","云窦藏冰雪，风霄响桧松。","卑喧寻解脱，此地觉从容。"]},{"t":"笼鸟 其一","f":"五言律诗","c":["云路飞难进，樊笼亦偶然。","羽毛原不类，罗弋自应先。","物小能关化，机危但信天。","虽惭鸡断尾，终弗乞人怜。"]},{"t":"笼鸟 其二","f":"五言律诗","c":["知机焉蹈此，岂敢怨离群。","飞止将安遇，哀鸣亦不闻。","低头修翠羽，侧目望青云。","遐想冥鸿翼，高骞绝俗氛。"]},{"t":"萤火","f":"五言律诗","c":["但看生尔处，腐草亦何神。","托命长依夜，窥天未及晨。","湿光寒自照，阴火故相亲。","旦夕随风雨，飘零若有因。"]},{"t":"式微","f":"五言律诗","c":["天心开大悟，海量悔深非。","近难何能脱，名山不早归。","野花寒结子，清露夜沾衣。","羁绪兼秋杀，凄然赋式微。"]},{"t":"古书","f":"五言律诗","c":["数行读不到，岂是眼前书。","痛惜生民后，穷搜天地初。","精华陶睿智，糟粕饷迂疏。","莫以韦编敝，芸窗饱蠹鱼。"]},{"t":"古剑","f":"五言律诗","c":["神物虽韬敛，光芒碧汉横。","祗因惊北斗，遂使在丰城。","利钝何曾见，恩雠总不鸣。","转愁脱赠后，烈士意难平。"]},{"t":"古琴","f":"五言律诗","c":["自绝王门后，孤鸣尚有琴。","谅因知者少，留得到而今。","一曲猗兰操，千秋泗水心。","悠然尘虑寂，沧海意何深。"]},{"t":"古鼎","f":"五言律诗","c":["宝兹非赝质，铉耳复能全。","糊口聊初试，铭功殊不然。","鹧鸪班自灿，饕餮象空悬。","折足何堪重，深为覆餗怜。"]},{"t":"古镜","f":"五言律诗","c":["宝镜今何古，秦台照胆馀。","积尘浑不觉，秋水失真如。","昏浊成蠲弃，虚明忆始初。","犹看团似月，觌面一欷歔。"]},{"t":"古碑","f":"五言律诗","c":["不作石头梦，空留泉下哀。","一朝辞翠巘，终古卧苍苔。","功业归何处，文章安在哉。","从来称岘首，姓字亦尘埃。"]},{"t":"古寺","f":"五言律诗","c":["倾颓岩谷里，何代梵王宫。","不见天花落，真成色相空。","禅关邻虎穴，山鬼啸林风。","莲社凋零尽，凭谁问六通。"]},{"t":"古树","f":"五言律诗","c":["秦皇封未及，甘入不材林。","老干擎天直，盘根拔地深。","风霜坚劲节，日月饱清阴。","且未浮槎去，焉知迟暮心。"]},{"t":"出笼鸟 其一","f":"五言律诗","c":["蒙君垂盼意，小鸟亦何知。","已破樊笼出，方思性命危。","惊魂栖未稳，觅食意还疑。","毛羽经磨损，飞鸣慎所之。"]},{"t":"出笼鸟 其二","f":"古风","c":["山林飞不去，罿?已难辞。","彩翮兼殊众，先鸣讵所宜。","自应随位置，敢复恨羁縻。","从此垂堂远，知几亦未迟。"]},{"t":"小砚跌破命儿廷璋胶固诗以识之","f":"五言律诗","c":["一片端溪石，相随历岁时。","吟哦长我共，辛苦独君知。","此破虽关数，斯文实在兹。","岂甘来护弃，将效范馨遗。"]},{"t":"赋得轩皇鼎","f":"五言律诗","c":["铸此留何意，轩皇仙不还。","盐梅非所用，草野亦徒閒。","无疾遭颠趾，馀丹可驻颜。","蛟龙防驳落，珍重莫轻攀。"]},{"t":"古书","f":"五言律诗","c":["一卷知何代，咸云是古书。","但教余见扩，何必宋人馀。","濡墨补残字，熏芸辟蠹鱼。","豁然糟粕外，先哲若同居。"]},{"t":"宝剑","f":"五言律诗","c":["匣内作龙鸣，鸣应有不平。","千金轻价值，百折重声名。","射斗原非妄，投珠总弗惊。","奇功何处立，神物感精诚。"]},{"t":"磨剑","f":"五言律诗","c":["宝剑谁能识，霜锋汨没中。","雌雄凭论断，利钝在磨砻。","流水鸣秋涧，寒窗走夜虹。","防身兼许国，何处有丰功。"]},{"t":"雨后见月","f":"五言律诗","c":["久雨天初豁，移礅坐晚风。","月无亏皦洁，云不碍虚空。","身老名犹在，官休道岂穷。","静中观大化，吾自得吾终。"]},{"t":"留别卢公亮","f":"五言律诗","c":["官罢绝来客，相亲独有君。","间关归故国，杯酒惜离群。","朔雪祝阿道，春城玄兔云。","何时重把袂，剪烛细论文。"]},{"t":"孔员外为余刻齐清集赋谢","f":"五言律诗","c":["老雪衡门积，虚窗皓月孤。","知音甘阒寂，閒咏对荒芜。","得句惭圭璧，多君重珷玞。","风流王宋后，此意世人无。"]},{"t":"古庙二首 其一","f":"五言律诗","c":["倾颓何代庙，四壁但埃尘。","老树干云日，虚堂聚鬼神。","灯龛藏野鼠，风叶恐行人。","宿草秋坟路，荒原自结邻。"]},{"t":"古庙二首 其二","f":"五言律诗","c":["深山藏结构，高树带斜晖。","罗网牵珠箔，莓苔绣宝衣。","江云来复去，梁燕乳还飞。","望望村人远，依稀隔翠微。"]},{"t":"晓寒","f":"五言律诗","c":["霜花侵客袂，岚气障山容。","初日出东壁，流辉含远峰。","征车寻古道，村舍指乔松。","下马思微饮，香醪何处醲。"]},{"t":"云","f":"五言律诗","c":["来往浑无著，虚空自古今。","卷舒如有意，隐现亦何心。","不霈高天雨，旋留邃谷阴。","风来时莫测，敛迹尔应深。"]},{"t":"饥","f":"五言律诗","c":["搜厨无所得，相对耐恒饥。","凉雨浇蓬径，金风砭葛衣。","世情趋尽异，吾道识应稀。","飘泊秋深燕，无家何处归。"]},{"t":"题明复庵别业","f":"五言律诗","c":["官清成吏隐，卜室傍林间。","迹与市朝远，心随水石閒。","寻泉逢野衲，启户见青山。","时有故人问，灌园犹未还。"]},{"t":"春日书怀","f":"五言律诗","c":["崇替何须论，身尊道不违。","琴书堪送老，花鸟共忘机。","莫以肥甘是，而轻蓬蔂非。","但知安素履，随意惜春晖。"]},{"t":"或有劝余复官者诗以答之","f":"五言律诗","c":["于世真无补，馀生合弃捐。","功名抛敝帚，岁月在残编。","呆戆安时议，颠危赋性偏。","谁能徇世务，俯仰白头年。"]},{"t":"青毡","f":"五言律诗","c":["性命研精蕴，诗书发快谈。","闭门无接纳，落笔有烟岚。","交态贫逾见，人情老渐谙。","青毡吾故物，垂白复焉贪。"]},{"t":"夏日书怀","f":"五言律诗","c":["百年无定著，踪迹老风尘。","樱熟时将夏，花残岁不春。","平生成底事，往古类何人。","自叩惭惊汗，临风一怆神。"]},{"t":"仲夏与诸同人游王园先至明复庵别业即与同往乘兴复至丰台分韵得诗五首 其一","f":"五言律诗","c":["数椽栖息地，万木翠阴环。","时策手中杖，閒看门外山。","同人来造次，野石坐斑斓。","知尔耽幽胜，相携叩竹关。"]},{"t":"仲夏与诸同人游王园先至明复庵别业即与同往乘兴复至丰台分韵得诗五首 其二","f":"五言律诗","c":["前度何悤遽，山桃不满园。","再游行径熟，几日树阴繁。","溪爱新荷色，庭怜旧雨痕。","拂林逢故识，隔水问寒温。"]},{"t":"仲夏与诸同人游王园先至明复庵别业即与同往乘兴复至丰台分韵得诗五首 其三","f":"五言律诗","c":["游兴连朝剧，兹辰遂热衷。","山光迎屐齿，松径引樵风。","亭榭幽深入，渠荷曲折通。","丰台遥在望，觅胜意何穷。"]},{"t":"仲夏与诸同人游王园先至明复庵别业即与同往乘兴复至丰台分韵得诗五首 其四","f":"五言律诗","c":["游情方恋旧，前路复怀新。","清浅溪随屐，呢喃燕趁人。","吹来山翠雨，沾我谷皮巾。","更喜初晴后，芳郊绝点尘。"]},{"t":"仲夏与诸同人游王园先至明复庵别业即与同往乘兴复至丰台分韵得诗五首 其五","f":"五言律诗","c":["谈深花渐落，饮罢日初低。","醒酒风生竹，烹茶水掬溪。","松间云欲去，枝上鸟还啼。","临别频回首，烟光满大堤。"]},{"t":"自笑","f":"五言律诗","c":["自笑平生志，常思赋遂初。","升沈今已定，踪迹竟何如。","岩穴怀高侣，风尘寄索居。","几时归皂帽，闭室注虫鱼。"]},{"t":"题庆员外松乔小室","f":"五言律诗","c":["结室何须大，能无俗务侵。","静虚摊卷处，高洁入云心。","蕉叶抽窗翠，盆鱼乐藻阴。","公馀思太古，雅韵寄瑶琴。"]},{"t":"再题松乔小室","f":"五言律诗","c":["逼近高堂侧，精营一小轩。","退思扃竹径，防客破苔痕。","今古罗绳瓮，行藏究本原。","从来经济手，得力在忘言。"]},{"t":"养性","f":"五言律诗","c":["养性宜蓬径，幽偏绝俗埃。","尘情删故蘖，灵蕴茁新荄。","风起防蕉叶，人过惜藓苔。","静中时有会，小酌对花开。"]},{"t":"寄赠乔山人兆三兼订游山之约三首 其一","f":"五言律诗","c":["遁迹西峰麓，生涯获遂初。","俗尘终岁隔，灵境百年居。","割蜜攀岩石，分泉养蛤鱼。","随时招近局，尊酒狎樵渔。"]},{"t":"寄赠乔山人兆三兼订游山之约三首 其二","f":"五言律诗","c":["沃土耕耘暇，无营不散襟。","寻僧过寺惯，拾菌入云深。","遐契岩栖境，閒生泉壑心。","柿丹秋有信，将拟踏霜林。"]},{"t":"寄赠乔山人兆三兼订游山之约三首 其三","f":"五言律诗","c":["邈矣超尘境，跫然有足音。","清心对流水，聪耳听鸣禽。","适俗原非愿，高栖素所钦。","兴言随杖履，幽梦结遥岑。"]},{"t":"种竹后复简松乔","f":"五言律诗","c":["莫讶余情僻，偏于竹有私。","繁华非不媚，真性独能持。","风动凉生牖，阴过翠拂卮。","更看霜雪意，无语若相知。"]},{"t":"秋日寄兴","f":"五言律诗","c":["入世难孤立，投閒可自仙。","山斋黄叶雨，渔笱碧潭烟。","放迹形骸外，行吟草泽前。","尘寰如我问，鸥鸟狎江天。"]},{"t":"买蛩 其一","f":"五言律诗","c":["秋蛩虽细小，惨毒尔何安。","聚族逾千命，呼鸡罄一餐。","世情唯鲁莽，吾意悯贪残。","买纵梧阴下，天全戢羽翰。"]},{"t":"买蛩 其二","f":"五言律诗","c":["乍似潜阴砌，旋疑隔曲房。","哀鸣声远近，明月夜苍凉。","客梦秋长醒，清心听不妨。","东山嗤谢傅，丝竹近淫荒。"]},{"t":"立秋雨后访沙门无垢","f":"五言律诗","c":["披襟怜霁色，仰首爱天容。","溽暑沈宵雨，新凉散候蛩。","茅堂寻野衲，石径度深松。","尘外清谈永，寥寥响梵钟。"]},{"t":"忆西山简乔梅庵","f":"五言律诗","c":["沧海何年去，渔樵乐此生。","自闻高隐处，每动出尘情。","老树经霜色，悬泉落涧声。","秋来多胜事，羡尔遂躬耕。"]},{"t":"宿僧舍","f":"五言律诗","c":["访衲过精舍，身轻翠蔼中。","云根泉吐月，松顶鹤翔风。","欹枕浑无寐，清心闻夜钟。","悄然思古德，垂老半归空。"]},{"t":"秋感 其一","f":"五言律诗","c":["飘泊无家客，乾坤一讲堂。","钟魂摇梦醒，槐荫泼阶凉。","岁月三秋逼，关河万里长。","此身何处著，搔首问穹苍。"]},{"t":"秋感 其二","f":"五言律诗","c":["世际羲轩盛，身惭稷契良。","幽青新旱厉，淮海旧怀襄。","沧水何年使，桑林近日禳。","文章思报国，此意竟荒唐。"]},{"t":"秋感 其三","f":"五言律诗","c":["明主巡方切，贤臣补衮殷。","睿谟崇帝舜，折槛有朱云。","远猎威胡虏，虔禋报祖勋。","荒寒边徼外，深念圣躬勤。"]},{"t":"秋感 其四","f":"五言律诗","c":["所学终何用，空馀泽畔吟。","徘徊千古业，孤负一生心。","秋老黄花悴，风回落叶深。","感时还自惜，霜雪鬓毛侵。"]},{"t":"秋感 其五","f":"五言律诗","c":["孤立安时命，遑知拙与工。","问心期不愧，入世岂求同。","风力抟鹰翮，霜威损桂丛。","烟霞沧海外，脉脉系初衷。"]},{"t":"秋感 其六","f":"五言律诗","c":["衰谢尘心尽，琴尊野兴长。","人情秋藻丽，吾意古苔凉。","引杖随溪水，看云度石梁。","足缨思遍濯，清浊问沧浪。"]},{"t":"秋感 其七","f":"五言律诗","c":["瓠落竟何似，浮踪浊水萍。","那堪孤客况，不尽九秋情。","夜月蒹葭色，寒窗蟋蟀声。","长公头未白，归去早埋名。"]},{"t":"赏菊","f":"五言律诗","c":["华堂虚位置，低彩自荣鲜。","霜力催无恙，人言服得仙。","乾坤钟晚节，孤洁类高贤。","萝薜谁家圃，吾将老一椽。"]},{"t":"秋郊纵目","f":"五言律诗","c":["广野开晴旭，襟怀扩远天。","轻雷山脚雨，空翠寺门烟。","秋老茱萸节，人閒草木年。","一尊当夕照，红叶下前川。"]},{"t":"闻雁","f":"五言律诗","c":["高旷平生志，艰辛老不移。","深秋如有恨，久客始能知。","归雁声何苦，中宵泪欲垂。","关河无限路，随尔到天涯。"]},{"t":"九日简毛秋岑明复庵","f":"五言律诗","c":["志士悲年迅，重阳节又临。","欲寻黄叶路，高寄白云心。","惠子濠梁乐，荣期带索吟。","芳踪谁可继，怀古意何深。"]},{"t":"题明复庵别业","f":"五言律诗","c":["为吏兼为圃，园蔬每自耘。","偶来前浦雨，多是近山云。","羡尔亲林壑，惭余滞俗氛。","种瓜思结耦，小筑傍榆枌。"]},{"t":"答巢六国学世馨即用原韵 其一","f":"五言律诗","c":["世情轻道义，交际复谁真。","硕德思前辈，论心笃后尘。","乾坤三大业，今古百年人。","此意孤悬久，逢君倍觉亲。"]},{"t":"答巢六国学世馨即用原韵 其二","f":"五言律诗","c":["生涯馀白发，世缔得同心。","乍见惊余老，雄谈识尔忱。","孤鸣琴已碎，苦诣道方深。","何处求真赏，寥寥太古音。"]},{"t":"再赠巢六世馨","f":"五言律诗","c":["大块敦庞气，偏于尔独钟。","九重陶伟器，万卷扩奇胸。","通塞天君泰，艰虞道味醲。","惭余衰朽质，深望后凋松。"]},{"t":"惊秋","f":"五言律诗","c":["几时不出户，已遍帝城秋。","贞脆荣枯递，江河日夜流。","惧孤天地德，深感岁时遒。","莫谓分阴志，专为运甓谋。"]},{"t":"九日郊行","f":"五言律诗","c":["登眺林皋霁，萧森霜露馀。","一从遭斥逐，深喜近樵渔。","芦雪人家岸，槐烟野衲居。","置身图画里，随步得相于。"]},{"t":"国进士云浦斋中检得骑都尉白鹤亭旧诗数纸笔意迥异时蹊即同过访二首 其一","f":"五言律诗","c":["大雅谁能继，孤吟动感伤。","篇章搜故纸，金石振华堂。","年少能如此，功深岂易量。","平生轻薄意，见尔觉荒唐。"]},{"t":"国进士云浦斋中检得骑都尉白鹤亭旧诗数纸笔意迥异时蹊即同过访二首 其二","f":"五言律诗","c":["宦途经蹭蹬，一笑拂尘襟。","霜重鸿飞远，山空豹隐深。","青灯终古业，白首访君心。","不弃他山石，乾坤是赏音。"]},{"t":"赠舒进士乃来","f":"五言律诗","c":["少壮成名日，文章报国心。","奇书资锐讨，精理渥灵襟。","邂逅惭余老，风尘契汝深。","孤鸣人境外，倾耳听希音。"]},{"t":"盆松","f":"五言律诗","c":["矫矫虬龙势，亭亭数寸阴。","讵知霜烈日，独抱岁寒心。","老石嶙峋白，苍根礧砢深。","无材堪大用，乌几伴枯吟。"]},{"t":"再咏盆松","f":"五言律诗","c":["妖矫盆中势，萧森几上阴。","根株年久固，霜雪岁寒深。","寂寞安贫日，峥嵘未老心。","临风时对尔，音响入鸣琴。"]},{"t":"明惺斋招余偕隐沧洲","f":"五言律诗","c":["我厌尘情秽，君耽遁世高。","青山留傲骨，沧海壮诗涛。","禾黍占晴雨，园蔬自桔槔。","相偕成沮溺，回首笑空劳。"]},{"t":"哭明惺斋三首 其一","f":"五言律诗","c":["夜梦方疑信，晨兴报溘亡。","穷途谁我重，交谊独君长。","风雅坛空在，烟霞愿未偿。","他时听玉笛，何忍赋山阳。"]},{"t":"哭明惺斋三首 其二","f":"五言律诗","c":["十载论交地，千秋此德邻。","升沈终不易，道义老逾真。","久病欣方减，新诗觉有神。","如何违数日，仓卒失斯人。"]},{"t":"哭明惺斋三首 其三","f":"五言律诗","c":["交道今谁重，斯文世所轻。","艰难羁客泪，生死哭君情。","惨雪迷归路，沧波空旧盟。","那堪招隐句，吟作断肠声。"]},{"t":"送六给谏居鲁巡察台湾 其一","f":"五言律诗","c":["岂有千秋望，空耽数卷书。","谩将屈蠖地，错拟卧龙居。","谋道亲樵牧，虚怀媲古初。","感君骢马客，三次到荒庐。"]},{"t":"送六给谏居鲁巡察台湾 其二","f":"五言律诗","c":["旧识疏贫贱，新知正阒寥。","白头甘濩落，青眼重箪瓢。","朔雪燕城暗，云帆瘴海遥。","那堪情始洽，离席祖星轺。"]},{"t":"送六给谏居鲁巡察台湾 其三","f":"五言律诗","c":["应运生申甫，乘时荐马阳。","谠言谟诰协，忧国鬓须苍。","海角敷功烈，葵心注庙堂。","所嗟贤补阙，迢递出蛮方。"]},{"t":"送六给谏居鲁巡察台湾 其四","f":"五言律诗","c":["台湾闽海外，奉命代巡行。","旌节三年驻，云山万里程。","乘骢臣子义，别泪故人情。","计日徯回棹，衔杯续旧盟。"]},{"t":"新春书怀","f":"五言律诗","c":["不揽范滂辔，从挥祖逖鞭。","名山留大业，吾学慕前贤。","白发争先后，新诗记岁年。","所伤时屡易，江海意空悬。"]},{"t":"甲子正月八日重馆竹梧轩","f":"五言律诗","c":["壮志销磨尽，他乡老病俱。","还搜残卷帙，重课旧生徒。","天地苏群动，饥寒困腐儒。","厚生怜八口，吾道乏良图。"]},{"t":"新正访舒乃来不遇","f":"五言律诗","c":["独坐理瑶琴，空鸣太始音。","出城寻故识，策马度荒林。","霭霭檐前日，嘤嘤窗外禽。","相思不相见，归路感何深。"]},{"t":"雨后讲席示诸生","f":"五言律诗","c":["竹梧新讲席，冰雪旧文坛。","业进心逾怯，功深道觉难。","阳春回黍谷，时雨润芳兰。","默默和风转，青灯莫畏寒。"]},{"t":"将出南郊看桃花先简明复庵","f":"五言律诗","c":["每为娱吾性，南郊匹马过。","竹篱春圃外，沙屿野鸥多。","已觉非尘市，兼之足啸歌。","谁能忘此地，花信近如何。"]},{"t":"简同人","f":"五言律诗","c":["云豁南郊路，名园拟畅游。","绿蓑渔舍雨，青旆酒家楼。","俗虑澄秋水，孤情托野鸥。","年华看旅雁，又过白蘋洲。"]},{"t":"题孟颖仙治平略后","f":"五言律诗","c":["万姓食为天，风淳赖养先。","均平怀往政，兼并抑何年。","饱暖忧禽兽，饥寒困圣贤。","古今商治理，遗轨在斯篇。"]},{"t":"雨窗独咏","f":"五言律诗","c":["喜听连朝雨，耽吟五字诗。","叩门无俗物，凿句有奇思。","鹤唳千寻岫，蚕抽独茧丝。","襟期谁与共，窗外绿梧知。"]},{"t":"新秋对月口占","f":"五言律诗","c":["庭院早凉轻，临风恋夜晴。","碧梧疏月影，哀角入云声。","缥缈关河望，推迁岁月惊。","诗成还自咏，展转动离情。"]},{"t":"咏宝鼎","f":"五言律诗","c":["三代调和器，胡为却在兹。","金精谁解重，宗庙不终遗。","饘粥恒于是，伛偻尚有词。","函牛堪大受，少汁莫轻施。"]},{"t":"卢峰口","f":"五言律诗","c":["险阨卢龙塞，经过一怆神。","悲风吹战垒，白骨吊征人。","月落喧狐语，山空耀鬼燐。","前途投宿处，冉冉汨行尘。"]},{"t":"悯流亡","f":"五言律诗","c":["龙沙风雪道，资斧怯前程。","忍见流亡像，哀闻乞命声。","饥寒方切己，胞与复关情。","我欲将图绘，风尘隔帝京。"]},{"t":"宁远州","f":"五言律诗","c":["出关二百里，州治覆寒云。","乱石堆墙短，流泉入圃分。","野狼昏截径，山鬼夜呼群。","问俗难投止，驱车背夕曛。"]},{"t":"宁远道中","f":"五言律诗","c":["征轺超崱屴，落叶照沙尘。","石险频惊马，山空偶见人。","鸣鸿哀旷野，荒草白深春。","此际逢歧路，凭谁一问津。"]},{"t":"经牧马场","f":"五言律诗","c":["龙堆千里道，极目望茫茫。","草木穷寒麓，风云惨大荒。","地邻箕子国，居近管宁乡。","有客怀南土，魂惊牧马场。"]},{"t":"胡家窝铺","f":"五言律诗","c":["险溺胡家铺，行人莫不闻。","地顽常带卤，山蠢不生云。","草滑埋蛇穴，风腥过虎群。","往来经此处，踯躅畏斜曛。"]},{"t":"陈家台述事","f":"五言律诗","c":["岁俭多宵小，颓垣户牖通。","既眠愁盗马，不寐听嘶风。","岂是燕台骏，深惭塞上翁。","晨兴看结蚓，骧首海云东。"]},{"t":"望北台早发","f":"五言律诗","c":["晓起天无色，星光浸冷溪。","荒榛塞古道，野戍听晨鸡。","林黑椎埋匿，风生草树嘶。","此心长惴惴，残梦逐轮蹄。"]},{"t":"宿大石桥","f":"五言律诗","c":["去家三十里，犹隔一宵程。","两岸众峰敛，一钩新月明。","近乡思愈切，久别恨旋生。","不寐听残夜，荒鸡下五更。"]},{"t":"述梦","f":"五言律诗","c":["岂是尘寰境，宁无栖隐心。","空香生绣陌，碧涧泻松阴。","我欲桃源去，人言山径深。","徘徊歧路侧，曙色动窗禽。"]},{"t":"奉窆先二人后述哀","f":"五言律诗","c":["风木悲今日，鸡豚尽此生。","一抔黄土泪，终古北邙情。","云起结愁色，溪流涌恨声。","乳鸦思返哺，绕树但哀鸣。"]},{"t":"怀都门诸友","f":"五言律诗","c":["芍药期将过，安榴花复开。","遥知清赏处，应念白头回。","片月千山里，孤云万里来。","相思情正剧，邻笛不胜哀。"]},{"t":"怀竹梧轩诸生并门人沈周颋","f":"五言律诗","c":["远客情怀恶，出门日已多。","诸生狂未减，瘦沈病如何。","海角吹残戍，边风涌白波。","长安斜照外，翘首望岩阿。"]},{"t":"留别门人何公符兼谢厚贶","f":"五言律诗","c":["失路同为客，君情迥出群。","搜厨谋一饭，倾橐赆千文。","梦绕辽疆月，心催汉戍云。","那堪今日别，鱼雁莫稀闻。"]},{"t":"与友人论诗","f":"五言律诗","c":["旷代斯文责，肩兹若有神。","讴吟恒自得，商榷定谁真。","风雅将兴日，乾坤未死身。","立言诚大业，天意属何人。"]},{"t":"背阴铺遇雨","f":"五言律诗","c":["日午增烦热，征途汗透冠。","风生来骤雨，云起忽埋山。","深慰农家望，旋愁行路难。","赊程看旅橐，不寐听潺湲。"]},{"t":"将赴辽东约门人沈周颋摄馆事两月余归迟沈已如期去一月矣怅然有作","f":"五言律诗","c":["远行念诸子，馆课尔堪招。","作客身多病，怀亲路觉遥。","梦回燕塞月，心折海门潮。","归去瓜期届，予诚愧久要。"]},{"t":"自辽东抵京往晤天峰云浦鹤亭即订西山之游得山字","f":"五言律诗","c":["道路三千里，风尘百日还。","盍簪欣晤语，林壑想追攀。","孤鹤立寒渚，断云归远山。","披襟同啸咏，俗虑净岩间。"]},{"t":"前题步天峰韵","f":"五言律诗","c":["西麓饶名胜，幽深别有天。","官閒曾过赏，尘隔几经年。","樵子石梁路，渔罾荻浦烟。","相期蜡双屐，幽兴寄林泉。"]},{"t":"秋夜读书 其一","f":"五言律诗","c":["断绝浮尘梦，支离世外居。","青灯堪耐久，白发不违初。","阴砌虫鸣露，寒更月照庐。","功深风雨后，甘苦竟何如。"]},{"t":"秋夜读书 其二","f":"五言律诗","c":["吾道残编在，秋斋翠色深。","杜门如老衲，力学尚童心。","霜叶鸣寒牖，风枝动夜禽。","年来人事少，稽古遂抽簪。"]},{"t":"庭前残卉为秋风所捲唯寒蛩疏竹而已反觉清耳豁目","f":"五言律诗","c":["荒秽驱风力，三秋贮月明。","未归湖海棹，聊寄薜萝情。","翠竹独居色，寒蛩夜坐声。","寂喧随万感，心与境俱清。"]},{"t":"冬 其一","f":"五言律诗","c":["羁客伤迟暮，隆冬发浩吁。","市居惭大隐，讲席愧通儒。","牢落精华铄，冰霜月夜孤。","无裘难卒岁，掩卷意踟蹰。"]},{"t":"冬 其二","f":"五言律诗","c":["身世馀残梦，琴书滞远天。","严风摧万汇，衰骨凛深渊。","久历炎凉境，今非少壮年。","老安夫子愿，应倍悯寒毡。"]},{"t":"送年家子毛秋岑归窆祖茔余有同约至期不遂","f":"五言律诗","c":["卜阡余负约，夙愿尔无违。","洒我思乡泪，沾君返国衣。","越江孤棹远，燕塞早鸿飞。","有梦随荒麓，相携上翠微。"]},{"t":"再送秋岑","f":"五言律诗","c":["杯酒送君行，秋风落叶声。","同悲衰老日，可奈别离情。","孤屿扁舟夜，荒江古月明。","遥思悽绝处，噭噭听猿鸣。"]},{"t":"三题松乔小室","f":"五言律诗","c":["小室藏幽邃，公馀足自娱。","纵横四五步，花竹两三株。","长日鸦反哺，晴檐燕引雏。","家庭饶至乐，岂必羡华膴。"]},{"t":"四题小室","f":"五言律诗","c":["入世仍尘迹，公归即散襟。","移花邀月近，款竹闭门深。","鱼亦濠梁乐，云留谷口阴。","此中真味永，得意托微吟。"]},{"t":"北牖","f":"五言律诗","c":["南荣思曝背，北牖苦寒侵。","风透成冰室，云留酿雪阴。","客心增岁暮，老貌觉愁深。","逸调弹隆古，寥寥孰赏音。"]},{"t":"往晤云浦留饮竟日","f":"五言律诗","c":["龙塞萦遥思，蜗庐减壮裁。","寂寥残腊候，冰雪故人来。","辽海倾诗橐，燕山共酒杯。","更看周急意，襟抱对君开。"]},{"t":"赋得岁寒松","f":"五言律诗","c":["万物凋零日，青苍见尔辰。","虽能甘苦节，非不愿阳春。","岂羡知稀贵，偏于岁暮亲。","四时无改序，淹寂亦何瞋。"]},{"t":"除夕","f":"五言律诗","c":["惨淡谋尊酒，妻孥坐夜阑。","岁从明日改，腊尽片时欢。","艰苦年来惯，身心老渐安。","敢同颜子乐，颇识送穷难。"]},{"t":"元日","f":"五言律诗","c":["一从辞宦籍，五载客长安。","湖海难酬愿，风尘且驻颜。","繁华新物态，诗酒自人间。","来往从纷剧，衡门镇日关。"]},{"t":"客斋见月","f":"五言律诗","c":["出世心如昨，羁尘迹尚初。","深宵闻远笛，孤月照荒庐。","诗句随年老，交情隔势疏。","茫茫天宇下，何处卜吾居。"]},{"t":"仲夏过明复庵别业","f":"五言律诗","c":["仲夏苦炎热，幽栖出郭寻。","淹君高树荫，清我远尘襟。","山鸟偶然下，谷云时作阴。","对兹真作乐，聊可傲华簪。"]},{"t":"秋 其一","f":"五言律诗","c":["昼夜无停运，乾坤自混濛。","万殊陶大化，一物杂昆虫。","甘苦缘生命，荣枯各始终。","无端秋又至，萧飒下天风。"]},{"t":"秋 其二","f":"五言律诗","c":["索居多物感，孤坐易情伤。","白露几时下，西风昨夜狂。","雁归知塞苦，人老觉秋忙。","回首思年少，悤悤两鬓霜。"]},{"t":"秋 其三","f":"五言律诗","c":["白帝司秋令，当之草木棼。","但知成委折，那复辨莸薰。","霜杵敲寒月，边鸿叫夜云。","商声无远近，孤客不堪闻。"]},{"t":"秋 其四","f":"五言律诗","c":["觉后原吾任，逡巡未尽迂。","风尘无巨识，今古薄真儒。","作客非长计，依人岂壮夫。","云中瞻白鹤，翘翮笑樊笯。"]},{"t":"秋 其五","f":"五言律诗","c":["浊秽方从俗，幽深岂自如。","烟霞思海屋，风雨恋蜗庐。","遐契何能遂，尘情未易除。","去留难自主，搔首问晴虚。"]},{"t":"秋 其六","f":"五言律诗","c":["百龄浑易尽，垂白尚浮踪。","老树延孤鹤，阴丛集乱蛩。","一灯寒夜雨，双鬓暮秋容。","惓惓终何益，名山有桂松。"]},{"t":"赠年家子戈编修芥舟李编修廉衣","f":"五言律诗","c":["宇宙谁同调，风尘岁月惊。","斯文逢二子，吾道不孤鸣。","旦夕庸人计，千秋志士情。","问年均可畏，头白感商声。"]},{"t":"雨后偶成","f":"五言律诗","c":["庭前新雨歇，把卷思无端。","明月露松隙，草虫鸣夜阑。","诗文随我贱，肝胆向人寒。","薄劣从浮世，幽偏觅古欢。"]},{"t":"简明复庵","f":"五言律诗","c":["烟海茫茫世，卑栖但浊尘。","交游四十载，寒士两三人。","每爱石林静，兼怀襟抱真。","携筇频出郭，沽酒莫辞贫。"]},{"t":"负游","f":"五言律诗","c":["空斋增抑郁，游约负前盟。","幽梦灵崖结，孤怀俗务婴。","苍山悬暮雨，黄叶下秋声。","谁识残年里，殷殷世外情。"]},{"t":"送孟颖仙任东平州佐四首 其一","f":"五言律诗","c":["两世金兰旧，千秋德义新。","白头将共老，童稚早情亲。","崇替经交态，初终见古人。","别离分显晦，邂逅复谁真。"]},{"t":"送孟颖仙任东平州佐四首 其二","f":"五言律诗","c":["学业谁堪并，迍邅可若何。","济东新雨露，燕市旧悲歌。","知己情难别，期君意倍苛。","为贫聊试仕，远抱莫蹉跎。"]},{"t":"送孟颖仙任东平州佐四首 其三","f":"五言律诗","c":["著书期寿国，夙愿未全非。","旧俗东平厚，今春麦秀肥。","题舆勷牧治，捧檄出皇畿。","学道思言偃，牛刀用岂违。"]},{"t":"送孟颖仙任东平州佐四首 其四","f":"五言律诗","c":["雄飞传赵鼎，佐岳起陈蕃。","脱颖锥初试，冲霄剑欲抡。","济云连粉署，岱色覆琴尊。","政暇饶佳制，因风寄荜门。"]},{"t":"题赠平主事弼侯新居 其一","f":"五言律诗","c":["官授小司空，君曾远戍戎。","野狐秋拜月，塞马夜嘶风。","旧历边庭险，新营竹石工。","巾车期不忘，此意亦何穷。"]},{"t":"题赠平主事弼侯新居 其二","f":"五言律诗","c":["何人勤在昔，留此待君娱。","林壑气相结，冈峦势不孤。","苔生新履迹，庭敞卧游图。","心远齐喧寂，朝昏乐故吾。"]},{"t":"题赠平主事弼侯新居 其三","f":"五言律诗","c":["退食耽清课，幽人乐在斯。","随花閒甃石，就水暗通池。","邀客舒吟啸，呼童具酒卮。","一从叨末座，留恋意长驰。"]},{"t":"题赠平主事弼侯新居 其四","f":"五言律诗","c":["遥识炎天爽，幽居惬素襟。","藤萝经暑薄，松竹受阴深。","就榻宜高枕，登台豁远岑。","凭兹离俗意，堪證出尘心。"]},{"t":"题赠平主事弼侯新居 其五","f":"五言律诗","c":["连朝愁酷热，台榭拟攀跻。","瓜果消炎日，诗文寄赫蹄。","长林麋鹿性，丰草野禽栖。","乘兴探幽邃，应教出处迷。"]},{"t":"连日苦热因忆明复庵别业 其一","f":"五言律诗","c":["朱明增酷烈，离垢想清芬。","槐荫留长日，山房接断云。","园蔬经雨摘，村酒隔篱分。","风味宛如昨，孤吟怅夕曛。"]},{"t":"连日苦热因忆明复庵别业 其二","f":"五言律诗","c":["僻处违城市，相求独往还。","人嫌茅屋漏，我爱竹林閒。","草色荒行径，松阴覆掩关。","徘徊时北望，云树隔颓颜。"]},{"t":"荷溪晚步偕诸同人","f":"五言律诗","c":["缓步循溪岸，探荷涤暑氛。","风轻鸥梦觉，水净月痕分。","佛火明僧梵，箫声隔浦云。","冠童人五六，归咏自成群。"]},{"t":"荷溪夜步用前韵","f":"五言律诗","c":["荷香邀客兴，柳岸净尘氛。","明月照沙际，披襟坐夜分。","身閒宽杖履，头白眷烟云。","凫雁情何逸，将随尔作群。"]},{"t":"荷溪","f":"五言律诗","c":["终年长作客，何处可娱情。","贪看桥西水，时为饭后行。","湖光生静绪，山色召幽盟。","科跣无相识，孤吟每月明。"]},{"t":"荷溪独往","f":"五言律诗","c":["咫尺桥西路，香风动芰荷。","罢餐长散步，无伴亦相过。","逸兴亲鱼棹，閒心羡雨蓑。","新诗吟欲就，隐隐起菱歌。"]},{"t":"荷溪偕门人昭信","f":"五言律诗","c":["湖上风光好，千回不厌劳。","天连平水阔，山接暮云高。","牢落从时辈，逍遥付我曹。","尔能随杖履，解此亦人豪。"]},{"t":"荷溪独往","f":"五言律诗","c":["最可披襟处，纷趋但市寰。","人情殊好尚，吾道合湖山。","鱼鸟若为侣，烟霞相与閒。","月明群籁静，踽踽踏沙还。"]},{"t":"立秋前荷溪","f":"五言律诗","c":["书斋西数武，别有远尘天。","芒履偶然到，沧洲久自专。","藤萝垂暮雨，桑柘起疏烟。","景色新秋近，轻凉亦可怜。"]},{"t":"荷溪偕庆祠部松乔","f":"五言律诗","c":["未遂岩栖志，聊寻逆旅欢。","看云思郑谷，临水忆湘兰。","尘市形骸局，湖山天地宽。","此情君若达，应不恋閒官。"]},{"t":"荷溪示诸生","f":"五言律诗","c":["百年唯适意，富贵欲何如。","直道人情远，迂儒世务疏。","溪山留造化，天地饷樵渔。","尔辈成名后，应思早遂初。"]},{"t":"和白鹤亭送无凡上人结茅盘山原韵 其一","f":"五言律诗","c":["振锡超尘境，飘然远绝群。","松门衔峭壁，石榻沤寒云。","一法心无住，千江月不分。","遥知莲社侣，携笑虎溪闻。"]},{"t":"和白鹤亭送无凡上人结茅盘山原韵 其二","f":"五言律诗","c":["性空虽不昧，尘海亦徒然。","撒手名山去，归心古佛前。","岭猿清妙悟，松月静安禅。","回首泥涂界，人天隔幻烟。"]},{"t":"前题再叠原韵 其一","f":"五言律诗","c":["此去成长往，甘心草木群。","移花秋贮月，种石夜留云。","禅室钟鱼静，斋粮鸟雀分。","山窗空际雨，应向定中闻。"]},{"t":"前题再叠原韵 其二","f":"五言律诗","c":["结茅空翠辟，烛径野花然。","樵路侵厨过，峰峦赴榻前。","澄潭空众象，秋月照枯禅。","时有探奇兴，携筇涧底烟。"]},{"t":"前题三叠原韵 其一","f":"五言律诗","c":["田盘高莫极，清冷出人群。","霄汉长悬月，虚空不住云。","钟鸣山谷应，竹引石泉分。","红叶萧萧落，秋声静里闻。"]},{"t":"前题三叠原韵 其二","f":"五言律诗","c":["谁识根尘净，今能得自然。","鸟啼山月上，门掩谷云前。","漉酒閒中课，敲诗醉后禅。","远公高卧处，翘首但苍烟。"]},{"t":"秋夜怀台湾六巡察居鲁","f":"五言律诗","c":["嘹唳雁声高，秋空月丽霄。","孤斋亲浊酒，万里隔寒宵。","滩雨蛮烟路，星槎海国潮。","故人官绝域，书札望迢遥。"]},{"t":"送云浦出塞觐亲 其一","f":"五言律诗","c":["每至黄花节，频伤出塞軿。","况当新抱恨，不比旧趋庭。","桐杖扶边月，风林惨客星。","乳鸦哀苦韵，忍畏老亲听。"]},{"t":"送云浦出塞觐亲 其二","f":"五言律诗","c":["晓起严征橐，霜花入望纷。","马头升旭日，鸿背落寒云。","海气深秋肃，笳声绝塞闻。","旅怀当此际，一倍感离群。"]},{"t":"送云浦出塞觐亲 其三","f":"五言律诗","c":["贪程悲不觉，游子暮何依。","落日孤烟远，辽天古木稀。","长途趋色养，回首念慈帏。","霜露情悽怆，中宵泪满衣。"]},{"t":"送云浦出塞觐亲 其四","f":"五言律诗","c":["居邻辽水岸，牧野旧非田。","骄马嘶风烧，奔狼骇猎烟。","君经沙漠地，我忆雪霜天。","羁旅怜同调，空斋计日还。"]},{"t":"闻警 其一","f":"五言律诗","c":["九重敷德化，万国凛王章。","致乱伊谁咎，安危庙算长。","舆图全盛日，宵小敢跳梁。","应瘽如伤虑，哀矜慰善良。"]},{"t":"闻警 其二","f":"五言律诗","c":["晋阳边寨接，仓卒报烟尘。","拥节虚名将，宣威遣大臣。","饥寒趋险步，盗贼本良民。","四境期宁谧，嘉谟在抚循。"]},{"t":"秋怀杂感 其一","f":"五言律诗","c":["一身随化转，万感逼秋来。","老骨风霜练，残年日月摧。","寒生边地苦，愁结暮笳哀。","岂有超尘识，雄心却早灰。"]},{"t":"秋怀杂感 其二","f":"五言律诗","c":["精华疲出处，岁月缚饔飧。","售世才无用，传经道不尊。","云心盟海鹤，风翮变神鲲。","近得吴山逸，相期隐鹿门。"]},{"t":"秋怀杂感 其三","f":"五言律诗","c":["碌碌成何事，纷纷困浊泥。","人情同画虎，吾道类醯鸡。","不识青云路，终当皓首迷。","烟霞泉石外，信有好楼栖。"]},{"t":"秋怀杂感 其四","f":"五言律诗","c":["婆心堪自信，苦口事全殊。","已历人情久，方知吾道孤。","发蒙无厚力，立雪有前儒。","抱瑟归蓬户，齐门耻滥竽。"]},{"t":"秋怀杂感 其五","f":"五言律诗","c":["力学何终极，耄年志不昏。","寸心争日月，斗室贮乾坤。","春雨浓花径，秋霜老树村。","寄情荣悴外，得意向谁论。"]},{"t":"秋怀杂感 其六","f":"五言律诗","c":["久稔人情幻，频增景物愁。","霜蛩寒叫月，风萚夜鸣秋。","海岳思平庆，云山忆点求。","和光宜用晦，终觉此心不。"]},{"t":"秋怀杂感 其七","f":"五言律诗","c":["西峰萦叆叇，翘首望连延。","红叶空山雨，青槐古寺烟。","林泉谁作主，登眺我无缘。","咫尺违佳赏，遐心一倍悬。"]},{"t":"秋怀杂感 其八","f":"五言律诗","c":["乾坤操大运，今古递相推。","庸碌欢娱日，英贤恐惧时。","披书堪自鉴，处世畏人知。","囊括期无咎，将随木石居。"]},{"t":"秋怀杂感 其九","f":"五言律诗","c":["闻说畿东路，阳侯肆虐豪。","三齐成巨浸，万姓委洪涛。","调燮资华衮，流离恻缊袍。","銮舆将远幸，恩泽慰呼号。"]},{"t":"秋怀杂感 其十","f":"五言律诗","c":["岂乐羁尘世，中怀愿莫酬。","两棺贫未举，八口计难周。","慈孝非能尽，神仙不可求。","敢言乘六气，无待与天游。"]},{"t":"秋怀杂感 其十一","f":"五言律诗","c":["诗书千载业，辛苦百年身。","嗜古甘违俗，为儒不厌贫。","青箱承世泽，白首付何人。","展卷然疑作，空闻有德邻。"]},{"t":"秋怀杂感 其十二","f":"五言律诗","c":["百岁难辞累，悽然念此生。","飘零亲属计，孤寡远乡情。","黄卷终何用，丹沙未易成。","雪霜盈鬓发，皎皎镜中明。"]},{"t":"秋怀杂感 其十三","f":"五言律诗","c":["举世谁知己，深秋倍郁陶。","风霜摧劲节，兰蕙悴盲飙。","大业愁担荷，名山正寂寥。","抗怀期尚友，乐道有箪瓢。"]},{"t":"秋怀杂感 其十四","f":"五言律诗","c":["才过黄花节，萧条满目伤。","山川囚苦月，天地梏严霜。","皋比愁空坐，文章气不扬。","扶筇时出户，风色望苍苍。"]},{"t":"秋怀杂感 其十五","f":"五言律诗","c":["蘋藻襄公事，知谁是女宗。","妍媸无定态，进退欲何从。","弃妇多贞操，新妆但丽容。","不忘葑菲咏，旨蓄御严冬。"]},{"t":"秋怀杂感 其十六","f":"五言律诗","c":["才华矜敏捷，裘马斗缤纷。","陇水原无定，初流势已分。","苦心乖世好，老貌杂人群。","自顾形骸秽，身藏岂用文。"]},{"t":"秋怀杂感 其十七","f":"五言律诗","c":["眠食安常性，粗疏亦任人。","事多增旅况，病易入衰辰。","老骥犹存骨，神鹰耻受驯。","羁绦何自束，将欲遂天真。"]},{"t":"秋怀杂感 其十八","f":"五言律诗","c":["生涯虽淡薄，启处觉徜徉。","别有荣华境，非关富贵场。","朱弦流逸韵，湘茝发寒芳。","相赏尘嚣外，知稀亦不妨。"]},{"t":"秋怀杂感 其十九","f":"五言律诗","c":["穷途安此日，宦海忆当年。","容膝论何地，抽簪遂所天。","藜床穿可坐，锻灶煖堪眠。","在昔庾开府，深知二子贤。"]},{"t":"寄答边赵珍","f":"五言律诗","c":["荆山和氏璧，流水伯牙琴。","岂不宜高价，其如乏赏音。","功名陶大块，学业粹分阴。","不受穷通囿，方知玉汝心。"]},{"t":"读道书","f":"五言律诗","c":["精纯堪入圣，玄妙亦非狂。","不坏人间相，兼希物外方。","道参天地始，心契鬼神藏。","生死真消息，群言岂尽荒。"]},{"t":"季春晦日晚步金鱼池得通字","f":"五言律诗","c":["鱼沼寻昏黑，崎岖僻径通。","沾衣垂露草，迎面落花风。","石髓鸣幽涧，星光炯太空。","归途增夜寂，清梵出云丛。"]},{"t":"闻蛩","f":"五言律诗","c":["秋来人不觉，偏尔识凉温。","清露下庭际，哀音动草根。","孤踪长冷落，荒径易黄昏。","微雨兼明月，谁堪永夜喧。"]},{"t":"九日郊宴","f":"五言律诗","c":["折简邀同辈，登临破郁陶。","但知狂纵酒，不敢妄题糕。","捲地惊沙起，鸣霄旅雁高。","残阳欹远树，天畔落云涛。"]},{"t":"古庙","f":"五言律诗","c":["后起千年树，先来一片山。","老僧勤导引，颓磴苦跻攀。","萝薜牵秦月，箴铭勒汉环。","诸天皆寂灭，何处问无还。"]},{"t":"过金鱼池 其一","f":"五言律诗","c":["暮春偕道侣，春服试初成。","经雨林花色，衔泥水燕情。","野风吹面暖，岚气傍衣生。","浴咏思前哲，遥遥结远盟。"]},{"t":"过金鱼池 其二","f":"五言律诗","c":["违俗原无意，馀生自有涯。","谈经寻僻地，沽酒就晴沙。","野日迟菱浦，风泉落涧花。","但教予性适，谁识世情赊。"]},{"t":"过金鱼池 其三","f":"五言律诗","c":["野酌无专向，幽寻信屐踪。","沼鱼晴弄影，沙渚细含风。","虎仆抽新藻，龙兹藉落红。","萧然濠濮上，胸境一时空。"]},{"t":"过金鱼池 其四","f":"五言律诗","c":["幽思萦新句，奇情恋落晖。","清风时拂座，空翠偶沾衣。","疏野真成癖，嬉游未尽非。","归来天欲暮，乘兴叩僧扉。"]},{"t":"雨后鱼溪 其一","f":"五言律诗","c":["昨苦泥途滑，今来霁景分。","诗情随笠屐，林壑绝埃氛。","白石蒸残雨，青天补漏云。","往还行径熟，鸥鸟久为群。"]},{"t":"雨后鱼溪 其二","f":"五言律诗","c":["兴来无早暮，放步即邱林。","拥鼻从人笑，探幽且自吟。","烟云工变态，鱼鸟识閒心。","眷恋斜阳下，遥山入望深。"]},{"t":"雨后鱼溪 其三","f":"五言律诗","c":["万汇晴光里，微躯物色俱。","澄怀亲水石，观化会虚无。","绿藻鱼遗子，微风燕引雏。","真机随处得，相赏有吾徒。"]},{"t":"雨后鱼溪 其四","f":"五言律诗","c":["沽酒延清赏，攀荆坐绿丛。","溪云停宿雨，沙鸟落轻风。","避俗身耽寂，看山兴不穷。","疏狂成痼癖，此意复谁同。"]},{"t":"雨后鱼溪 其五","f":"五言律诗","c":["但有开襟处，相将兴不阑。","路从渔父得，山许野人看。","素尚虽难遂，幽寻亦自欢。","乾坤容我放，未肯信衰残。"]},{"t":"对镜","f":"五言律诗","c":["形色根于性，虚明照若神。","检身惭寡过，觌面不惊人。","岁月诚难假，须眉到老真。","遐思姑射子，冰雪貌长春。"]},{"t":"对镜步张生光模韵","f":"五言律诗","c":["皎洁君能守，真常我不如。","发须将白尽，愿力未酬初。","深虑精华铄，频惊岁月虚。","前途难预鉴，相对一长歔。"]},{"t":"散步","f":"五言律诗","c":["散步开荆户，支颐听鸟音。","断云侵榻冷，小雨过山阴。","世事终难测，交情不敢深。","天留閒岁月，遥寄鹿门心。"]},{"t":"廷璋儿以武举效力京营千总秉瑛侄以进士试用户部主事数年资其薄俸以供饘粥今二子前后归班候选生路遂绝赋此见志且励二子固贫之志不可不坚也","f":"五言律诗","c":["生机何所赖，官罢废饔飧。","不有安贫乐，焉知陋巷尊。","无谋宜困阨，守死报乾坤。","应笑皋夔侣，饥来叩富门。"]},{"t":"赠金鱼池酒肆主人 其一","f":"五言律诗","c":["相逢沽酒肆，混迹亦泉林。","阅尽尘寰态，无妨栖隐心。","山光当户列，云色傍檐阴。","时有观鱼乐，衔杯濠上吟。"]},{"t":"赠金鱼池酒肆主人 其二","f":"五言律诗","c":["车马纷驰地，唯馀此际閒。","襟怀耽泌水，阛阓即深山。","庭敞峰争入，池幽鸟去还。","应嗤茂陵叟，卖赋向人间。"]},{"t":"过金鱼池酒肆","f":"五言律诗","c":["酒肆人间世，幽寻不觉喧。","千峰奔座榻，一水漱篱根。","茗椀亲鱼藻，诗情寄鹿门。","呶呶沈醉客，相顾两无言。"]},{"t":"宿卧佛寺精舍","f":"五言律诗","c":["日入众山悄，谷禽时一鸣。","閒房留半榻，明月上初更。","云去天无迹，风来树有声。","根尘何日净，相对说无生。"]},{"t":"戊辰七月六日举子命名廷璧","f":"五言律诗","c":["夜乏维熊兆，朝闻异雀鸣。","果能承父业，敢望大家声。","白首嗟余老，何时见汝成。","几篇残著作，辛苦历平生。"]},{"t":"久雨忽晴","f":"五言律诗","c":["经月苦淋涝，瀰漫天地昏。","豁然开暮景，相约出衡门。","碧水沈云色，青山带雨痕。","高飞看野鹤，去去没遥村。"]},{"t":"秋晓","f":"五言律诗","c":["短杖策晨露，高天过塞鸿。","孤云宿危石，幽草生凉风。","秋色既如此，暮怀相与同。","徘徊无尽意，举首望长空。"]},{"t":"秋日溪行","f":"五言律诗","c":["斜日明村巷，商声动暮蝉。","一年将欲尽，百岁岂徒然。","坐起草沙际，夷犹云鸟前。","愁心无处著，随意此留连。"]},{"t":"雨后看山","f":"五言律诗","c":["望久山无色，苍茫立钓矶。","豁然高壁露，知是薄云归。","鹅鸭爱新雨，儿童嬉落晖。","世情难尽遣，聊且学忘机。"]},{"t":"寄怀单青侅","f":"五言律诗","c":["偶然得聚首，遂尔成知音。","浊酒冰霜别，故人关塞深。","东风变芳草，离思结春阴。","望久无来雁，徒增岑寂心。"]},{"t":"寄怀杨子安","f":"五言律诗","c":["相识未云久，相知觉己深。","寒风吹别泪，芳树霭新阴。","漏静发遥思，月明无两心。","蚕丛西蜀道，魂梦历危岑。"]},{"t":"李廉衣来京己两月矣遍寻不晤感赋 其一","f":"五言律诗","c":["道义偶然合，绸缪遂至今。","早知松柏性，不畏雪霜侵。","阔别三年久，相思此日深。","徽音如在望，跂睇缈云岑。"]},{"t":"李廉衣来京己两月矣遍寻不晤感赋 其二","f":"五言律诗","c":["几度扶筇出，寻君空复还。","萧斋肠若结，孤榻梦相关。","梁苑何能到，青云不可攀。","窗禽春唤侣，终日语绵蛮。"]},{"t":"客境","f":"五言律诗","c":["客境从飘泊，生涯若有无。","饥寒持岁月，潦草聚妻孥。","敢谓人情薄，深惭吾道孤。","谋生原不易，况是老迂儒。"]},{"t":"闻蝉","f":"五言律诗","c":["三伏时方半，炎威势正横。","哀蝉声忽咽，凉露意潜惊。","多是穷愁客，易生迟暮情。","白头孤馆里，偏听尔长鸣。"]},{"t":"壬申正月十一日纪事","f":"五言律诗","c":["炊烟断蜗室，惨雪洒鹅毛。","沟壑安吾分，饥寒愧汝曹。","衰残难自诿，奔走亦徒劳。","此境平生惯，高吟且自豪。"]},{"t":"任东涧访余仪徵县署留话三日赋赠","f":"五言律诗","c":["就养真阳署，深藏异隐沦。","薄材安腐朽，同气别风尘。","不患无知己，终愁逊古人。","逢君旋复去，相送意逡巡。"]},{"t":"真州距杭城仅数百里自夏徂秋己历三月不能一省祖墓雨后见月感赋","f":"五言律诗","c":["来此夫何事，淹留起暮愁。","江山邻故国，风雨滞行舟。","白发心多感，他乡月易秋。","望云挥老泪，魂梦越江游。"]},{"t":"题观稼图","f":"五言律诗","c":["身膺民社寄，民以食为天。","命棹随流水，觇农遍野阡。","沙鸥浮远渚，山雨洒平田。","岂博循良誉，公私望有年。"]},{"t":"送金纫芷归全椒即用留别原韵","f":"五言律诗","c":["契合原非易，分携倍觉难。","尊醪残腊候，风雪暮江寒。","白发诗文约，青灯岁月宽。","回舟梅正发，相待早春看。"]},{"t":"游潘园酬沈沃田江松泉","f":"五言律诗","c":["园小依城筑，楼高傍水开。","春晴一登眺，山色渡江来。","廉使饶清兴，诸君不易才。","莺花陪胜宴，衰朽愧新裁。"]},{"t":"乙亥上巳约署中诸友游吴园雨阻不践","f":"五言律诗","c":["客斋逢禊日，相约出尘氛。","花鸟摧淫雨，林亭阻大云。","春光聊滞我，高致岂虚君。","待得新晴后，登临意倍欣。"]},{"t":"三月八日吴园脩禊","f":"五言律诗","c":["名园喜初霁，脩禊践幽寻。","石耸峰峦古，烟生洞壑深。","和风吹老貌，春水涤烦襟。","忽忆山阴会，遥遥隔古今。"]},{"t":"题见山楼","f":"五言律诗","c":["缥缈立高楼，新晴豁远眸。","天垂荒野阔，山夹大江流。","花鸟三春丽，乾坤一望收。","苍茫东海外，彷佛见瀛洲。"]},{"t":"晚斋坐雨步纫芷原韵","f":"五言律诗","c":["时序春光晚，昏埋雨气深。","水连高岸阔，云涌大江沈。","岁月淹胥浦，乡关动越吟。","松楸天际望，展转莫愁侵。"]},{"t":"九日游吴园步韵","f":"五言律诗","c":["晴色丽朝暾，肩舆出郭门。","招携酬令节，取次历名园。","丘壑高人致，烟霞过客魂。","小山丛桂外，将拟采芳荪。"]},{"t":"和金仁趾乞任东涧撰大父竹溪先生诗叙原韵","f":"五言律诗","c":["大父真人瑞，文孙亦世贤。","诗歌垂隐德，扬扢赖洪篇。","艰苦唯斯道，嗟跎及暮年。","江淹才欲尽，把卷意茫然。"]},{"t":"乙亥生日书怀","f":"五言律诗","c":["残年心易足，回首事多惊。","岁月崎岖过，文章惨淡成。","湖山新老眼，梅竹遂平生。","东望钱塘近，扁舟独往情。"]},{"t":"佛手柑","f":"五言律诗","c":["断却黄金臂，高秋世外悬。","未参心即佛，先示指头禅。","接引空垂相，归依待有缘。","何人求解脱，稽首问真诠。"]},{"t":"瓶中红梅","f":"五言律诗","c":["青障回残腊，红梅放早芳。","折来供几席，生意见冰霜。","貌古非无色，寒深自有香。","谁于萧索候，相赏弗相忘。"]},{"t":"答东涧老人","f":"五言律诗","c":["冰雪双蓬鬓，乾坤两布衣。","久甘身寂寞，不问世轻肥。","老益诗情壮，狂憎酒力微。","百年閒事业，耽此未全非。"]},{"t":"熊某为写小照诗以赠之","f":"五言律诗","c":["科头非戾俗，觌面岂惊人。","顾我才无用，知君笔有神。","栖崖云自古，采药涧长春。","他日酬微尚，名山绘始真。"]},{"t":"丙子二月二十七日自真州赴杭省祖墓","f":"五言律诗","c":["辽海归无日，西泠旧有坟。","青年频入梦，白首但空闻。","帆挂长江月，心依故国云。","裹粮酬夙愿，春景正氤氲。"]},{"t":"瓜州渡江","f":"五言律诗","c":["瓜步扁舟晓，金山翠霭澄。","莺花三月渡，风土百年心。","地势分南北，江流自古今。","废兴思往迹，感叹一何深。"]},{"t":"晚泊","f":"五言律诗","c":["古岸维舟后，清灯对酒时。","竹深渔唱晚，江迥雁飞迟。","无计酬黄石，空怀茹紫芝。","飘零归故国，惭愧老天涯。"]},{"t":"三月八日桃源岭展祖墓","f":"五言律诗","c":["策杖缘湖岸，披荆觅墓门。","望空三酹酒，剪纸一招魂。","泪洒流泉溢，悲深野日昏。","欲回天色暮，惆怅立郊原。"]},{"t":"展墓后述哀","f":"五言律诗","c":["艰难依北塞，生死绝南征。","古冢荒榛合，悲风薄暮生。","老亲他日泪，游子百年情。","幸不先朝露，犹来献一觥。"]},{"t":"五月十六日奉窆曾祖母陈太君祖父葭湄公于杭城留下之安乐山","f":"五言律诗","c":["开尊浇厚土，卜吉妥幽魂。","远水潆沙岸，群山拱墓门。","相形宜震巽，表石示儿孙。","敢妄希荣显，相期笃本原。"]},{"t":"五月二十日自杭返仪徵舟中纪行 其一","f":"五言律诗","c":["舟行真自在，风顺不稽程。","天逐江流转，帆随鸟翼轻。","越山青未断，吴岫远相迎。","少泊依沙岸，东冈月色明。"]},{"t":"五月二十日自杭返仪徵舟中纪行 其二","f":"五言律诗","c":["已解嘉禾缆，兼程一叶轻。","雨收黄歇浦，帆挂吕蒙城。","未觉劳行役，閒生吊古情。","忽闻江上笛，悽切作离声。"]},{"t":"京口渡江与金孝廉棕亭同作","f":"五言律诗","c":["行李发江东，帆轻御便风。","几朝同啸咏，千里破空濛。","天入南徐阔，山经北固雄。","君才堪利涉，吾道近蓑翁。"]},{"t":"官斋","f":"五言律诗","c":["官斋三载住，公事一无闻。","就养非高隐，劳生且出群。","性怜娇女慧，学喜幼儿勤。","犹子循声著，清贫意颇欣。"]},{"t":"维扬远眺","f":"五言律诗","c":["邗水云初散，芜城目暂舒。","江山通楚越，风俗重盐鱼。","董相崇祠在，昭明旧阁馀。","古来繁盛地，歌舞近何如。"]},{"t":"秋日同金孝廉钟越游新城汪园五首 其一","f":"五言律诗","c":["肩舆出近郭，引缆赴遥岑。","兴发淩虚棹，心清浴水禽。","岸沙疏雨润，村路白云深。","未览林园胜，晴郊已散襟。"]},{"t":"秋日同金孝廉钟越游新城汪园五首 其二","f":"五言律诗","c":["舍舟登彼岸，策杖踏秋原。","苔滑欹桥路，云生古寺门。","溪山娱老性，尊斝就名园。","持此幽偏意，应同静者论。"]},{"t":"秋日同金孝廉钟越游新城汪园五首 其三","f":"五言律诗","c":["入门披竹露，觅胜信芒鞋。","瑶草潜幽涧，山花坠古厓。","烟霞如有待，樵牧且相偕。","眷恋林泉好，经过每畅怀。"]},{"t":"秋日同金孝廉钟越游新城汪园五首 其四","f":"五言律诗","c":["飞阁淩霄起，登临入望宽。","江声流槛外，山色扑檐端。","时序清秋晚，风霜白日寒。","东西连楚越，乘兴一凭栏。"]},{"t":"秋日同金孝廉钟越游新城汪园五首 其五","f":"五言律诗","c":["景物探幽邃，风光解送迎。","林峦多变态，登眺屡移情。","南北身无定，欢娱感易生。","名山何处卜，归老遂躬耕。"]},{"t":"冬夜听沈江门弹琴","f":"五言律诗","c":["满座容皆肃，希声入耳清。","片云江上白，孤月夜深明。","沧海神龙跃，空山老鹤鸣。","知君弦指外，怀古有馀情。"]},{"t":"听琴","f":"五言律诗","c":["风定寒梅发，幽香小室融。","虚窗弹古调，明月照枯桐。","山静泉流细，天高鹤唳空。","曲终群籁寂，心境接洪濛。"]},{"t":"听沈江门鼓琴步棕亭韵","f":"五言律诗","c":["孤云归远岫，群鸟入寒林。","天宇澄秋水，江门鼓素琴。","虚斋人尽后，明月夜方深。","默坐心如洗，听君弦上音。"]},{"t":"送棕亭公车北上","f":"五言律诗","c":["到去南宫捷，君才自不难。","文章期大用，风雨隔交欢。","行李残书重，绨袍朔雪寒。","故人唯念此，蚤晚报平安。"]},{"t":"丙子岁暮得王进士简泉书却寄 其一","f":"五言律诗","c":["淞泖声名久，金阊邂逅新。","维舟方缱绻，分手忽逡巡。","湖海千秋业，荣枯百岁身。","广搜同大厦，古调愧阳春。"]},{"t":"丙子岁暮得王进士简泉书却寄 其二","f":"五言律诗","c":["斯文欣契合，时序感推迁。","不朽期今日，论交罄百年。","众流趋下壑，孤岳耸高天。","大业非知己，难将此意传。"]},{"t":"听弹塞上鸿曲","f":"五言律诗","c":["一鼓塞鸿音，关山雨雪深。","淩云飞乍起，倾耳韵还沈。","远戍中宵泪，孤臣万里心。","听君无尽意，感我欲沾襟。"]},{"t":"听弹秋江夜泊","f":"五言律诗","c":["秋气森庭户，江声沸几筵。","何人舟夜泊，沈子坐操弦。","孤雁鸣沙岸，哀猿吊岭烟。","归心千里外，听罢泪潸然。"]},{"t":"听弹沧海龙吟","f":"五言律诗","c":["空斋调雁柱，沧海听龙吟。","弦指风雷聚，波涛栋宇深。","扬鬐声裂石，坐客昼惊心。","渐觉音和缓，春膏沛远林。"]},{"t":"听弹水仙操","f":"五言律诗","c":["希音今绝响，古乐独安弦。","浊俗谁同调，孤鸣忆水仙。","空江招白鹤，远峤迓成连。","如共幽人语，灵槎舣日边。"]},{"t":"题观察卢同年雅雨平山高会图","f":"五言律诗","c":["欲变繁华俗，将成弦诵区。","平山开盛会，都转是名儒。","士萃东南秀，诗标主客图。","流传千载后，真不愧欧苏。"]},{"t":"九月四日钱少司寇舟抵维扬同年卢都转雅雨放艇真州邀余往会至即同饮官斋更期九日平山堂登高二首 其一","f":"五言律诗","c":["旌节来长水，扁舟发夜分。","官斋同宴饮，天象动星文。","深涧流甘乳，高松养白云。","久邀贤地主，相待共清氛。"]},{"t":"九月四日钱少司寇舟抵维扬同年卢都转雅雨放艇真州邀余往会至即同饮官斋更期九日平山堂登高二首 其二","f":"五言律诗","c":["忆弭嘉禾棹，曾登乐顺堂。","别来霜再白，相见菊初黄。","诗思增奇崄，交情笃老苍。","欲窥千顷度，终愧隔微茫。"]},{"t":"送钱司寇香树还长水","f":"五言律诗","c":["年老怀知己，相逢每恨迟。","可堪衰飒候，又是别离时。","烟雨楼头月，銮江渡口诗。","美人隔秋水，无计慰相思。"]},{"t":"元日书怀","f":"七言律诗","c":["西溪空有梅千树，却向辽东久索居。","万里关山苏武梦，一床冰雪管宁庐。","乡心未释庭闱望，逝水空嗟岁月虚。","樽俎相看人尽醉，龙荒风景独愁予。"]},{"t":"艾抡元招康东侯叶圣嘉魏文壁艾明德车宜年诗集余远归闻赴同用雄字","f":"七言律诗","c":["闻说诗坛树帜雄，征尘初拂过邻东。","到来执简非安道，座上披襟是孔融。","大麓寒英飘白雪，梅花古韵出焦桐。","相欢桦烛应嫌短，遮莫天街丙夜风。"]},{"t":"送富氏姊随夫闽南","f":"七言律诗","c":["风裂蓬窗雪暗吹，残灯相对各含悲。","正当朔漠饥寒日，况是冰霜离别时。","万里关山从此去，百年骨肉会无期。","惊魂顷刻同杯酒，又听天街夜漏移。"]},{"t":"送车宜年乡试","f":"七言律诗","c":["年来辛苦共磋磨，咫尺高斋早暮过。","贤圣心传悬日月，文章气势走江河。","扶摇鹏翮清秋健，烂缦琪花上苑多。","不患明时嗟不遇，寒窗夙愿定如何。"]},{"t":"接闽南富氏姊书载饥寒甚迫感赋二章 其一","f":"七言律诗","c":["一缄经岁抵荒陲，惊定将开喜复疑。","万里身孤艰苦日，十年音断别离时。","繁言不尽思亲泪，展读如闻觌面悲。","极目南天空浩叹，角声哀咽朔风吹。"]},{"t":"接闽南富氏姊书载饥寒甚迫感赋二章 其二","f":"七言律诗","c":["万里萧条别塞关，十年魂梦绕烟峦。","雁回北地肠应断，书望南天泪未乾。","闽徼饥寒空我报，边荒衣食胜君难。","行间斑剥啼痕满，不忍临风再展看。"]},{"t":"都门秋","f":"七言律诗","c":["经年迢递阻关梁，节物惊心倍感伤。","远戍霜摧枫岭赤，野塘风起雁沙黄。","笔佣千里音书少，梦返三更道路长。","此日知亲忧子切，白头朝夕倚闾望。"]},{"t":"西征闻捷三章 其一","f":"七言律诗","c":["鲁夷衅鼓寇边陲，帝子分符过月支。","万里转输天地迥，十年征伐羽书迟。","元戎初奏疆场绩，丹陛欣瞻拜舞仪。","独念渠魁犹未馘，将军何日议班师。"]},{"t":"西征闻捷三章 其二","f":"七言律诗","c":["弹丸负固狎天威，新破乌斯捷羽飞。","荒服舆图收圣版，中原戎马耀神机。","乾坤且未销金鼓，将士还应卧铁衣。","只恐九重忧正切，筹边何以静边归。"]},{"t":"西征闻捷三章 其三","f":"七言律诗","c":["庙堂喜溢下纶音，草野偏多虑远心。","鬼啸沙场边月冷，马嘶阵鼓塞云深。","乘威急绝豺狼衅，捣窟还防出没阴。","赫怒己加应奏凯，虞廷干羽舞森森。"]},{"t":"生日书怀","f":"七言律诗","c":["一朝纶命出彤墀，襁褓随亲徙北陲。","有识但悲风土异，无才甘弃盛明时。","白头堂上思乡切，彩服阶前怯岁迟。","惭愧贤书空蚤窃，桑弧蓬矢怅虚施。"]},{"t":"塞外战场","f":"七言律诗","c":["万里龙沙古战场，荒台残垒望苍苍。","雪中衰草连天白，塞上愁云匝地黄。","孤剑临风怀往事，中原回首隔斜阳。","可怜多少英雄血，化作丹林一夜霜。"]},{"t":"宿北塔堡","f":"七言律诗","c":["结靷冲寒落日微，昔年烟火望全非。","空林鸟雀饥啼急，荒碛牛羊晚下稀。","投宿问年心欲折，探囊呼酒兴还违。","中宵展转愁难寐，飒飒风声浩雪飞。"]},{"t":"边城秋感九首 其一","f":"七言律诗","c":["一夕西风起大荒，萧条景物别殊方。","三韩戍北征鸿急，五国城南塞草黄。","华表不归丁令鹤，闾山空寄管宁床。","几声羌笛连云发，杳杳哀音断客肠。"]},{"t":"边城秋感九首 其二","f":"七言律诗","c":["兴王将相奋雄图，此处曾经裂虎符。","江走乌龙穿紫塞，山开长白障留都。","遐方貂贝归朝觐，盛世恩膏及朽枯。","大地重熙歌乐土，故乡风景忆西湖。"]},{"t":"边城秋感九首 其三","f":"七言律诗","c":["心随归雁颉云翔，晓日关山望帝乡。","忆昔凤池瞻德化，正当龙塞靖妖芒。","襄平鸡犬新丰社，渤海楼船旧战场。","羡尔居民安故土，尽销兵甲课农桑。"]},{"t":"边城秋感九首 其四","f":"七言律诗","c":["辽海西陵道路长，提封万里隔严疆。","百年芳草迷归梦，几处寒砧动早霜。","云压秦关山叠叠，风驱胡燕海茫茫。","生还有愿何时遂，沈水西流昼夜忙。"]},{"t":"边城秋感九首 其五","f":"七言律诗","c":["愁绝长因蜡炬消，江南塞北集寒宵。","庭闱头白乌难白，拜扫人凋墓亦凋。","泉石心惭绮里季，功名身愧霍嫖姚。","请看月落天将曙，犹向酸风泣泬寥。"]},{"t":"边城秋感九首 其六","f":"七言律诗","c":["霜清水落海天空，莽莽云山夕照中。","故国音书凭旅雁，穷途踪迹类飘蓬。","黄龙紫塞身长客，越水吴山路不通。","指点真番临浿郡，古来征戍苦辽东。"]},{"t":"边城秋感九首 其七","f":"七言律诗","c":["风雪连宵走百灵，将军猎队出郊坰。","呼鹰马去冲云起，射虎人归带血腥。","刘向有才虚对策，儿宽无遇但横经。","顿思投笔从戎伍，破虏功成早勒铭。"]},{"t":"边城秋感九首 其八","f":"七言律诗","c":["戍楼冈势郁岧峣，暂一登临破寂寥。","玄兔群峰环碧海，白狼高浪蹴青霄。","朝鲜东走诸番近，督亢西连斥堠遥。","身在异乡归未得，故园松柏亦全凋。"]},{"t":"边城秋感九首 其九","f":"七言律诗","c":["死生契阔数何奇，南北东西系所思。","失主精魂同落寞，丧家骨肉久乖离。","那堪羸病羁愁客，又值严风酷雪时。","怅望穹苍搔首问，茫茫消息总难知。"]},{"t":"入都会试途中作","f":"七言律诗","c":["辽海悲风接帝京，公车西指泪纵横。","饥寒正痛亲双老，冰雪何堪子独行。","回望白云连塞远，愁听乌鸟向人鸣。","为求禄养轻离膝，魂梦长悬捧檄情。"]},{"t":"赴试答蔡宗鲁","f":"七言律诗","c":["立身岂必定荣华，计乏娱亲愿渐奢。","养志实无田可力，望云空有梦还家。","公车夜渡辽河雪，细雨春开上苑花。","顾我与君同出处，时清休种邵平瓜。"]},{"t":"入山海关感赋","f":"七言律诗","c":["万里涂膏筑怨年，讵知二世祚随迁。","界分天地华夷限，计并山河日月绵。","堠吏千秋仍守钥，戍兵此日正防边。","风尘寂寞驱车入，望里閒愁起暮烟。"]},{"t":"辛丑会试题礼闱号壁","f":"七言律诗","c":["迂儒只合掩荆扉，何事频年苦棘围。","入世已知经历浅，服官还觉性情非。","每伤边塞庭闱老，却虑君臣遇合违。","早使鹿车归故里，临溪数亩伴渔矶。"]},{"t":"徐秦二孝廉与余同客南泉寺既去简邀小酌","f":"七言律诗","c":["塞客同来重作客，客中萧索复分离。","须知孤馆深愁处，正忆三人共话时。","爱我定思河朔饮，为君早置建康卮。","莫因怯暑迟云履，点检风尘更有谁。"]},{"t":"赠田隐居","f":"七言律诗","c":["放眼乾坤一笑看，钦君高致隐烟峦。","功名亲老予难已，出处身轻尔自宽。","水浸碧天孤月皎，山悬飞瀑落云寒。","狂吟散发无拘束，不信人间行路难。"]},{"t":"七夕咏牛女","f":"七言律诗","c":["经年此夕慰相思，徙倚天街漏渐移。","欢会明看银汉接，深情偏渡鹊桥迟。","应知顷刻相逢处，便是离魂欲断时。","旧恨新愁和夜永，人间且谩说佳期。"]},{"t":"哭徐五孝廉天柱","f":"七言律诗","c":["百年怀抱竟何成，仓卒羁魂恨未平。","客里一棺凭友葬，边荒八口仗谁生。","义当身任无他诿，泪为家贫暗自倾。","杯酒酹君君有识，九泉应鉴故人情。"]},{"t":"九日旅情","f":"七言律诗","c":["秋深景物尽萧条，此日登临兴岂豪。","风捲黄沙连野阔，鹰抟紫塞振云高。","闭门不落儒生帽，怀土愁沾客子袍。","独对茱萸频自酌，醉横孤剑读离骚。"]},{"t":"留馆京师","f":"七言律诗","c":["挟策艰难献帝阍，冀邀升斗赡朝昏。","那堪孤客天涯境，尽是双亲梦里魂。","刺眼寒花三次发，惊心白露九秋繁。","望乡时倚庭前树，冷雁哀笳满蓟门。"]},{"t":"旅情","f":"七言律诗","c":["高原原上暮横烟，辽海燕山路几千。","霜介树头催落叶，衣寒天畔未装绵。","砌蛩凄语深更月，风□寒敲欲曙天。","展转寸心摧已折，秋来终夜不成眠。"]},{"t":"病中秋夜梦归","f":"七言律诗","c":["衰草离披白露凉，草根蟋蟀近匡床。","支颐恍惚闻残□，欹枕迢遥到故乡。","悴貌入庐惊弟妹，高堂挥泪诘行藏。","一声梦断南归雁，月照寒窗秋夜长。"]},{"t":"接闽南富氏姊书","f":"七言律诗","c":["万水千山信使稀，书传艰苦到边迟。","谩言绝粒真难拯，即便多金岂易赍。","目断武夷云起处，魂迷沙漠月沈时。","两乡怅望乾坤末，泪洒悲风总未知。"]},{"t":"酬屈北雄","f":"七言律诗","c":["百年超识慕樵渔，牢落长随万卷书。","震世声名归艺苑，出尘踪迹寄僧庐。","黄沙蔽目燕山道，白草连天塞上居。","潦倒逢君应一醉，高楼呼酒雨晴初。"]},{"t":"代门人赵玉送前师夏晴江归里","f":"七言律诗","c":["久钦道范甫追随，旋送文旌出凤池。","易水沙清霜落后，燕台风急雁来时。","暮云遥忆孤村暝，晓露寒思匹马迟。","立雪心依归路杳，前途应见别离诗。"]},{"t":"秋日登通州城楼","f":"七言律诗","c":["高城吹角满江楼，楼上登临动客愁。","陵谷参差随去鸟，河山迢递任归舟。","凋零书剑谁青眼，缥缈乡关忆白头。","极目那堪风景暮，云峰天外写高秋。"]},{"t":"雨后复登通州城楼","f":"七言律诗","c":["放眼城端万里分，雨馀苍翠涤尘氛。","霞飞峻岭晴烧石，天入澄波净浴云。","野树远连山色暝，清砧凄杂雁声闻。","蹉跎岁月成何事，空使归心望里殷。"]},{"t":"初秋郊望","f":"七言律诗","c":["西风吹雨过燕城，茂草芳丛踏已平。","介树严霜看未落，穿云归雁听无声。","碎琴久绝王门操，归梦长牵故国情。","此日高堂闻画角，遥知清泪为儿倾。"]},{"t":"螴蜳","f":"七言律诗","c":["螴蜳心境日悬空，臧谷亡羊事总同。","书带草摧连夜雨，洛如花死一秋风。","屠龙有技虚成巧，澼絖微长亦建功。","翘首西溪明月下，芰荷衣对绿蓑翁。"]},{"t":"秋日与友人分得时字","f":"七言律诗","c":["紫陌商飙扑面吹，天涯王粲倚楼悲。","凤城景物凋零日，龙塞冰霜酷烈时。","望子老亲情正切，傍人孤客梦空驰。","填胸羁绪何能遣，慷慨留君且赋诗。"]},{"t":"中秋望月","f":"古风","c":["月碾高天万象开，寒光清夜逼人来。","金盘玉露凝仙掌，沧海明珠结蚌胎。","顾兔养年空想像，嫦娥窃药久疑猜。","聊凭瓜果倾?醁，一任乾坤有劫灰。"]},{"t":"蛩","f":"七言律诗","c":["薜萝窗下命如丝，翼鼓寒音字字悲。","花影扶疏风静夜，砧声断续月明时。","惊心顿觉宜归早，絮语如闻说岁迟。","潦倒羁人愁不寐，斗疑霜雪鬓边垂。"]},{"t":"岁暮馆阿员外宅","f":"七言律诗","c":["纸田墨稼稔收难，时序催人岁复残。","压塞冻云含雪暗，失林孤雀堕风寒。","马融旧拥笙歌帐，薛令长吟苜蓿盘。","惭愧程门曾立雪，长安落魄笑儒冠。"]},{"t":"秋日与姜孝廉华圃赋感怀诗得鹂字","f":"七言律诗","c":["凤城风鼓夜声悲，此日鸡栖无尽思。","豺祭空山驱虎豹，珠潜沧海抱龙螭。","金丸弹雀己轻用，腐鼠惊鹓却太疑。","乡国但能归款段，双柑斗酒听黄鹂。"]},{"t":"都门立春","f":"七言律诗","c":["春日膏车逐塞尘，淹留京国复逢春。","惊看凤历开新岁，愁忆龙沙惜别辰。","树剪繁花虚焕彩，盘陈杂馔总成辛。","和风未布冰霜满，回首魂消潞水滨。"]},{"t":"留京教习","f":"七言律诗","c":["敢云才识出人群，羁滞愁心空自焚。","春色晓瞻天路迥，钟声遥隔帝城闻。","嗣宗谩洒穷途泪，贾谊能传治世文。","家望扶桑归路远，碧霄遮断海东云。"]},{"t":"春日书怀","f":"七言律诗","c":["捧檄卢江空有愿，一身京国怅閒留。","彩衣未遂阶前舞，白发重增塞上愁。","碧草何心荣客径，黄莺底事唤晴洲。","百年马首终无角，出处频伤岁月流。"]},{"t":"春晴郊望怀诸兄弟","f":"七言律诗","c":["碧霄云净树无烟，此日相思倍黯然。","好鸟有情皆唤侣，雄边不尽远连天。","排江画鹢催潮急，背郭哀笳向晚偏。","兄弟他乡如我问，生涯犹拥旧青毡。"]},{"t":"寄怀艾明德","f":"七言律诗","c":["蜗角深惭拔十名，长安旅食寄浮生。","曲成流水谁新赏，诗和寒窗忆旧盟。","日落暮云横远塞，春来朝雨暗边城。","何时归去重携手，点检清樽对月明。"]},{"t":"寄蔡宗鲁","f":"七言律诗","c":["衡门咫尺隔微波，乘兴朝来暮复过。","花觅深春诗句富，坐邀明月酒杯多。","别来佳会谁重续，想到同心欲浩歌。","我已风尘增旅困，故人消息近如何。"]},{"t":"巢大司寇书斋畅观名画索题长句","f":"七言律诗","c":["麻姑仙驭出昆崙，海上方蓬海市吞。","苍狗吠来天入梦，素娥奔去月消魂。","筳篿虽设灵氛远，椒醑空陈帝阙尊。","一自瑶池巡幸后，祇今飘泊有龙孙。"]},{"t":"重访范兰亭喜晤即同泛舟得天字","f":"七言律诗","c":["片帆曾访暮秋天，采药游踪去未还。","久步园林看竹罢，犹瞻云鹤向河边。","迷茫归棹愁中境，忽谩同舟梦里仙。","已判疏狂留信宿，平分风月入诗篇。"]},{"t":"秋日偕诸友人舟中望月得更字","f":"七言律诗","c":["天光水色两澄清，孤月含秋傍艇生。","逐浪千寻无定影，悬空中夜为谁明。","烟波不尽诗人意，云树偏多故国情。","画角又吹黄叶落，可堪千里咏残更。"]},{"t":"秋日寄怀叶圣嘉","f":"七言律诗","c":["一夜枝头玉露浓，晓看花柳作秋容。","自伤燕市红尘客，空羡缑山白鹤峰。","张敏梦迷高惠路，退之云附孟郊龙。","寸心直可同千古，为忆君为岁暮松。"]},{"t":"范兰亭索赠限梅岑送潘问奇原韵 其一","f":"七言律诗","c":["遐霄有愿畏摧颓，蛮触虚名却早灰。","花径只容明月到，松关唯见白云来。","误人圭组看笼鸟，避地衣冠傍钓台。","闻得罗浮寻旧约，不知亲折几枝梅。"]},{"t":"范兰亭索赠限梅岑送潘问奇原韵 其二","f":"七言律诗","c":["林园寂历绕烟洲，岸帻披襟出世求。","苍竹吟风栖老鹤，玉箫吹月下高楼。","人间谁是青云侣，天上空怀紫府游。","自我溪山乘逸兴，应抛丹鼎共渔舟。"]},{"t":"范兰亭索赠限梅岑送潘问奇原韵 其三","f":"七言律诗","c":["临流背郭结精庐，十顷良田及雨锄。","晓簟侵云无俗梦，夜杯入馔有佳鱼。","香风石鼎烹梅蕊，明月蕉窗读道书。","何事閒中不可乐，一邱一壑尽扶舆。"]},{"t":"范兰亭索赠限梅岑送潘问奇原韵 其四","f":"七言律诗","c":["纳纳乾坤任尔狂，搜罗今古入奚囊。","千峰翠涤三秋雨，孤鹤长鸣万仞冈。","乍听霓裳歌月殿，忽惊沧海走风樯。","纵横六合谁同调，杯酒多君许细商。"]},{"t":"范兰亭索赠限梅岑送潘问奇原韵 其五","f":"七言律诗","c":["堂堂祖烈旧知名，海立分符各讨征。","三楚寇招宗泽骑，八闽星堕武侯营。","功垂竹帛身堪祀，忠在乾坤死亦生。","纂述前徽凭杰士，如君端不堕家声。"]},{"t":"范兰亭索赠限梅岑送潘问奇原韵 其六","f":"七言律诗","c":["龙沙万里隔烟云，地北天南望不分。","乌未白头悲二老，魂招紫塞哭孤坟。","哀笳背日吹荒戍，野马迷空战夕曛。","谁可开诚倾肺腑，风尘历尽喜逢君。"]},{"t":"九日饮同年何公南书斋","f":"七言律诗","c":["严风驱雁尽南飞，枯坐萧斋怅落晖。","凤阙恩沾桑落赐，龙山兴与菊花违。","难期地缩壶公杖，却忆尊开靖节扉。","深荷主人情缱绻，天涯欢笑亦如归。"]},{"t":"赠无厓上人","f":"七言律诗","c":["不忍慈眸见世人，烟霞深处寄閒身。","崖悬飞瀑惊风雨，月落深潭聚鬼神。","一指臞禅来鹤听，六时枯偈有云亲。","避人踪迹应如此，飘泊深惭席上珍。"]},{"t":"送杨澍三之粤东 其一","f":"七言律诗","c":["腐烂文章仗琢磨，饥驱万里逐风波。","长安亲见知交少，南粤还愁瘴疠多。","家返钱塘身又去，书传梅岭雁难过。","却伤无计留琴剑，挥泪离亭一浩歌。"]},{"t":"送杨澍三之粤东 其二","f":"七言律诗","c":["新州竻竹有荒城，一夕西风吊古情。","旧址沙沈文献宅，高标苔没马援名。","天涯亭上征鸿断，梦觉关头夜月明。","回首那堪家万里，思君祇此亦魂惊。"]},{"t":"甲辰元日纪事","f":"七言律诗","c":["正苦寒风吹欲死，忽惊阛阓祝融驰。","谩誇席夺谈经日，却忆霖垂噀酒时。","谏爵谁当开白兽，恩纶曾遍锡丹墀。","临轩彩笔如相授，不献椒花灿丽词。"]},{"t":"送康东侯门人高宏同赴乡试","f":"七言律诗","c":["雨后天高道路清，征车西指趁新晴。","金台骥过风生鬣，桂殿花开月有情。","一榜云龙标杰士，双辉珠玉竞芳名。","南宫再捷应簪笔，莫但随班听漏鸣。"]},{"t":"秋日寄怀都门友人","f":"七言律诗","c":["高斋花暖夜归迟，几日长安对酒时。","别梦尚迷芳草绿，征鸿忽背晓烟驰。","燕山雨过金台暮，辽海云深画角悲。","两地秋风人不见，几回珍重寄来诗。"]},{"t":"雨后简叶圣嘉","f":"七言律诗","c":["玄兔城头夜雨过，黄龙冈下水增波。","离披塞草纡行径，咫尺仙舆缈绛河。","叫露寒螀孤月白，惊霜征雁北风多。","重阳沽酒登高处，我欲题诗藉薜萝。"]},{"t":"叶圣嘉许九日倾囊沽酒届期不果诗以嘲之","f":"七言律诗","c":["风捲黄云浪捲沙，风晴浪息起边笳。","奚囊久废寻山句，篱菊偏开索酒花。","自许携尊倾箧笥，虚疑遣使报烟霞。","踟蹰令节终难负，斟酌旗亭傍晚赊。"]},{"t":"步马秀才原韵赠徐叶张王四子 其一","f":"七言律诗","c":["四君丰格旧同俦，才子瑶篇扫壁留。","笔挟风云腾彩凤，槎回星汉忆牵牛。","岩间苍鼠穿松过，石上寒泉带月流。","我暇欲追诸子胜，丹峰翠巘一囊收。"]},{"t":"步马秀才原韵赠徐叶张王四子 其二","f":"七言律诗","c":["云鸿海鹤忆同俦，胜事空悲去不留。","久慑风涛甘守兔，每思圭组鉴牺牛。","盍簪盛友皆名辈，扛鼎雄才绝俗流。","欲吐胸怀谋一醉，黄龙冈上雨初收。"]},{"t":"哭坦居五弟 其一","f":"七言律诗","c":["百年空有事功期，和叶埙篪不竟吹。","鵩赋长沙终作祟，刀无王览更谁遗。","峥嵘气向丹霄尽，迢递魂归故国迟。","书閟石函何日启，一生怀抱独兄知。"]},{"t":"哭坦居五弟 其二","f":"七言律诗","c":["穷边犹幸得团圆，几载微名各一天。","京国人深遥别恨，衡门相聚未盈年。","箦移仓卒疑难释，医视分明病己痊。","冥默穹苍高莫问，空挥热泪朔风前。"]},{"t":"哭坦居五弟 其三","f":"七言律诗","c":["如君真是克家郎，静念平生事可伤。","雁塞穷愁羁骨肉，鸡窗健志敌冰霜。","市燕骐骥宜高价，瑞国鸾凰竟不翔。","自是衰微兴尚早，斯人空作一门祥。"]},{"t":"哭坦居五弟 其四","f":"七言律诗","c":["双亲垂白隶真番，艰苦襟怀讵可言。","砥砺正期成国士，文章端可大寒门。","一朝玉树埋荒草，终古黄沙吊旅魂。","摊卷伤心孤烛夜，芸窗铁砚复谁论。"]},{"t":"哭坦居五弟 其五","f":"七言律诗","c":["三十才过命已隳，天生大器竟何为。","谁咨孔坦临终略，不愧曾参启足时。","野寺一棺荒荠合，破篱三径夜乌悲。","何堪把臂论文地，衰草寒花寂寞滋。"]},{"t":"哭坦居五弟 其六","f":"七言律诗","c":["荆树庭前叶正森，忽惊风雨折浓阴。","望云应堕思亲泪，残卷空馀教子心。","一室孤灯寒欲烬，数声哀雁月初沈。","知君魂魄时来往，风雨灵旗每夜深。"]},{"t":"将赴河间教授任奠别五亡弟高","f":"七言律诗","c":["死后经营恨未申，间关千里逐风尘。","情同毛义膺徵檄，事异王尊叱御轮。","樽酒倘知来一奠，泉台应起问双亲。","显扬柩下孤儿望，黄卷青灯代尔身。"]},{"t":"雨后由保定县放舟抵省","f":"七言律诗","c":["雨歇风微雁阵斜，扬舲击汰荡晴沙。","波光白捲千寻日，山色红烧一片霞。","过眼云峰奔岸树，近村烟火失渔家。","旗亭前路堪沽酒，暂一停桡问杏花。"]},{"t":"赠同年吴学使七云 其一","f":"七言律诗","c":["文章髫龀压临城，仙籍芳名震玉京。","潜邸儒臣周睿简，飞龙天敕授文衡。","心倾殿陛葵同赤，日辨珉矼鉴逊明。","荒署寒毡沾化育，泰山北斗望峥嵘。"]},{"t":"赠同年吴学使七云 其二","f":"七言律诗","c":["忆昔同攀月桂枝，金山玉海识丰仪。","大鹏奋翮淩霄劲，孤雀翔风接翅迟。","养志莫酬甘旨愿，怀亲空诵蓼莪诗。","青云已作帡幪覆，锡类应捐紫陌悲。"]},{"t":"赠河南兵备道署臬司朱某","f":"七言律诗","c":["大梁廉宪握军机，皂盖朱幢奖德辉。","才赡雄韬销壁垒，身膺殊渥彻□帏。","扬威万□貔貅励，恤法三章狴犴稀。","吏治兵储归赤腹，彝尊象勺锡黄扉。"]},{"t":"教授顺天府 其一","f":"七言律诗","c":["谩道嵇康七不堪，偶因稽古服微官。","宦情莫敌烟霞癖，儒味聊甘苜蓿盘。","一代勋猷归鼎鼐，千秋书策属单寒。","閒开讲席临轩坐，已见熏风长蕙兰。"]},{"t":"教授顺天府 其二","f":"七言律诗","c":["侯门幸不曳长裾，数仞宫墙寄广居。","敢诩圣贤真事业，免教陇亩自耰锄。","庭无一事曾挠性，天假閒身且著书。","西麓烟霞春正好，冠童携手乐公馀。"]},{"t":"哭陈进士宪图 其一","f":"七言律诗","c":["眼底如君铁石人，谁能相赏出风尘。","炊烟屡绝才偏富，瘦骨孤撑语不贫。","佛火夜寒悲自咏，旅情春剧苦同申。","琅玕赠我留君泪，每一吟哦一怆神。"]},{"t":"哭陈进士宪图 其二","f":"七言律诗","c":["从古英雄遇合难，每凭健笔发长叹。","遗编蒙土将谁赏，洒泪开函独我看。","花径宛然词客杳，松窗无恙酒杯寒。","生刍奠罢携僧别，惆怅斜阳下远滩。"]},{"t":"哭陈进士宪图 其三","f":"七言律诗","c":["十年科甲老閒身，万里艰难应诏臣。","深痛玉楼徵记日，正为乡国梦归人。","恩雠满匣留金剑，侠烈孤魂质鬼神。","简练阴符终未试，应教杰士泪沾巾。"]},{"t":"哭陈进士宪图 其四","f":"七言律诗","c":["有才无命复何言，赍志重泉死亦冤。","旅榇暂依乡衲寺，客骸谁返故园魂。","箕裘有子空瞻望，苫块无亲奠晓昏。","最是伤心凭吊客，清晨乌雀夜深猿。"]},{"t":"哭陈进士宪图 其五","f":"七言律诗","c":["避俗荒斋寄索居，傍人饥饱任粗疏。","佛灯光照朝磨剑，梵语声淆夜读书。","一榻臞禅僧自在，满窗明月客非初。","诗人死后魂难瞑，定把烦冤问太虚。"]},{"t":"哭陈进士宪图 其六","f":"七言律诗","c":["屈指交游更几人，滇南塞北独相亲。","荣名苦励英雄志，衰病先摧逆旅身。","寡和焦桐音歇绝，多愁诗句字酸辛。","文坛从此谁同调，欲捡残编化作尘。"]},{"t":"哭陈进士宪图 其七","f":"七言律诗","c":["净地依然竹覆池，老僧相见犬相随。","石傍细路敲诗处，花外高轩对酒时。","鸿雁带霜归瞑漠，神雅背日泣寒枝。","思君景物皆堪泪，翘首滇南恐未知。"]},{"t":"哭陈进士宪图 其八","f":"古风","c":["远客饥寒病复牵，况当杯酒恣流连。","魂归燕塞霜初落，书寄滇南雁始还。","殓具敛来朋友泪，灵舆归冀子孙贤。","人生?帙终虽解，珍摄浑疑未尽年。"]},{"t":"老虎洞寻张某昼晦失路堕荆棘中野宿达旦见张治酒慰劳因述其事","f":"七言律诗","c":["阴云万顷大荒屯，失路无从可问津。","月黑豺狼饥猎兽，山深魑魅夜呼人。","朝暾隐显寻烟火，古道微茫历莽榛。","相顾主人成一笑，招魂何惜酒杯频。"]},{"t":"樱桃沟","f":"古风","c":["山前山后云峰立，草笠芒鞋此一经。","怪石狰狞蹲虎豹，急湍高下斗雷霆。","攀藤路古缘纤末，斜日烟深入杳冥。","携手?砑时一啸，野鸥惊起落沙汀。"]},{"t":"九日题来青轩","f":"七言律诗","c":["来青缥缈起山阿，连袂跻攀恣啸歌。","众壑高从檐外落，千峰低向槛前过。","渔梁樵径烟霞古，翠石苍松岁月多。","自昔龙山传落帽，不知风景竟如何。"]},{"t":"灯花和同年子钱东麓因呈香树学使","f":"七言律诗","c":["螭膏凤脑结根芽，色相天然吐异花。","烈焰腾时偏磊落，丹心倾处自光华。","应怜破牖凋红蕊，著意春风护绛纱。","照我夜吟辛苦后，好同江管竞奇葩。"]},{"t":"赠颜维聪 其一","f":"七言律诗","c":["托迹宫墙别有天，花酣月满独流连。","庭萦草径随云遇，阶列松阴让鹤眠。","避俗閒情亲冷署，碎琴孤韵欲安弦。","姱修万古薪传在，欲问心斋坐忘年。"]},{"t":"赠颜维聪 其二","f":"七言律诗","c":["陋巷尼山旧德邻，飘零书剑走风尘。","传家法物箪瓢在，负郭先畴井洫沦。","燕市只今潜郭隗，荆湘何处访春申。","宫墙且共谈颜乐，云净高天月满轮。"]},{"t":"九日与邢卓哉毛秋岑用杜少陵宴蓝田庄韵 其一","f":"七言律诗","c":["放怀天地觉增宽，酒社文坛几度欢。","云里霜声排雁字，檐前秋色上鸡冠。","龙山雅会人俱往，蓝水空传句不寒。","此日登临存我辈，应将今古幻中看。"]},{"t":"九日与邢卓哉毛秋岑用杜少陵宴蓝田庄韵 其二","f":"七言律诗","c":["翠竹黄花野外宽，篱边溪畔各追欢。","苍髯得句狂呼酒，玉树临风醉不冠。","霜叶满林秋灿烂，丹峰横汉气高寒。","天空缥缈楼千尺，乘兴登临一笑看。"]},{"t":"种竹","f":"七言律诗","c":["邻园修竹许我移，冒雨栽傍书斋宜。","径扫古烟秋黯淡，窗横疏影宵参差。","淩云老干势矫矫，抱节新箭枝离离。","何须结实待鸾凤，已觉霜雪非能欺。"]},{"t":"刘园看牡丹同用真字","f":"七言律诗","c":["名园选胜结芳邻，取次看春及暮春。","拟搆新诗酬国色，争浇浊酒奠花神。","云来深竹庭逾静，客到忘机鸟亦驯。","政暇不妨频出郭，招携童叟话天真。"]},{"t":"送毛秋岑去后次日作","f":"七言律诗","c":["槐荫阴阴覆索居，泉声㶁㶁溜空除。","论心昨日尊仍在，握手今朝事已虚。","江冷丹枫人去远，月明孤馆雁来初。","思君驴背秋风里，定为羁愁一念予。"]},{"t":"雪后简卢公亮","f":"七言律诗","c":["朔风吹雪遍河干，启户银花入望宽。","官阁吟梅惭水部，洛阳卧病类袁安。","远峰积素明斜照，饥鸟群飞噪夕寒。","命棹无劳剡溪去，山阴咫尺兴何阑。"]},{"t":"示女尼性魁","f":"七言律诗","c":["剃度离家自弱年，归空犹有发堪怜。","数茎香髻抛残业，一点芳心入静缘。","夜叩寒钟霜月下，晓闻清梵露鸡先。","长将宝镜悬胸臆，洗净铅华不坐禅。"]},{"t":"春郊","f":"七言律诗","c":["晴郊缓步草芊绵，背石临流设小筵。","媚耳莺声新出谷，娇春柳色细垂烟。","已知吾道人情远，且喜芳尊野兴便。","如意醉歌如意舞，和风相送入茅檐。"]},{"t":"酒徒","f":"七言律诗","c":["共笑真儒是腐儒，英奇自昔困屠沽。","学谈洙泗薪传鲜，剑说丰城侠气孤。","险阻久经身跮踱，风尘数被鬼揶揄。","不须进退嗟维谷，兴在高阳一酒徒。"]},{"t":"月中桂","f":"七言律诗","c":["不老灵根月窟蟠，岂同凡卉有凋残。","嫦娥缬佩生仙界，顾兔和丸寿广寒。","衰盛每随圆缺转，荣枯应向晦明看。","偏于玉露金风后，万古香飘碧落端。"]},{"t":"寿山东巡抚朱同年母程太夫人八秩初度","f":"七言律诗","c":["金山玉海旧家声，旌节遥临政治平。","东海洋洋齐大国，菁莪蔼蔼鲁诸生。","丰功共道如公肃，慈诫同称轶宪英。","蔀屋茅檐趋十郡，一时瞻拜祝长庚。"]},{"t":"题懊道人临赵松雪水墨鸳鸯兼书崔珏诗","f":"七言律诗","c":["芦荻风起横塘秋，双双贞鸟相匹俦。","恶彰文彩敛锦翼，还防罗毕藏沙洲。","水墨吴兴号逸品，诗篇崔珏称名流。","道人摹拟尽神妙，欲辨真赝劳清眸。"]},{"t":"伯夷叔齐庙 其一","f":"七言律诗","c":["天畔巍巍吊古台，征衣遥望拂尘埃。","荒榛合沓山间路，颓壁阴森雨后苔。","悴貌入来方暂拜，名心相对已潜灰。","前途西望寒云起，牢落秋风首重回。"]},{"t":"伯夷叔齐庙 其二","f":"七言律诗","c":["遗踪旧是墨台城，景仰高风入圣清。","万古君臣存叩马，两人心事遂逃名。","瘦癯亲炙当时貌，顽懦应兴此日情。","槛外愁听秋色里，雁行风断别离声。"]},{"t":"伯夷叔齐庙 其三","f":"七言律诗","c":["天伦父命未分明，又值商辛历数更。","才智云兴方应运，黄农歌罢已捐生。","西山岫耸当年绿，滦水波流万古清。","野曲至今传牧竖，悽哀如听采薇声。"]},{"t":"伯夷叔齐庙 其四","f":"七言律诗","c":["云山高峻水流长，清圣名争日月光。","逃国衣冠同揖让，采薇歌曲忆羲皇。","齐桓竞霸雄风尽，唐帝征辽故垒荒。","地下应逢吴泰伯，可堪携手说兴亡。"]},{"t":"出山海关是日宿叶家坟 其一","f":"七言律诗","c":["又逐西风出塞垣，却将辽海作家园。","黄沙白草荒城曙，衰柳残烟古戍昏。","风景空增游子恨，江山不返二亲魂。","回看万里云天杳，泪洒龙冈暮雨繁。"]},{"t":"出山海关是日宿叶家坟 其二","f":"七言律诗","c":["龙冈夜雨晓初收，惊见霜花草际浮。","一剑凄凉人出塞，万山巀嵲雁鸣秋。","驱驰世路馀空橐，荏苒光阴已白头。","把酒自悲还自笑，古来得失只荒邱。"]},{"t":"艾明德叶圣嘉蔡宗鲁魏文壁与余皆庚午年生交最善十年来相继物故归而哭之又随征雁上长安月照离筵惨不欢满眼穷愁悲骨肉空囊冰雪走饥寒炎凉作客肌肤惯天地无家去住难八口关心聊复尔松楸回首泪阑干既痛逝者且自念也","f":"七言律诗","c":["一官匏系逐风尘，十载归来问故人。","嵇阮莫酬青史愿，轩岐不救白华身。","诗书世泽空文藻，鸿博徵名付莽榛。","幸我同庚未同死，生刍犹奠一卮春。"]},{"t":"沈阳留别家人","f":"七言律诗","c":["又随征雁上长安，月照离筵惨不欢。","满眼穷愁悲骨肉，空囊冰雪走饥寒。","炎凉作客肌肤惯，天地无家去住难。","八口关心聊复尔，松楸回首泪阑干。"]},{"t":"姜女祠和壁间韵","f":"七言律诗","c":["嵯峨片石对秦城，千古存亡动远情。","过客谩深姜女恨，芳名翻幸祖龙成。","山雄绝塞当祠落，海捲洪涛到岸平。","瞻罢出门频叹息，贞魂缥缈望中生。"]},{"t":"红瓦店晓发","f":"七言律诗","c":["梦回边戍月朦胧，海峤嗷嗷过雁鸿。","满眼霜花连塞白，惊心燎火彻天红。","侵星入谷驱羸马，鹤骨鹑衣战朔风。","老去壮心穷未减，那知羞涩一囊空。"]},{"t":"腐儒","f":"七言律诗","c":["历遍诸艰返故园，百年蓬荜腐儒尊。","鍊成铁骨磨天地，撞破烟楼让子孙。","高揭云心参大化，深探月胁识真源。","玄猿老鹤来三径，朱草琪花自一村。"]},{"t":"孟夏雨后简毛秋岑明复庵相约再游王园","f":"七言律诗","c":["燕地春寒景物湮，寻春春尽不逢春。","连朝已渥催花雨，清兴还思附骑尘。","山翠自添前度色，莺声应唤再游人。","过迟太早均无当，斟酌良辰办酒缗。"]},{"t":"再简毛秋岑","f":"七言律诗","c":["名场蝉蜕歌式微，重来燕市故识稀。","冠裳久乏真知己，侠义终归大布衣。","野鸟野花足寄傲，醉歌醉哭咸忘机。","况君不趿信陵履，春光谁复能羁违。"]},{"t":"咏落叶敬步御制原韵 其一","f":"七言律诗","c":["露折霜摧岂自由，花残莺老债谁留。","无边晻暧成虚荫，不断萧骚付浊流。","弃妇机中明月夜，离人江上白云秋。","何须更听回风曲，满眼荣枯导客愁。"]},{"t":"咏落叶敬步御制原韵 其二","f":"七言律诗","c":["东西飘泊散残红，寥落关山夕照空。","岂向御沟流锦字，已甘憔首逐飞蓬。","集无枯菀随凉雨，望断青葱忆好风。","最是蝉鸣凄绝处，萧萧声乱五更中。"]},{"t":"咏落叶敬步御制原韵 其三","f":"七言律诗","c":["瞥眼惊看节序殊，流光那得住斯须。","已伤茂苑差池陨，旋感深林次第无。","力怯云衢甘委壑，巢怜风影泣栖乌。","枝头未尽苍黄色，惨淡馀荣尚守株。"]},{"t":"咏落叶敬步御制原韵 其四","f":"七言律诗","c":["风木无端惊客心，皋鱼隐痛对伊深。","飘来湿处疑含泪，盼去空庭失旧阴。","忆接芳蕤徒缱绻，情依乔影费追寻。","羁人不寐愁听汝，中夜蛩音杂雨音。"]},{"t":"咏落叶敬步御制原韵 其五","f":"七言律诗","c":["田家荆树近如何，泪洒枯茎感慨多。","纷与断霞争渡水，乱披残霭下寒波。","虫书未就馀残萚，蚁梦初回尽改柯。","鸿雁影稀孤干在，愁心摇落遍关河。"]},{"t":"咏落叶敬步御制原韵 其六","f":"七言律诗","c":["天高地迥感深秋，无定萍踪相对愁。","梦逐樵蓑穿石磴，魂迷渔笠上兰舟。","穷途有哭如狂阮，随处堪埋类醉刘。","敢以巴言赓睿藻，自伤身世等浮沤。"]},{"t":"九日燕台怀古","f":"七言律诗","c":["陟身千仞览遐荒，往古遗踪事缈茫。","燕市几曾收骏骨，召南何处觅甘棠。","云来西北连阴岳，雁过高空带晓霜。","我但呼朋谋醉饱，黄花白酒蟹盈匡。"]},{"t":"渔父","f":"七言律诗","c":["江间渔子钓初罢，蓑笠背负斜阳归。","山鸟有时入茅屋，溪云随艇停荆扉。","为耽泉石偶遁世，遂与鹿豕相忘机。","烹鱼沽酒聚樵牧，酣歌啸傲谁人非。"]},{"t":"答明惺斋招隐沧洲原韵 其一","f":"七言律诗","c":["名场削籍滞长安，几载悲歌行路难。","海角一椽思野处，天边孤鹤任高盘。","为郎颜泗虚迁尉，多病文园欲挂冠。","潦倒风尘知己尽，桂丛深处拟追攀。"]},{"t":"答明惺斋招隐沧洲原韵 其二","f":"七言律诗","c":["石径茅茨觅旧安，宦途深觉立身难。","天人籁发将齐物，薖轴吟成继考盘。","养性不贪鸡肋味，寻山应制鹿皮冠。","扁舟旧说沧洲远，云鹤高踪孰可攀。"]},{"t":"答明惺斋招隐沧洲原韵 其三","f":"七言律诗","c":["拂衣沧海梦魂安，南亩桑麻课不难。","收雨懒云归峤远，培风雏凤薄霄盘。","尊当花月烹肥羜，座杂渔樵著小冠。","回首应怜荣竞路，缁尘鸳鹭正追攀。"]},{"t":"将赴辽东营窆先二人并大兄嫂三兄留别在京诸友","f":"七言律诗","c":["梦绕辽疆夜渡河，仓皇东去恨如何。","千秋华表仙禽邈，万里羁魂绝塞多。","难后死生无定计，愁来天地尽悲歌。","欲知前路真消息，血泪应增海上波。"]},{"t":"三河县访赵邑宰康已迁大兴去一日矣","f":"七言律诗","c":["单车羸马任蹉跎，连日征途阻啸歌。","山拥孤城当大路，地排三水走长河。","故人昨已朝京去，行李今方冒雪过。","我自思君倍惆怅，鸡坛车笠竟如何。"]},{"t":"客有问余诗者赋此答之","f":"七言律诗","c":["岂有元音重庙堂，干求当世避炎凉。","荒山暮雨劳行役，紫塞秋风过战场。","远道怀人生死泪，陈编吊古废兴肠。","更多身外閒歌哭，慷慨无端每醉乡。"]},{"t":"长城吊古","f":"七言律诗","c":["祖龙冀立万年基，鹿马盈庭祚已移。","蹈海仙船人远遁，防胡力政计空奇。","榆关障岭通辽蓟，碣石波涛控岛夷。","中外一家归圣化，宁知王者大无私。"]},{"t":"宿山海关","f":"七言律诗","c":["崨嶪群峰暮霭多，长城蟠挂势巍峨。","防边夜警重关□，出塞声悲壮士歌。","见惯云山头已白，春深瀛海雁初过。","凭高万里看秦塞，明月苍茫隔绛河。"]},{"t":"夏屋屯","f":"古风","c":["陇头滚滚飞惊泉，奔崖注壑声潺湲。","高峰叆叇暮春雪，空谷纡郁寒烧烟。","碛里危途少人迹，道傍废冢看牛眠。","深林䆗窱隔村落，?篥凄楚吹遥天。"]},{"t":"松山","f":"七言律诗","c":["想像先皇用武奇，书生背水阵何为。","真人天启无疆祚，沧海潮吞百万师。","此日河山存战垒，盛时冠带奉边陲。","生逢累洽重熙后，开国规模动远思。"]},{"t":"望海店吊古","f":"七言律诗","c":["茫茫何处是蓬瀛，万顷银涛混太清。","徐市孙卿真大猾，秦皇汉武岂长生。","雨来岛黑看龙挂，风起崖崩听虎鸣。","险历重冈閒吊古，夷歌羌笛总边情。"]},{"t":"吊古战场","f":"七言律诗","c":["落日悲风起塞垣，暂停车骑眺高原。","黄沙荒碛征人墓，野月哀笳壮士魂。","何代庙谟勤远略，至今殇鬼哭黄昏。","由来德化消兵燹，四海浑忘乐利恩。"]},{"t":"十里台避风遇故人话旧","f":"七言律诗","c":["邂逅同酣浊酒杯，谩将往事费疑猜。","迂儒自分难投俗，圣主何曾肯弃才。","野日荒荒春草白，黄沙滚滚塞鸿哀。","邮亭饮罢旋分袂，泪洒龙堆十里台。"]},{"t":"甲子三月五日抵沈阳","f":"七言律诗","c":["归来身世感歧途，廿载飘零菀复枯。","蓬室栖迟惭角绮，金门饱死愧侏儒。","云山无恙人将老，天地多情草又苏。","风木空馀游子恨，蓼莪吟罢泪模糊。"]},{"t":"春郊晓望","f":"七言律诗","c":["扶桑晴日晓无烟，纵目高冈极远天。","山势北来雄帝阙，海潮东去见朝鲜。","豳风业就神龙跃，紫塞春随旅雁还。","形胜先皇遗迹在，郁葱佳气满辽边。"]},{"t":"过某隐居感赋","f":"七言律诗","c":["衡泌何时遂息机，避人踪迹任褒讥。","已安濩落材无用，不分渔樵愿亦违。","过眼烟□难久住，羡君鸾鹤早同归。","芳踪一去经千载，寂寞云山旧采薇。"]},{"t":"觅茔地得","f":"七言律诗","c":["折臂三公贵亦凶，牛眠岂敢冀前踪。","但求安土归窀穸，能妥幽魂不树封。","海角奇经搜地骨，云根奥窟隐山龙。","嵷隆陵寝从西望，朝夕氤氲紫气重。"]},{"t":"别沈阳","f":"七言律诗","c":["风淳地沃丰岐并，旅食频年骨暗惊。","未获潜身安乐土，争求识面但虚名。","蠮螉塞下黄云路，鸡鹿山前白发生。","几日归来席未暖，又携诗卷向神京。"]},{"t":"辽东离席座上尽江浙人感而留赠","f":"七言律诗","c":["江左山阴道路赊，一尊邂逅聚天涯。","最怜满座思归客，翻送愁人远去家。","细雨深孤新菡萏，离筵惭对野榴花。","欲知别后相思处，班马嘶风落日斜。"]},{"t":"赠尹相国四公子卓庵","f":"七言律诗","c":["濡首泥涂不觉非，宦途恬退世人稀。","谁如宰辅佳公子，甘作林泉老布衣。","振策高峰看蜃市，濯缨沧海立龙矶。","知君心契渔樵侣，我亦风尘久息机。"]},{"t":"送毛秋岑","f":"七言律诗","c":["野水经霜镜远空，西峰过雨翠崇隆。","正期蜡屐寻僧舍，无那蒲帆返桂丛。","昔日烟霞诗社在，扁舟蓑笠酒人同。","燕台应念羁愁客，翘首南云望雁鸿。"]},{"t":"书怀","f":"七言律诗","c":["百年深惧此生浮，怀古心希第一流。","风雨鬼神窥陋室，艰难天地策精修。","阰牵兰桂悲徒远，芳树蓠蘅怅未收。","荏苒须眉空老大，崦嵫西望冀淹留。"]},{"t":"吊岳忠武王","f":"七言律诗","c":["英雄血战奋蜺旌，雪耻忠丹贯日明。","不忌犁庭回二帝，忍教奸相坏长城。","魂骑箕尾归苍昊，地涌波涛走巨鲸。","从此中原终莫救，至今烈士恨难平。"]},{"t":"经圣祖仁皇帝围场恭纪遥和明惺斋奉使查边旧作","f":"七言律诗","c":["威胡狝狩出严疆，万乘旌旗耀日光。","骁骑合围营细柳，侍臣簪笔赋长杨。","云留峭壁呼鹰处，草满平原射虎场。","昔日壮图劳圣主，至今神武凛夷王。"]},{"t":"读易","f":"七言律诗","c":["百年甘作老迂儒，矻矻深愁岁月虚。","扫尽尘情栖陋室，辟开灵腑读奇书。","阴阳顺逆生成后，消息絪缊法象初。","敢谓抚躬能寡过，聊搜精义遣居诸。"]},{"t":"送童觐王南旋","f":"七言律诗","c":["二十五年悲契阔，天南塞北两茫然。","风尘此日犹重面，亲友当时半九泉。","后会未知文酒地，清秋还是别离筵。","从兹我欲寻黄绮，乘兴应迷雪夜船。"]},{"t":"大侄秉瑜来自湖广 其一","f":"七言律诗","c":["当时显考黜纶扉，尔父飘零我北依。","塞上庭帏生死隔，天涯兄弟信音稀。","迢遥乡国重云暗，纂述箕裘旧业非。","五十馀年方见汝，苍颜白发对歔欷。"]},{"t":"大侄秉瑜来自湖广 其二","f":"七言律诗","c":["五载长安寄客身，游踪知尔楚由秦。","乍逢不识生离貌，细语犹疑梦里人。","忆自孩提家遘难，忽相哀咽泪沾巾。","即今飘泊同衰老，乡国茫茫那问津。"]},{"t":"春日简孟颍仙","f":"七言律诗","c":["晴郊野趣耽腐儒，出郭寻春亲鸥凫。","花柳多情久相待，溪山有约焉可孤。","载酒扁舟故人共，随筇浅草新雨濡。","收来蘋池竹里句，将绘辋川摩诘图。"]},{"t":"蔚千春筵咏梅花","f":"七言律诗","c":["老干离奇历岁年，花迎首祚发华筵。","空矜玉貌堪谁赠，久抱寒香欲自仙。","时爱尚需桃李艳，孤情不爱蝶蜂怜。","漫言托地非暄暖，松柏精神荫后先。"]},{"t":"赠李徵君廌青","f":"七言律诗","c":["田盘高蹈逸风尘，五载萦思不易亲。","道谊文章关运会，烟霞泉石掩经纶。","向平婚嫁寻山晚，攸绪荣华出世真。","此日泥涂逢大隐，虚疑姑射有神人。"]},{"t":"立秋前一日典衣邀同人看荷","f":"七言律诗","c":["久客光阴感慨中，花时难遣酒杯空。","况兼白发伤迟暮，宁惜青袍作主东。","千叠云山环北郭，一溪烟水自离宫。","须知雅会非长得，几日秋生大块风。"]},{"t":"答友人道意 其一","f":"七言律诗","c":["茫茫尘海隔灵槎，身世蜉蝣日已斜。","李杜文章名滥窃，皋夔事业愿空奢。","金门偶驻王乔舄，笙鹤如瞻缑岭霞。","借问秘函玄妙诀，春风消息到梅花。"]},{"t":"答友人道意 其二","f":"七言律诗","c":["阴阳来往运无端，电掣风驰易老残。","千古兴亡纷蚁垒，百年辛苦转蜣丸。","蓬山仙路云车引，辽海箫声鹤驾寒。","指点尘寰奔竞地，可堪华表一回看。"]},{"t":"友人邀饮即席赋赠","f":"七言律诗","c":["瀰漫冰雪岁将残，失路空嗟范叔寒。","卖赋几时逢狗监，论交何处觅鸡坛。","寸衷久抱千秋恨，斗酒聊谋一夕欢。","我亦吹篪同落魄，长安裘马笑儒冠。"]},{"t":"简答友人","f":"七言律诗","c":["奇才孤诣企前贤，百岁遭逢但信天。","生不同时多后憾，身虽觌面亦徒然。","苍松岁久脂凝珀，黄鹤丹成骨自仙。","从古名山留大业，知音端不在当年。"]},{"t":"简余省三","f":"七言律诗","c":["蒯缑结佩践朱门，偃蹇才华讵可论。","吾道自应纨裤贱，穷途谁识缊袍尊。","中宵乡梦吴山远，几载羁愁塞雪昏。","乘此秋风未摇落，扁舟归去问家园。"]},{"t":"寿金总戎毓昆七秩双庆","f":"七言律诗","c":["华堂瑞霭映朝霞，堂上齐龄岁月赊。","黍谷松虬持杖国，天中榴火结丹砂。","蛮烟瘴雨元戎绩，绣虎雕龙甲第家。","忠孝绵绵传世泽，何须蓬岛问仙槎。"]},{"t":"五月望后热甚忆李廉衣柯东岩园居却寄","f":"七言律诗","c":["人间何处觅蓬壶，相国园林世所无。","远水千盘通沼榭，秋风五月落松梧。","山搜奇景看晴雨，诗搆精思状画图。","应念老夫尘垢里，支颐西望正踟蹰。"]},{"t":"寄答边选拔赵珍二首 其一","f":"七言律诗","c":["邂逅相逢棘院时，愁怀未罄十年思。","忽惊投笔仓皇去，欲悔谋尊缱绻迟。","云树正牵羁客梦，雁鸿遥寄故人诗。","开缄读罢真堪泪，知我如君更有谁。"]},{"t":"寄答边选拔赵珍二首 其二","f":"七言律诗","c":["潦倒非关世路歧，君才卓荦数何奇。","无媒拙宦时应弃，落第频年事可疑。","海内文章声价重，室中风雨鬼神知。","名山大业争千古，吾党荣枯贵自持。"]},{"t":"立秋日携近诗过天峰饮","f":"七言律诗","c":["对酒高吟客里诗，惊看梧叶坠阶墀。","三秋消息萌深暑，一岁寒暄判此时。","敢道才雄摇海岳，但知巨斝吸鲸螭。","百年多难身长在，赖有奇情老未衰。"]},{"t":"吊钱中和","f":"七言律诗","c":["遍历名山觅返还，可堪垂老释黄冠。","徒令吊客悲膏火，岂有穹霄降玉棺。","薤露歌前风日惨，北邙山下水云寒。","不须泉路通消息，定悔红颜缚羽翰。"]},{"t":"送葬","f":"七言律诗","c":["缟素衣冠塞路尘，白杨风起正愁人。","恩荣分隔泉台夜，金粉情抛翠幄春。","缥缈游魂从变幻，招摇丹旐插荆榛。","智愚今古皆沦没，谁解玄关养谷神。"]},{"t":"辞馆","f":"七言律诗","c":["怀璧休言价十城，生憎海鹤向人鸣。","平原好客遗毛遂，越石宁囚谢晏婴。","辽水东西堪采药，缑山缥缈羡吹笙。","冥冥踪迹孤鸿远，翘首云霄去后情。"]},{"t":"贺同年张太守蔚千新居兼值诞辰","f":"七言律诗","c":["潋滟湖光绕帝州，杖藜科跣任遨游。","欣看荷芰盈新夏，知是蓬瀛第几洲。","待客云山今得主，逢君海屋正添筹。","人间欲问耆英叟，遥指蒹葭秋水头。"]},{"t":"题蔚千荷庭","f":"七言律诗","c":["衡门荒径遂栖迟，复有湖塘性更怡。","养鹤何须寻阆苑，卜居今已近瑶池。","山云高覆槐阴席，卮酒閒谈竹马儿。","牢落风尘谁得似，茫茫烟水忆鸱夷。"]},{"t":"仲夏望日过蔚千饮","f":"七言律诗","c":["谩誇远水与遥岑，城市山林此又寻。","南浦雨过湘簟爽，西峰云起晓窗阴。","忘形礼数捐虚谬，坐客尊醪任浅深。","借问当时河朔饮，可能来往有高吟。"]},{"t":"简问蔚千花信","f":"七言律诗","c":["閒把幽情问硕薖，别来花信近如何。","几番澍雨催红萼，应有明霞涨碧波。","瞥眼升沈同白发，颓龄风景合高歌。","知君不厌清狂客，竹杖芒鞋早暮过。"]},{"t":"雨后偕同人过蔚千饮 其一","f":"七言律诗","c":["幽栖岂必出人群，水绕柴门绝俗氛。","联袂来看三径雨，解衣先坐一床云。","泖湖皂盖当年事，御沼清尊此日勋。","卓荦满堂佳客聚，应占星象动天文。"]},{"t":"雨后偕同人过蔚千饮 其二","f":"七言律诗","c":["坐看空际雨霏微，云气苍茫绕竹扉。","供客佳鱼随网得，开筵野鸟近人飞。","浣花溪晚少陵醉，折角巾欹郭泰归。","聊为盛时留太古，往来宾主尽忘机。"]},{"t":"蔚千索题新居","f":"七言律诗","c":["傍居咫尺即嚣氛，心远偏能绝弗闻。","槛外时鸣幽涧鹤，檐前长宿近山云。","长公出处原无碍，仲蔚蓬蒿久不耘。","几次辟书徵未起，北山君岂愧移文。"]},{"t":"过蔚千荷庭谩兴","f":"七言律诗","c":["萍踪浪迹滞天涯，谁可开怀共酒卮。","每向槐阴寻旧雨，几经苔径觅新诗。","地非巢父牵牛处，人是濂溪解绶时。","同在风尘名利外，孤云野鹤自相随。"]},{"t":"过蔚千荷庭饮","f":"七言律诗","c":["子真谷口远离尘，弘景白云只自亲。","岂有湖山同翠水，不劳舟楫问迷津。","一尊风雨时留客，近市烟霞可赠人。","遂使辽东老羁旅，常抛书卷过西邻。"]},{"t":"偕同人过蔚千荷庭分赋","f":"七言律诗","c":["碧云香雾望中迷，晴雨皆堪命杖藜。","濠上襟期君不减，辋川柴馆我频题。","诗篇淡老逢陶谢，人物风流尽阮嵇。","咫尺枌榆来往易，避炎深坐夕阳西。"]},{"t":"过蔚千荷庭晚归二首 其一","f":"七言律诗","c":["尘嚣何处挹清芬，高咏新诗每过君。","真羡幽居堪寄傲，敢誇健笔足淩云。","烟沈霞起閒中谛，鸟语溪声静里分。","长夏淹留忘溽暑，倚栏清啸日斜曛。"]},{"t":"过蔚千荷庭晚归二首 其二","f":"七言律诗","c":["落落遐心远嚣俗，洋洋泌水堪乐饥。","图画昔时已愈疟，栖迟此处真忘机。","村犬吠云日欲暮，荷溪照月花仍辉。","老夫短筇策沙岸，随风香气吹我衣。"]},{"t":"立秋七日蔚千招同僧司业理斋陶侍讲西园荷庭宴集得卮字","f":"七言律诗","c":["初秋凉气散庭墀，高树云阴荫酒卮。","红涨雨溪花焕烂，翠翻风壁竹参差。","閒吟屡接山阳宴，爽籁新传太史诗。","忘却扁舟鲈鲙思，林塘正有好襟期。"]},{"t":"秋日过蔚千荷庭索饮花事已阑","f":"七言律诗","c":["盍簪几日觅佳游，岁月推迁大火流。","出世襟期醇酎涤，隔帘葭菼御河秋。","修篁拂露侵宾座，旅雁含风过钓舟。","花事已阑时欲暮，愁听白纻满中洲。"]},{"t":"岁暮寄怀年家子毛秋岑","f":"七言律诗","c":["分携南浦泪盈裾，三载愁怀望雁鱼。","清夜云山魂几去，萧斋风雪岁将除。","君方松泖耽鲈鲙，谁解临邛问子虚。","寂寞空吟梁月句，不堪衰谢怅离居。"]},{"t":"送秉瑜大侄从军大金川","f":"七言律诗","c":["天家神器出龙堆，问罪雄师走迅雷。","借箸书生□武备，登坛大将是奇才。","几年巴徼兵戈梗，计日蛮荒瘴疠开。","顾我谈经头己白，免教投笔起徘徊。"]},{"t":"刘编修殿虎赠余诗己三年矣赋此答之 其一","f":"七言律诗","c":["吾辈迂疏世共闻，难将知己问尘氛。","况当遁迹如张俭，谁信谈经类子云。","识具古今仍嗜学，交空南北始逢君。","芝兰赠我联同气，怀袖三年吐异芬。"]},{"t":"刘编修殿虎赠余诗己三年矣赋此答之 其二","f":"七言律诗","c":["碧云苍雾讲堂阴，燕市离群听雁音。","倾盖一谈天下计，开襟真见古初心。","浮沈声气交嫌晚，商榷人天道且深。","白雪若教容易和，岂烦岁久始追寻。"]},{"t":"读史","f":"七言律诗","c":["独坐荒斋思渺茫，千秋遗事感兴亡。","汉平楚霸疑韩信，宋逼金人用李纲。","山涌风云关塞黑，霜摧洲渚荻芦黄。","不堪摇落伤秋晚，鸿雁声哀下夕阳。"]},{"t":"蔚千七十初度并贺生女","f":"七言律诗","c":["云间太守仲弓才，晚节襟怀傍钓台。","天假湖塘娱大隐，人因烟水恋深杯。","淩霄老柏栖鸾翼，明月新珠出蚌胎。","矍铄如君谁得似，檐前榴火报初开。"]},{"t":"夏至日蔚千招饮荷庭","f":"七言律诗","c":["骄阳隆赫正斯时，独有林庭暑更宜。","苔厚阶除人迹少，水侵栏槛鸟飞迟。","陶令归来唯嗜酒，杜陵老去渐工诗。","高吟剧饮无拘束，不觉狂遗白接䍦。"]},{"t":"邯郸梦和屈北雄原韵 其一","f":"七言律诗","c":["卢生献赋去仍还，歧路萧条此遇仙。","旅馆徒传千载梦，邯郸谁续再来缘。","天空孤鹤鸣丹嶂，风驾晴云忆彩鸾。","何处黄粱寻胜迹，遥遥墟里见炊烟。"]},{"t":"邯郸梦和屈北雄原韵 其二","f":"七言律诗","c":["灵黍何须问大还，热心顿冷即神仙。","群生苦恋浮尘梦，一枕谁空欲海缘。","久弃名场閒养药，未应云路禁骖鸾。","追寻往事邯郸道，陵壑苍茫绕夕烟。"]},{"t":"蔚千荷庭","f":"七言律诗","c":["骇汗冲炎事早休，朅来杯酌对芳洲。","凉生几簟非关雨，风起松篁忽讶秋。","唐相冰山消烈日，石家金谷衄危楼。","天留尔我升沈外，疏放凭谁笑白头。"]},{"t":"出郊远眺","f":"七言律诗","c":["万里关山烟雾重，巍峨宫阙动疏钟。","入云春燕差池羽，逐水桃花烂漫容。","事业久甘终卷帙，性情偏喜近筠松。","沧洲东去无多路，樵牧将随出世踪。"]},{"t":"简蔚千索饮","f":"七言律诗","c":["每到炎天苦烈晖，便思荷槛叩荆扉。","隔窗幽鸟群呼雨，绕麈□云□湿衣。","但许疏狂挥素壁，不须弦管乱清机。","老来珍惜閒中会，风起花溪落易稀。"]},{"t":"饮蔚千荷庭因书己意二首 其一","f":"七言律诗","c":["高树鸣蝉昼亦阴，门环灵沼受凉深。","溪山得友方成赏，风雨开尊每过寻。","凫雁惯来离垢境，主宾相对出尘心。","临轩一曲横焦尾，高咏成连海上音。"]},{"t":"饮蔚千荷庭因书己意二首 其二","f":"七言律诗","c":["举目无非执热场，特来此处就清凉。","买山未结高人侣，对景翻生久客伤。","采采芙蕖难涉水，青青荷芰可缝裳。","烟霞有约空相待，矫首南天忆故乡。"]},{"t":"饮蔚千荷溪 其一","f":"七言律诗","c":["绕舍东南尽水乡，冰盘雪槛映壶觞。","清风独厚羲皇叟，野客偏宜薜荔裳。","龙岫已凋梁国苑，锦棚不羡富家庄。","更从何处容疏放，挥洒烟云啸咏长。"]},{"t":"饮蔚千荷溪 其二","f":"七言律诗","c":["虽有湖塘供老眼，也因心远解徜徉。","青槐晴下重阶荫，白鹭炎飞几片霜。","隔岸轮蹄纷冒暑，爽人庭榭且衔觞。","天时世事从无定，水色山光总未央。"]},{"t":"七夕后一日饮蔚千荷庭","f":"七言律诗","c":["何须银汉舣灵槎，对此湖光意己赊。","树里人烟疑海屋，云中鸡犬近仙家。","暮年醇酒为生计，早岁荣名作幻花。","我亦从兹思远遁，武林深处问桑麻。"]},{"t":"遥同明复元奉使北夷渡黑龙江旧作","f":"七言律诗","c":["使臣衔命戾江濆，江水澄源接紫氛。","蚌吐珠光争夜月，龙腾潭窟起祥云。","星槎击汰双旌耀，天语开函绝域闻。","才仗济川联部落，共占声教奉明君。"]},{"t":"送门人杨伊水赴乌程主簿","f":"七言律诗","c":["黄鸟嘤嘤求侣声，春风饯别赴乌程。","存心利物一官好，折柳离亭百感生。","仇览己成鸾凤质，于陵终属庙堂英。","多年世契文章友，淹恤何堪送远情。"]},{"t":"题孙在原江行小照","f":"七言律诗","c":["五溪三峡出黔阳，贤宰朝京道路长。","蜃雨蛮烟收健笔，雕题卉服送行装。","孤帆身拔蛟龙窟，万里心依日月光。","履险如夷看道貌，乘风应不羡宗郎。"]},{"t":"代张稼兰送怀来令吴文正","f":"七言律诗","c":["书剑翩翩塞上游，莺花首夏送行辀。","旧从珠浦瞻丰度，新绾铜章喜献酬。","水落桑乾环帝阙，山连阴岳壮神州。","秦城代邸多遗迹，歌咏无忘寄白头。"]},{"t":"代张稼兰送白水令梁善长","f":"七言律诗","c":["十年宦海涉风波，白发名场老复过。","燕市逢君重握手，龙江回首一悲歌。","正堪花月谈当日，无计河桥挽去珂。","愁绝秦关云路杳，分携莫惜醉颜酡。"]},{"t":"壬申冬过天津赠同年卢运使雅雨","f":"七言律诗","c":["潦倒燕台已暮途，耽吟知己遇全疏。","冰霜路绕长芦陌，棨戟门瞻大海隅。","敢诩叔鸾称独步，争传子干是鸿儒。","编成出塞谁能和，风雅逢君道不孤。"]},{"t":"咏瓶花","f":"七言律诗","c":["胆瓶斜插两三枝，丰致嫣然亦可怡。","满室馨香春焕烂，隔帘蜂蝶影参差。","易伤艳质纷纷落，好劝熏风细细吹。","景物随时看不尽，名园回首事多悲。"]},{"t":"甲戌真州九日邀署中诸友游吴许二园林","f":"七言律诗","c":["真州吴囿城东湄，扁舟九日来探奇。","湘芷江兰杂洞壑，古柏老桂蟠蛟螭。","忽讶远山渡隰岸，那知高阁淩厜㕒。","乘兴邻园贾馀勇，短筇登历忘饥疲。"]},{"t":"秋日偕任徵君东涧集龙门桥归汎江口看山之作","f":"七言律诗","c":["西郭乘流出市阛，龙门桥畔听潺湲。","修篁尊酒方延赏，迟日扁舟未拟还。","烟树苍茫胥口渡，云峰突兀润州山。","不缘官署身拘限，长共浮鸥野外閒。"]},{"t":"将至杭州便道访刘野鹤山居","f":"古风","c":["萍踪无定复南游，垂老天涯且未休。","满目波涛穷厉揭，空山薜荔自春秋。","久?尘匣沦双剑，应有灵槎到十洲。","拟向刘安问仙诀，莫将鸿宝秘丹邱。"]},{"t":"秋日寄怀任东涧","f":"七言律诗","c":["君住山阳淮水畔，余家辽左鸭江滨。","一朝邂逅怜同调，千古文章信有神。","待价骅骝虚苜蓿，高栖鸾鹤老松筠。","相思北望秋将晚，鸿雁声高落叶频。"]},{"t":"乙亥九日偕署中诸友登北山寺","f":"七言律诗","c":["九日招携出郭游，清尊野菊对閒鸥。","狂吟我欲题青壁，落帽君无笑白头。","人滞江乡风月老，雁横霜浦荻芦秋。","南朝剩有佳山色，乘兴登临一放眸。"]},{"t":"九日登北山寺怀都门诸友","f":"七言律诗","c":["傍城孤屿石崚嶒，九日扶筇试一登。","东走江声趋铁瓮，南来山色障金陵。","回看京国伤离别，久客天涯眷友朋。","此日知君怀我处，丹厓应上最高层。"]},{"t":"秋日偕富甥介伟游龙门桥归汎江口看山","f":"七言律诗","c":["西门之外龙门桥，森森万竹参天高。","扁舟欹侧入荻浦，秋云黯淡横江皋。","连峰隔岸势奔走，巨舸争渡声嗷嘈。","乘醉披襟一鼓棹，诗成吟啸轻波涛。"]},{"t":"题汪西灏奉萱图","f":"七言律诗","c":["偶辞鸥鸟趋徵诏，旋返钱塘老布衣。","自有閒居真事业，独留至性在庭闱。","茅容对客烹鸡后，和靖临湖放鹤归。","应使劳劳朝市士，披图潜息利名机。"]},{"t":"奉窆曾祖母祖父后留别地师朱汇徵","f":"七言律诗","c":["万里艰难投绝塞，百年存没隔辽天。","平生洒尽思乡泪，垂老归来买墓田。","脚踏烟岚穷豹隐，峦回沙水卜牛眠。","我曾我祖安窀穸，别后宁忘括地仙。"]},{"t":"送沈驭风归辽东","f":"七言律诗","c":["真州城中浩雪飞，真州城外行人稀。","肩舆仆仆晨出饯，江风飒飒寒吹衣。","萍蓬飘泊我犹客，关山迢递君能归。","垂老他乡岂易别，遥瞻云水心依依。"]},{"t":"和友人游仙杂诗 其一","f":"七言律诗","c":["年来踪迹但支离，世味人情老渐知。","材与不材堪自处，道非常道觅吾师。","鸾音鸿爪同消息，老屋荒江阅岁时。","笑看蚍蜉尘垢里，熙熙攘攘欲奚为。"]},{"t":"和友人游仙杂诗 其二","f":"七言律诗","c":["三才相盗复相媒，消息人间莫浪猜。","识得蟾精随月满，直教龙女献珠来。","井轳倒绠牵泉脉，犀火灵潭照蚌胎。","另立乾坤身再造，伫看名姓列丹台。"]},{"t":"和友人游仙杂诗 其三","f":"七言律诗","c":["先天一气叩关元，窅窅冥冥大药存。","颠倒乾坤成泰象，往来离坎立玄根。","狂澜海底探蛟穴，逆水滩头过剑门。","送得真人归洞府，温风桃熟武陵源。"]},{"t":"和友人游仙杂诗 其四","f":"七言律诗","c":["闻说仙人十二楼，琪花瑶草秘神州。","身探月窟金初现，手挽天河水逆流。","沧海露凝珠颗润，蓝田风暖玉苗秋。","万灵呼吸皆从令，不让卢敖汗漫游。"]},{"t":"和友人游仙杂诗 其五","f":"七言律诗","c":["遐思未遂赤松游，大道虽闻不解愁。","荏苒光阴惊逝水，飘零天地感浮鸥。","襄王绮梦怀神雨，嬴女箫声隔凤楼。","羡杀瑶池陪宴饮，蕊珠宫里露华秋。"]},{"t":"和友人游仙杂诗 其六","f":"七言律诗","c":["人间天上事如何，谩道黄姑别恨多。","自有鹊桥通碧落，不教织女隔银河。","彩云结绮成华幄，玉露凝珠坠锦梭。","从此星垣罗袜敛，岂烦岁岁久淩波。"]},{"t":"和叶某留别原韵 其一","f":"七言律诗","c":["浊俗谁堪性命亲，出尘丰格慕长春。","云衾石枕名山梦，月径苔矶野鹤茵。","混沌凿开天上路，大千甘溺幻中身。","从兹抉出樊笼外，万虑纠纷一霎驯。"]},{"t":"和叶某留别原韵 其二","f":"七言律诗","c":["入山唯觉与山亲，鸟语花香识岁春。","雨过紫芝生绣谷，风来朱草落云茵。","地无名利戕真性，天假烟霞铸道身。","莫讶形同黄鹤健，已将心共白鸥驯。"]},{"t":"和叶某留别原韵 其三","f":"七言律诗","c":["但解繁华著意亲，那知转瞬不成春。","貂蝉冷落麒麟冢，歌舞销沈锦绣茵。","太上洪施延命诀，百年忍作断蓬身。","唯期大事因缘就，山鸟山花处处驯。"]},{"t":"和叶某留别原韵 其四","f":"七言律诗","c":["微躯天地亦何亲，玄发朱颜旦暮春。","剌眼莺花摧大块，惊心冰雪积寒茵。","灯残漏尽三生梦，蔓草荒原百岁身。","不待刘家丛桂长，便思叶县两凫驯。"]},{"t":"和叶某留别原韵 其五","f":"七言律诗","c":["飞梦遥连海外亲，惧将尘网汨芳春。","鸣泉落涧羞歌扇，幽鸟衔花薄舞茵。","趼足行吟名峤顶，破瓢饮挂老松身。","龙沙符瑞今当会，八百丛中鹤驭驯。"]},{"t":"和叶某留别原韵 其六","f":"七言律诗","c":["香园善水性天亲，蟾血鸾膏养大春。","时与白云归洞府，月随瀛海上屏茵。","乾坤有象泡中影，今古难醒醉里身。","悯世婆心知不倦，伫看龙杖葛陂驯。"]},{"t":"和叶某留别原韵 其七","f":"七言律诗","c":["和光蛇虎亦须亲，避世襟期别有春。","大地蜉蝣悲浩劫，先天消息迓文茵。","晤言顿醒浮生梦，把臂还惊顷刻身。","是否请君回首看，新人争逐旧人驯。"]},{"t":"和叶某留别原韵 其八","f":"七言律诗","c":["澄怀无碍与天亲，灵蠢皆成大地春。","老鹤玄猿尘外友，落花芳草洞中茵。","云山此去千年计，陆海重来再造身。","我亦心期朝五岳，深惭狂象未能驯。"]},{"t":"和叶某留别原韵 其九","f":"七言律诗","c":["有道真能害作亲，冬藏秋杀尽皆春。","鼎炉鲍石烹神火，海峤蛟珠列翠茵。","银汉槎头徵往事，白云乡里悟前身。","任教轩冕罗天阙，龙性从来不受驯。"]},{"t":"和叶某留别原韵 其十","f":"七言律诗","c":["闻说仙源梦寐亲，桃花流水武林春。","岩端果熟分猿俸，洞口云封坐藓茵。","捐佩久暌朝市客，逢人谁识牧樵身。","敢云真诰从空下，老觉年来性渐驯。"]},{"t":"和叶某留别原韵 其十一","f":"七言律诗","c":["百年唯有道堪亲，岁月从教秋复春。","剑吐龙文翔佩带，座邀天乐奏花茵。","恩深亭毒归灵宥，情款阴阳结寿身。","解得仙凡通咫尺，云旗风马总能驯。"]},{"t":"和叶某留别原韵 其十二","f":"七言律诗","c":["难把玄珠寄所亲，崖花荣悴纪冬春。","灵溪此日留丹灶，仙迹他年感卧茵。","阴谷苍藤藏日月，冰壶石髓澡心身。","大还有药君知否，慧剑成龙豢已驯。"]},{"t":"和叶某留别原韵 其十三","f":"七言律诗","c":["鹿豕堪同眷属亲，襟怀何处不阳春。","壶中甲子还天地，袖里风雷护枕茵。","过去徒留千载恨，悟来方识此时身。","定知万化从心运，海澨烟霄羽驾驯。"]},{"t":"和叶某留别原韵 其十四","f":"七言律诗","c":["山中宰相我情亲，得诀君归洞里春。","行处药锄随杖履，梦回松月照衾茵。","十洲潜影云霄路，五岳淩空鹤背身。","踪迹人间如借问，谷神昌后毒龙驯。"]},{"t":"和叶某留别原韵 其十五","f":"七言律诗","c":["青城乌目一朝亲，石室阴崖万古春。","术秘丹梯金作简，药收银海月当茵。","挥叱云烟鸾鹄驭，往来天地主宾身。","应嗤土窟尸乡叟，但解群鸡绕屋驯。"]},{"t":"和叶某留别原韵 其十六","f":"七言律诗","c":["一与群真笑语亲，八千秋过八千春。","蓝桥结眷邀神女，丹穴流珠醉锦茵。","蓬岛月明朝贝阙，扶桑日出控鳌身。","若逢望气关门尹，吩咐青牛且暂驯。"]},{"t":"九日同年卢都转雅雨邀同钱少司寇香树平山堂登高","f":"七言律诗","c":["重阳连袂眺高台，雨歇平山景物开。","楼阁参差排地起，峰峦突兀渡江来。","白云端为秋卿驻，肃气还因使节回。","落帽风流传胜事，何如此日共衔杯。"]},{"t":"和同年卢都转雅雨红桥修禊原韵 其一","f":"七言律诗","c":["花光夹岸拥仙舟，觞咏良辰竞逗遛。","一自江滨开郑驿，顿令海内识荆州。","清尊到处金衣劝，好句成时锦簟酬。","莫怪画桡喧柳浦，风流都转作遨头。"]},{"t":"和同年卢都转雅雨红桥修禊原韵 其二","f":"七言律诗","c":["裙屐才名尽少年，彩毫争艳万花前。","纷趋巨壑沧溟外，罗列群峰太华巅。","晓日僧开无碍塔，春风人坐总宜船。","炊烟一片晴光合，遥指江城碧树圆。"]},{"t":"和同年卢都转雅雨红桥修禊原韵 其三","f":"七言律诗","c":["交流碧玉四桥通，辇路纡回翠槛东。","曲沼春波涵帝泽，层台仙籁下天风。","离宫宛转窥青琐，绝峤依稀认紫濛。","此日太平传盛事，人人身到五云中。"]},{"t":"和同年卢都转雅雨红桥修禊原韵 其四","f":"七言律诗","c":["看花老眼倍添明，听遍枝头百啭声。","愧我文章真少技，知君心迹自双清。","笙歌队里长春国，灯火光中不夜城。","独撚霜髭赓丽句，水明楼上月三更。"]},{"t":"送宫方伯怡云往嘉兴用同年卢都转雅雨韵","f":"七言律诗","c":["平山高阁忆同游，倾盖论交恨白头。","伏处岂徒钦宿望，晤言真不愧儒修。","銮江随养趋乌目，邗水扬帆向秀州。","何日尊醪重把袂，碧云红树已深秋。"]},{"t":"前题又步原韵一首","f":"七言律诗","c":["邂逅逢君雪满头，怜才慕德两绸缪。","百年耽咏心长泰，万里乘风事早休。","都转雷塘思握管，客星严濑访披裘。","老来我亦无拘束，愿与湖山结胜游。"]},{"t":"寿河间陈太守十四韵","f":"五言古诗","c":["冠冕南都丽，文章北斗悬。","太邱光史册，东武轶陶甄。","帜拔巍科早，风移太邑传。","彤廷隆誉洽，瀛郡德星连。","抚字劳丰歉，恩膏匝陌阡。","珠光辉合浦，麦颖秀旻天。","邵杜声华著，龚黄事业肩。","腐儒依绛帐，旧物有青毡。","蠹饱神仙字，炊荒苜蓿田。","徒闻三绝誉，深愧两斋贤。","雪酿梅花白，春归柳絮妍。","觞称腊去后，筵敞月来先。","覆冒承殊渥，输忱鲜滴涓。","叨陪群属末，泥首祝遐年。"]},{"t":"题贞松图寿谢母苏节妇","f":"五言古诗","c":["老手状贞容，离奇类古松。","烟萝偕婺隐，臃肿却秦封。","节劲寒增茂，心坚岁失冬。","栽培深得地，枝干欲成龙。","空有盈虚数，偏为造化钟。","仙人应驻驾，试看鹤来踪。"]},{"t":"题竹石牡丹图寿谢母苏节妇","f":"五言古诗","c":["竹抱淩云节，根移自海东。","一从飞凤去，甘伴古苔终。","箨老色逾碧，年深势转崇。","枝高无过羽，叶茂不彫风。","甘与巉岩寂，全看富贵空。","但教筠箭发，足以慰孤穷。"]},{"t":"赠济南梁太守十八韵","f":"五言古诗","c":["相国家声旧，孙谋奕叶光。","才华真挺拔，建树岂寻常。","贤以为郎著，名因出守扬。","恩膏被齐鲁，政绩继龚黄。","儒术通敷治，词章允擅场。","披云瞻器宇，伟度识琳琅。","祖武绳经济，嘉谟卜庙堂。","欣叨大厦覆，私觊薄材彰。","腐慢遭时弃，提携愧德凉。","我生同泛梗，天意酷亡羊。","色养哀无禄，亲丧复异乡。","恒饥从妇孺，中夜独徬徨。","泪尽衰麻赤，灵归关塞茫。","麦舟谁解赠，愁病欲成狂。","宁不惜残命，还应乞大方。","深情蒙缱绻，浓荫忆松篁。","斗水枯鱼活，鸿慈再造长。","吹嘘寒谷暖，冥报吁穹苍。"]},{"t":"留赠长清何明府淡园二十韵","f":"五言古诗","c":["大邑抡才子，长清擅胜形。","万山朝泰岱，一水会沧溟。","寺著图澄迹，人传石虎灵。","云来常入牖，鸟浴不离汀。","十里松前月，五峰山后屏。","林峦挥丽藻，政治发新硎。","操苦尘生甑，风移户不扃。","慈祥深雨露，刚断走雷霆。","骐骥驰周道，雕鹏振紫冥。","循良真父母，经济待朝廷。","愧我遭颠覆，伊谁辨渭泾。","乞涂怜白壁，埋狱惜青萍。","脱难悲张俭，归耕慕管宁。","世人皆欲杀，君眼独垂青。","赋笔惭鹦鹉，原情类鹡鸰。","解骖深缱绻，周急免伶俜。","饱德心方洽，分襟泪欲零。","间关萦梦寐，望月缅仪型。","陋巷安初服，嘉音伫远听。","他年功业就，端不负钟铭。"]},{"t":"制艺","f":"五言古诗","c":["酝酿坟皇奥，研抒性命馀。","身当多难后，心隔少年初。","勉扩尘中境，聊摅腹内书。","风雷随煅炼，冰雪荡空虚。","艰苦文章在，支离世务疏。","此中堪自信，诸子意何如。"]},{"t":"癸亥五月二十后酷热异常死者万计六月五日恭遇皇上省躬求言是夜北风大作继以膏雨沴戾顿除仰见圣主至诚格天捷于影响赋此纪异且私幸其安全也","f":"五言古诗","c":["旱魃从来有，骄阳似此无。","乾坤三昧火，昼夜一洪炉。","督亢山疑灼，桑乾水渐枯。","熇蒸当五月，瘴疠遍燕都。","烈日焦躯体，炎飙中喝痡。","书斋团火狱，天意欲焚儒。","声怵街邻哭，心茫去住图。","阴阳无间隔，人鬼但须臾。","精祷诚能格，苍生谴顿除。","大风驱沴戾，霖泽渥膏腴。","势定方妻子，身存再发肤。","亲知相庆吊，远迩尽欢娱。","羁魄惊初复，香胶喜亦沽。","高穹呼吸接，兹理信非诬。"]},{"t":"赋得汲古得修绠","f":"五言古诗","c":["圣贤遗大业，慷慨慕前修。","纤悉虽曾获，渊深不易求。","譬穷江海阔，须自滴涓谋。","岁月为长索，诗书汲众流。","辘轳操巨手，甘苦渥枯喉。","濡首探精蕴，冲波习勇泅。","一朝登道岸，百尺上竿头。","瀱汋无超识，空馀抱瓮羞。"]},{"t":"赋得登云梯","f":"古风","c":["灵峦干碧落，云路有丹梯。","振步淩?崿，登峰岂杖藜。","足音铿石齿，山脑缩芒鞮。","渐与尘寰回，还随鸾鹤跻。","明河流耳畔，佳气满关西。","影出烟霞表，身承雨露低。","攀缘无蹭蹬，高下受提携。","不奋淩云志，终当困浊泥。"]},{"t":"赋得日暖万年枝","f":"五言古诗","c":["曈昽升大地，晻暧茂芳枝。","旭景融贞干，苍髯耀赤墀。","栽培蒙厚土，精彩发明时。","纤翳无亏曜，倾阳早若葵。","敷荣堪献寿，劲节复能持。","已受离光照，还思夜露滋。","豫章欣有托，梁栋自多资。","樗栎虽凡陋，流辉幸不遗。"]},{"t":"赋得熏风入禁松","f":"五言古诗","c":["夭矫古松树，栽培禁苑中。","祝融宣仲侣，偃盖引南风。","鸳瓦声初起，虬枝势暗通。","郁葱云气下，跄济佩声融。","灵籁森青琐，苍涛动碧空。","虞弦欣在御，民愠解何穷。","每羡淩霄干，深蒙被物功。","坚贞期自励，樗散薄幽丛。"]},{"t":"赋得五月五日扬子江心铸镜","f":"五言古诗","c":["水心天宝镜，灵异世无双。","神匠鸠重午，鸿钧绕大江。","一轮光继日，对月夜悬窗。","时有龙鸾翙，还教心胆降。","涵虚长皎洁，鉴物别珉矼。","应祀甘霖霈，无劳水滴駹。"]},{"t":"代寿山东中丞朱母程太夫人八秩有四初度三首 其一","f":"五言古诗","c":["冠盖盘江盛，家声奕叶长。","祖勋传博穆，母德媲桓光。","自有充闾庆，因来九鹤祥。","诞生公辅器，襄佐圣明皇。","伊洛思犹切，淮扬颂不忘。","经纶闻黼座，节钺授封疆。","膏雨周齐甸，仁声播鲁邦。","三春成寿域，大耋庆高堂。","天语嘉贤淑，恩纶锡诰章。","承欢开幕府，祝嘏献霞觞。","鹤发初萌镜，霜姿翠映篁。","孙云纷绕膝，兰桂灿成行。","禄养今方炽，松年老愈康。","荒词何足贵，聊借祝遐昌。"]},{"t":"代寿山东中丞朱母程太夫人八秩有四初度三首 其二","f":"五言古诗","c":["斗极钟灵气，名贤旷代生。","钜才堪鼎鼐，雅量协枢衡。","学富穷三箧，文成压两京。","巍科先获隽，太守蚤蜚英。","乘传淮扬路，维藩河洛行。","悬鱼标峻洁，携鹤表廉平。","廷有徵黄论，天回借寇情。","经纶资锁钥，齐鲁枉麾旌。","画笏为筹策，藏胸富甲兵。","使君真福曜，东土作金城。","款曲求民膜，渊冲秉国成。","臣心银箭直，官况玉壶清。","杞菊衙斋饭，羔羊道路评。","史云遥并驾，伯起实齐声。","属吏亲圭璧，馀芳缀杜蘅。","春阳熙浩荡，夏屋荫峥嵘。","每欲镌铭颂，时同骖竹迎。","及兹逢母寿，欣与祝长庚。","蓂荚祥初验，恩纶诏屡荣。","瑞光凝棨戟，綵服映璁珩。","慈貌臞于鹤，佳孙秀若瑛。","板舆扶月稳，玉佩受风轻。","麟髓应调馔，冰桃亦助觥。","仙姬攀玉杖，奼女奏鸾笙。","璇斗经天朗，台精照地明。","无劳问铅汞，真已近蓬瀛。","伟矣旂常业，皇哉巾帼名。","雀环人拟献，葵日我先倾。","叙德惭窥管，抒怀悚报琼。","击辕聊有颂，郢曲不堪赓。"]},{"t":"代寿山东中丞朱母程太夫人八秩有四初度三首 其三","f":"五言古诗","c":["寿母垂僖颂，共姜录卫风。","节高成子孝，心苦教臣忠。","虎尾灾曾履，春台暖渐融。","郎君当运会，梦卜兆罴熊。","彩凤淩霄起，神鹏绝汉翀。","襟披乐广雾，才发士元空。","淮豫传芳绩，经纶简睿衷。","名悬三岛北，身障百川东。","远迩周民隐，恩威沛泽公。","千秋欣遇合，一德动昭融。","汲引宁馀力，声华每发蒙。","清流同注壑，弱翮早依丛。","感激缘明义，追随愿始终。","慈帏逾大耋，宠诰锡高穹。","懿则谁能并，芳规播不穷。","阐幽存史笔，作颂献雕虫。","已觉惭圭璧，还知类管筒。","何人歌绝调，冰雪在梧桐。"]},{"t":"上丁日皇上亲诣太学行释奠礼恭纪十二韵","f":"五言古诗","c":["文治开天运，明禋重国黉。","銮舆移禁籞，凤冕出严城。","对越天颜穆，趋跄士气荣。","百灵森羽戚，九奏戛箫笙。","道契尼山秘，心通泗水灵。","上丁修祀典，至圣感精诚。","恍接无言教，欣看大道行。","森严神驭悦，震憺众情倾。","雷动回云日，山呼诵圣明。","祥光馀殿庑，春色满神京。","翘首宫墙近，斋心刻漏惊。","幸叨陪祀列，踊跃发欢声。"]},{"t":"古意 其一","f":"五言绝句","c":["白云起前山，遮断郎归路。","妾欲往从之，知郎在何处。"]},{"t":"古意 其二","f":"五言绝句","c":["明月挂前轩，秋风下高树。","忽动别离情，出门望江路。"]},{"t":"古意 其三","f":"五言绝句","c":["虫语响空阶，高梧落疏影。","秋夜月华明，独照孤帏冷。"]},{"t":"古意 其四","f":"五言绝句","c":["郎爱蕙草花，花多恐难久。","妾有幽兰香，愿君莫去手。"]},{"t":"古意 其五","f":"五言绝句","c":["嘉树植中庭，号为女贞木。","岁寒色不凋，霜雪从相酷。"]},{"t":"子夜歌 其一","f":"五言绝句","c":["妾有五色丝，织作同心带。","绾以结不开，试看郎心耐。"]},{"t":"子夜歌 其二","f":"五言绝句","c":["采莲荡轻舟，莲房含未吐。","但见莲花娇，谁识莲心苦。"]},{"t":"子夜歌 其三","f":"五言绝句","c":["鸳鸯傍莲舟，欲打心忽变。","俄见有人来，佯羞整金钿。"]},{"t":"子夜歌 其四","f":"五言绝句","c":["瞥见双鸳鸯，交颈戏珠箔。","惭笑隐房栊，低声骂轻薄。"]},{"t":"四声曲 其一","f":"五言绝句","c":["日落山峰紫，月出溪水绿。","时闻款乃声，隐隐过岩曲。"]},{"t":"四声曲 其二","f":"五言绝句","c":["深山绝行踪，轮囷多古木。","时闻樵采声，丁丁出幽谷。"]},{"t":"四声曲 其三","f":"五言绝句","c":["乔木啭仓庚，春雨昨夜足。","时闻叱牛声，村村野相续。"]},{"t":"四声曲 其四","f":"五言绝句","c":["羊牛相呼鸣，夕阳含雨足。","时闻横笛声，遥遥下山麓。"]},{"t":"秋夜旅情","f":"五言绝句","c":["明月浸疏桐，空阶虫语响。","伏枕梦不成，凄其动远想。"]},{"t":"都门晚眺","f":"五言绝句","c":["吾家在何处，遥遥白云蔽。","伫望白云飞，云飞杳无际。"]},{"t":"对月口占 其一","f":"五言绝句","c":["閒夜步苔阶，一身万里客。","明月照我怀，顾影长太息。"]},{"t":"对月口占 其二","f":"五言绝句","c":["两地不相见，共此明月光。","殷勤望明月，展转心内伤。"]},{"t":"秋夜","f":"五言绝句","c":["檐端露明月，月苦乡心儆。","草虫寒夜鸣，疏桐落秋影。"]},{"t":"石桥","f":"五言绝句","c":["略彴石欹斜，菖蒲映清水。","水流细有声，泠泠漱石齿。"]},{"t":"板桥真武庙","f":"五言绝句","c":["古寺覆寒云，下马聊独往。","四顾无人声，风蝉树间响。"]},{"t":"谷口茶棚庵","f":"五言绝句","c":["谷口施茶僧，击磬迎来往。","松棚午阴凉，时有松风响。"]},{"t":"渡滦河","f":"五言绝句","c":["雾气暗河干，霜花浮草色。","行路讵不难，如何远跋涉。"]},{"t":"抚宁道中","f":"五言绝句","c":["上山复下山，时行山涧底。","落日恐夕心，遥遥望墟里。"]},{"t":"涧底花","f":"五言绝句","c":["空谷媚幽姿，寒花抱一枝。","秋风吹不息，摇落复谁知。"]},{"t":"榆关遇雨","f":"五言绝句","c":["萧萧红叶落，历历雁声过。","一夜榆关雨，愁听出塞歌。"]},{"t":"出关闻雁","f":"五言绝句","c":["匹马秋风道，荒山夜雨时。","音书如解寄，为报客行迟。"]},{"t":"翡翠花","f":"五言绝句","c":["山中翡翠花，秀夺炎鸟色。","采撷充佩帏，应教美人悦。"]},{"t":"野茶花","f":"五言绝句","c":["塞上牧马儿，采叶调酥酪。","空有珍珠花，随风自开落。"]},{"t":"口占赠李复堂","f":"五言绝句","c":["杰士多奇情，往往不得吐。","相遇素心人，一日可千古。"]},{"t":"山寺","f":"五言绝句","c":["古寺翠烟深，日入空山静。","渔火隔溪明，寒松落疏磬。"]},{"t":"春斋","f":"五言绝句","c":["野性逖尘情，荒斋人独宿。","昨夜春雨过，窗前发新绿。"]},{"t":"白鹭","f":"五言绝句","c":["野性依沙渚，䙰褷净雪襟。","风芦栖未稳，延颈忆云岑。"]},{"t":"拥翠庭","f":"五言绝句","c":["石骨垒为墙，石皮盖为瓦。","清风送微凉，高卧南窗下。"]},{"t":"南陂","f":"五言绝句","c":["苍翠带平冈，坐见南山路。","白云淡无心，遥遥向山去。"]},{"t":"烟霞汇","f":"五言绝句","c":["山势高逶迤，溪流复清绝。","虚谷寂无人，烟霞自兴灭。"]},{"t":"琴石","f":"五言绝句","c":["山月渐欲高，泉声响岩窦。","石上理鸣琴，松风落衣袖。"]},{"t":"掬月溪","f":"五言绝句","c":["美人弄明月，清辉长在手。","欲以赠他人，虚明惧难守。"]},{"t":"龙潭","f":"五言绝句","c":["山坳郁潭窟，蜿蜒神龙藏。","有时欲行雨，云起山苍茫。"]},{"t":"独树庵","f":"五言绝句","c":["苍翠掩禅关，夜深人说法。","老僧独无言，倚树看秋月。"]},{"t":"山馆","f":"五言绝句","c":["摊书坐南窗，虚室绝尘想。","风过壁琴鸣，铿然流细响。"]},{"t":"留云坞","f":"五言绝句","c":["朝作陇头阴，暮作田间雨。","却怪此山云，不乐尘中去。"]},{"t":"瀑水厓","f":"五言绝句","c":["冰雪悬重冈，惊飞落奇响。","来者不可留，去者悲长往。"]},{"t":"白石渡","f":"五言绝句","c":["饭牛山之南，垂钓山之北。","行者莫问津，前途不相识。"]},{"t":"山寺","f":"五言绝句","c":["古杖策秋云，遥望云中寺。","时有林梢风，吹雨落山翠。"]},{"t":"山云","f":"五言绝句","c":["行步望前山，白云若堪把。","入云不见云，白云在山下。"]},{"t":"望前山","f":"五言绝句","c":["盈眸苍翠深，诘屈寻樵路。","转瞬岚气生，忽失前峰处。"]},{"t":"步屧","f":"五言绝句","c":["群鸟暮归飞，夕阳在高树。","步屧下平冈，白云横去路。"]},{"t":"送人归山","f":"五言绝句","c":["君归隐名山，山中结茅屋。","应有太古云，长伴幽人宿。"]},{"t":"芳树轩","f":"五言绝句","c":["芳树郁晴轩，山禽相聚语。","树里白云来，轻风复将去。"]},{"t":"山泉","f":"古风","c":["灵液吐云根，??流泉注。","泉在此山清，莫向人间去。"]},{"t":"寻春","f":"五言绝句","c":["寂历踏空林，兼之访樵牧。","相见指南山，山南草初绿。"]},{"t":"访隐","f":"五言绝句","c":["空山太古民，茅茨结深处。","溪谷涨流云，惆怅山前路。"]},{"t":"新晴","f":"五言绝句","c":["积雨溜阶除，临轩玩新霁。","幽鸟不惊人，飞来啄山翠。"]},{"t":"秋夜","f":"五言绝句","c":["空山气候清，夜深人未寝。","流萤入座来，忽觉衣裳冷。"]},{"t":"山出云","f":"五言绝句","c":["閒云偶出山，时作山前雨。","流光若近人，即之无觅处。"]},{"t":"整屧","f":"五言绝句","c":["整屧启荆扉，寻源约邻舍。","忽听水声潺，新泉迸阶下。"]},{"t":"早行","f":"五言绝句","c":["石磴历崟崎，野花泫朝露。","空际但闻香，欲觅不知处。"]},{"t":"登房山","f":"五言绝句","c":["崇冈高崔巍，登顿猿鹤路。","指点下方云，云中几家住。"]},{"t":"看红叶","f":"五言绝句","c":["霜叶灿朱霞，溪水相映带。","水上多白云，人家白云外。"]},{"t":"秋斋","f":"五言绝句","c":["野树著新霜，青黄映窗左。","归鸟栖复惊，山猿窃岩果。"]},{"t":"宿山馆","f":"五言绝句","c":["朝出雅初鸣，暮归日已暝。","清梦不离山，还踏苍苔径。"]},{"t":"幽寻","f":"五言绝句","c":["汗漫恣幽寻，峰林相蔽隐。","隔浦见炊烟，知有山家近。"]},{"t":"石阙","f":"五言绝句","c":["采芝石阙西，放鹤石阙东。","此中有天地，不与黄埃通。"]},{"t":"老衲","f":"五言绝句","c":["老衲竟何为，坚坐理鹤发。","有时渴欲饮，汲碎寒潭月。"]},{"t":"渔舟","f":"五言绝句","c":["仰看山色青，俯看溪水绿。","夜泊芦荻湾，白云伴孤宿。"]},{"t":"野寺","f":"五言绝句","c":["老树出颓垣，客至雀惊起。","僧雏款禅扉，烹茶掬溪水。"]},{"t":"题画","f":"五言绝句","c":["荷锸采紫芝，山深迷所在。","应有商山翁，携手云峰外。"]},{"t":"题画梅 其一","f":"五言绝句","c":["冰霜结严寒，生意久寥落。","此时天地心，独有梅先觉。"]},{"t":"题画梅 其二","f":"五言绝句","c":["当春不发花，春去不著叶。","独抱岁寒心，芳香吐冰雪。"]},{"t":"题画梅 其三","f":"五言绝句","c":["苍根如积铁，夭矫枝条劲。","天地浸冰霜，寒香欲谁赠。"]},{"t":"山窗","f":"五言绝句","c":["红杏发南枝，山窗鸟声集。","落花飞不高，随风复飘入。"]},{"t":"新霁","f":"五言绝句","c":["新霁葛衫轻，閒吟步庭砌。","松轩昼忽阴，冉冉流云至。"]},{"t":"雨后山斋","f":"五言绝句","c":["山斋雨乍晴，新月照茅屋。","万籁寂不喧，残声滴疏竹。"]},{"t":"步月","f":"五言绝句","c":["烟消万壑净，独步平林东。","披襟一长啸，明月悬高空。"]},{"t":"题画 其一","f":"五言绝句","c":["扁舟溯回溪，溪穷崖石陡。","我欲问桃源，白云横渡口。"]},{"t":"题画 其二","f":"五言绝句","c":["山老骨磷磷，水清石楚楚。","明月下渔舟，野烟生极浦。"]},{"t":"赠僧 其一","f":"五言绝句","c":["虚室闻空香，窗前落溪水。","相对两忘言，坐看山云起。"]},{"t":"赠僧 其二","f":"五言绝句","c":["尘市结精庐，杂花映修樾。","欲识妙明心，寒潭贮秋月。"]},{"t":"独吟","f":"五言绝句","c":["枯坐耽微吟，默与天机会。","静里闻孤鸿，彷佛层霄外。"]},{"t":"夜雨","f":"五言绝句","c":["夜雨洒山斋，幽人入虚听。","朝来启户看，落花满苔径。"]},{"t":"首夏","f":"五言绝句","c":["首夏日初暖，佳树新阴茂。","濛濛细雨滋，阶面苍苔厚。"]},{"t":"独行","f":"五言绝句","c":["閒居爱丘壑，独行常踽踽。","空谷无人声，坐听山禽语。"]},{"t":"晴","f":"五言绝句","c":["小雨天忽晴，盈眸尽空翠。","花落寂无声，随风沾衣袂。"]},{"t":"新秋","f":"五言绝句","c":["露涤山径清，秋气满林薄。","寥寥天宇空，高飞唳孤鹤。"]},{"t":"早春","f":"五言绝句","c":["策杖缘流溪，迤逦春山里。","隔浦望村墟，山桃发红蕊。"]},{"t":"月夜","f":"五言绝句","c":["天高秋月明，澄潭复皎洁。","山静无人迹，此景唯自悦。"]},{"t":"暮","f":"五言绝句","c":["疏雨过空阶，暮禽将侣去。","野云不归山，夜宿檐前树。"]},{"t":"晓行 其一","f":"五言绝句","c":["清眺入深林，露气熏芳芷。","野寺闻山钟，遥遥隔溪水。"]},{"t":"晓行 其二","f":"五言绝句","c":["牯牛下崇冈，野禽浴溪水。","烟霞蔽茅茨，犬吠深林里。"]},{"t":"蔬圃","f":"五言绝句","c":["野老爱佳蔬，种植资膏土。","林中灌汲声，轧轧鸣秋圃。"]},{"t":"隐几","f":"五言绝句","c":["幽讨日欲曛，归来聊隐几。","魂梦不知疲，仍在群峰里。"]},{"t":"秋灯","f":"五言绝句","c":["秋宵万籁清，天地归真静。","一灯对古人，默默自深省。"]},{"t":"秋兰","f":"五言绝句","c":["涉江采芳兰，正值秋风起。","美人期不来，怀香向谁是。"]},{"t":"秋虫","f":"五言绝句","c":["孤月照高梧，萧疏落寒影。","唧唧候虫鸣，秋声露中冷。"]},{"t":"秋苔","f":"五言绝句","c":["扃户少人踪，苔痕厚阶砌。","山鸟爱幽居，衔花落苍翠。"]},{"t":"秋雨","f":"五言绝句","c":["峰顶扩奇怀，天地收双目。","长啸月横空，流声满岩谷。"]},{"t":"秋空","f":"五言绝句","c":["孤艇泊枫林，梦绕江天路。","寒雨带归鸿，飞向江南去。"]},{"t":"秋坟","f":"五言绝句","c":["商飙起原野，悲响在杨木。","荒冢亦何知，行人为踯躅。"]},{"t":"秋田","f":"五言绝句","c":["老农幸有秋，殷勤望田谷。","牧子独无心，驱牛下寒绿。"]},{"t":"送别","f":"五言绝句","c":["笙歌兴已阑，欢笑转悽楚。","别语正依依，残钟天欲曙。"]},{"t":"怀友","f":"五言绝句","c":["别酒怨征鸿，携手衡门道。","新莺忽作声，绿遍阶前草。"]},{"t":"白头吟 其一","f":"五言绝句","c":["白头兼莫春，非复芳菲节。","展转心忽伤，深悲蕙草歇。"]},{"t":"白头吟 其二","f":"五言绝句","c":["兰香发芳春，春归香欲歇。","佳期久已悭，独立庭前月。"]},{"t":"山居 其一","f":"五言绝句","c":["茅屋下斜阳，摊书卧北窗。","片云生栋宇，化作雨苍茫。"]},{"t":"山居 其二","f":"五言绝句","c":["危磴转寒山，窅窕麇□路。","丁丁发木声，远隔云深处。"]},{"t":"山居 其三","f":"五言绝句","c":["邃石吐苍云，参差落檐瓦。","时与好风俱，甘霖被原野。"]},{"t":"山居 其四","f":"五言绝句","c":["春雨润前村，扶筇每孤往。","百谷性不分，时听农人讲。"]},{"t":"冬日山行","f":"五言绝句","c":["石冻流泉细，林枯落叶乾。","扶筇过鸟道，风磴入云寒。"]},{"t":"别赵南村","f":"五言绝句","c":["相逢应未远，何事转凄其。","才得与君遇，冰霜又别离。"]},{"t":"挂剑台","f":"五言绝句","c":["宝剑值千金，欲赠徐君死。","解挂墓门前，千秋吴季子。"]},{"t":"怀清台","f":"五言绝句","c":["巴妇饮丹穴，芳声动庙庭。","所遭非令主，曾为筑怀清。"]},{"t":"题画册十七首 其一","f":"五言绝句","c":["溪流淰淰清，山色鳞鳞碧。","空亭云气深，何处幽人迹。"]},{"t":"题画册十七首 其二","f":"五言绝句","c":["野老不入城，家在云深处。","山径结危桥，看云日来去。"]},{"t":"题画册十七首 其三","f":"五言绝句","c":["茅屋隐山坳，石磴崟崎上。","时复掉船归，空江孤月朗。"]},{"t":"题画册十七首 其四","f":"五言绝句","c":["树里人家屋，柴荆傍水隈。","江空天一色，帆影日边来。"]},{"t":"题画册十七首 其五","f":"五言绝句","c":["顿僻数间屋，扶疏几株树。","野老坐垂纶，日送浮云去。"]},{"t":"题画册十七首 其六","f":"五言绝句","c":["山绕鹿门青，庞公旧隐形。","欲空天地眼，峰顶结孤亭。"]},{"t":"题画册十七首 其七","f":"五言绝句","c":["携杖石桥东，松风起幽听。","白云满空山，谁识幽人径。"]},{"t":"题画册十七首 其八","f":"五言绝句","c":["浩雪盈空山，天地还淳朴。","欲识造化心，寒梅发深谷。"]},{"t":"题画册十七首 其九","f":"五言绝句","c":["群峰云上立，乱石风前走。","荡胸岚气生，看山背两手。"]},{"t":"题画册十七首 其十","f":"五言绝句","c":["访衲登危巘，听泉倚卧松。","回看山下路，已有白云封。"]},{"t":"题画册十七首 其十一","f":"五言绝句","c":["厓石森精灵，长松碍云日。","科头何处翁，摊书坐蓬室。"]},{"t":"题画册十七首 其十二","f":"五言绝句","c":["鹿门空有约，林虑旧山孤。","何处寻真隐，人间见画图。"]},{"t":"题画册十七首 其十三","f":"五言绝句","c":["漠漠洞壑云，萧萧芦荻岸。","月明天宇空，孤鹤横霄汉。"]},{"t":"题画册十七首 其十四","f":"五言绝句","c":["怪石立山鬼，狰狞古渡头。","涛声催贾客，风雨急归舟。"]},{"t":"题画册十七首 其十五","f":"五言绝句","c":["云起群峰动，溪流众壑喧。","荒村枯木外，踪迹老衡门。"]},{"t":"题画册十七首 其十六","f":"五言绝句","c":["流水绕重山，茅茨隔烟雾。","借问捕鱼翁，莫是桃源路。"]},{"t":"题画册十七首 其十七","f":"五言绝句","c":["蹊柳初垂绿，平桥接水田。","荷锄新雨足，沽酒话丰年。"]},{"t":"明妃","f":"五言绝句","c":["奉命和戎主，甘心朔漠来。","望乡时洒泪，不上李陵台。"]},{"t":"孟才人","f":"五言绝句","c":["妾命何堪惜，恩深殉九泉。","一声歌未竟，肠断旧君前。"]},{"t":"题吴园二十景 其一 白沙翠竹江村","f":"五言绝句","c":["水净白沙明，花满江村路。","策杖入修篁，清谈坐深处。"]},{"t":"题吴园二十景 其二 见山楼","f":"五言绝句","c":["苍苍楼前山，连峰数千里。","上接蔚蓝天，下带长江水。"]},{"t":"题吴园二十景 其三 华黍斋","f":"五言绝句","c":["养高绝外营，郊居爱华黍。","江上无心云，飞来落甘雨。"]},{"t":"题吴园二十景 其四 千尺桃花潭","f":"五言绝句","c":["灼灼桃花红，澄澄潭水绿。","疑是武陵源，人家匿深谷。"]},{"t":"题吴园二十景 其五 月台","f":"五言绝句","c":["明月丽中天，群动一时寂。","独坐理鸣琴，清辉照几席。"]},{"t":"题吴园二十景 其六 分江","f":"五言绝句","c":["清江可濯缨，分来就溪壑。","应有濠上人，相携看鱼乐。"]},{"t":"题吴园二十景 其七 仙人洞","f":"五言绝句","c":["坐久寂无闻，真人潜深窟。","静里察玄机，白云蓊欲出。"]},{"t":"题吴园二十景 其八 东溪白云亭","f":"五言绝句","c":["戢茅傍东溪，溪光摇屋宇。","白云往复来，时作亭前雨。"]},{"t":"题吴园二十景 其九 虚舟","f":"五言绝句","c":["结屋号虚舟，閒心绝世忤。","一任水禽来，衔花满幽处。"]},{"t":"题吴园二十景 其十 三峡馀波","f":"五言绝句","c":["江源不可穷，馀波注芳泽。","髣髴坐瞿塘，清猿叫虚壁。"]},{"t":"题吴园二十景 其十一 古柏","f":"五言绝句","c":["老柏蟠虬龙，夭矫鳞鬣古。","时有清风来，吹落藤花雨。"]},{"t":"题吴园二十景 其十二 芙蓉沜","f":"五言绝句","c":["涉江采芙蓉，江流水平远。","欲渡无舟航，惆怅秋风晚。"]},{"t":"题吴园二十景 其十三 柳风麦浪之间","f":"五言绝句","c":["垂柳带平畴，孤亭坐山翠。","野老叱牛归，夕阳下平地。"]},{"t":"题吴园二十景 其十四 复啸亭","f":"五言绝句","c":["弹琴坐修篁，长啸怀往昔。","明月无古今，还照幽人夕。"]},{"t":"题吴园二十景 其十五 冬缸书屋","f":"五言绝句","c":["文史富三冬，青缸照往哲。","欲识天地心，寒梅吐冰雪。"]},{"t":"题吴园二十景 其十六 江乡传舍","f":"五言绝句","c":["胥口渡已沈，銮江非故迹。","亭林几度更，登临怅畴昔。"]},{"t":"题吴园二十景 其十七 雪窟","f":"五言绝句","c":["丛梅发严冬，光辉映白雪。","一曲郢中歌，寒宵对孤月。"]},{"t":"题吴园二十景 其十八 烟霞多处","f":"五言绝句","c":["烟霞逞殊观，变幻不可测。","转瞬归虚无，青苍见山色。"]},{"t":"题吴园二十景 其十九 因是庵","f":"五言绝句","c":["妙谛悟真空，清净丘园里。","明月照檐端，还照前江水。"]},{"t":"题吴园二十景 其二十 小山秋","f":"五言绝句","c":["小山丛桂花，秋风吹不落。","此地近淮南，余将老栖托。"]},{"t":"题采药图","f":"五言绝句","c":["偶随玄鹿径，已入白云乡。","此际逢刘阮，相携渡石梁。"]},{"t":"青陵台","f":"五言绝句","c":["淫雨霖霖歇，江河水不深。","祇今台上日，万古照贞心。"]},{"t":"淮阴钓台","f":"五言绝句","c":["不耐王孙饿，收纶去此台。","曾经淮水渡，千古为生哀。"]},{"t":"子陵钓台 其一","f":"五言绝句","c":["人生各有志，乃在去就间。","一钓成千古，高风不可攀。"]},{"t":"子陵钓台 其二","f":"五言绝句","c":["世代更千载，高人去不回。","富春江上月，独照子陵台。"]},{"t":"对镜","f":"五言绝句","c":["冶容耀春花，妆罢自矜惜。","顾影复徘徊，低头长太息。"]},{"t":"午睡","f":"五言绝句","c":["熏风清枕簟，娇睡晕潮生。","微笑朱唇启，应知梦里情。"]},{"t":"秋宵","f":"五言绝句","c":["芙蓉落叶疏，鸳鸯怯波冷。","银汉耿中宵，孤帏清漏永。"]},{"t":"调砧 其一","f":"五言绝句","c":["孤妾调砧杵，空闺生早寒。","思君沙漠外，风雪走瀰漫。"]},{"t":"调砧 其二","f":"五言绝句","c":["夜气侵双臂，深宵睡未迟。","妾心难远寄，辛苦月明知。"]},{"t":"题年家子卢主事秋灯夜读图","f":"五言绝句","c":["明月照高天，青云傍庭户。","心静夜摊书，欣然慕前古。"]},{"t":"题沈学子徵兰图","f":"五言绝句","c":["涉露采芳兰，花开被九畹。","将为王者香，莫畏秋风晚。"]},{"t":"题兴福寺 其一","f":"五言绝句","c":["破山唐代寺，潭影浸禅房。","偶共高僧坐，閒云满石床。"]},{"t":"题兴福寺 其二","f":"五言绝句","c":["坐久山光淡，禅关日色低。","微闻孤鹤唳，声在数峰西。"]},{"t":"长信宫 其一","f":"七言绝句","c":["当春兰蕙竞芬芳，金殿筵开捧御觞。","几日承恩欢乐地，秋风花落禁宫凉。"]},{"t":"长信宫 其二","f":"七言绝句","c":["九重恩断妾难忘，日日焚香扫御床。","朝罢探君何处乐，人传歌舞在昭阳。"]},{"t":"长信宫 其三","f":"七言绝句","c":["西宫芳草正添愁，沸耳笙歌乐未休。","莫羡腰肢轻似燕，当年恩眷妾曾优。"]},{"t":"春闺","f":"七言绝句","c":["花落庭閒睡起迟，倦欹鸳枕蹙蛾眉。","穿窗忽见归来燕，长叹一声双泪垂。"]},{"t":"春怨","f":"七言绝句","c":["别语分明计日回，香闺深思转徘徊。","伤心有约庭前树，寂寞无人花又开。"]},{"t":"秋砧","f":"七言绝句","c":["月照孤帏夜正长，凄凄砧杵捣秋光。","妾身不畏西风冷，只恐天山下早霜。"]},{"t":"九日登高","f":"七言绝句","c":["笳声凄切雁声哀，风起高原猎骑回。","无尽愁云吹不散，望乡空上白龙堆。"]},{"t":"塞上词 其一","f":"七言绝句","c":["平沙漠漠戍楼阴，一派边声动暮砧。","塞上秋风吹不尽，营州城北古云深。"]},{"t":"塞上词 其二","f":"七言绝句","c":["郊原雪后黑山枯，风捲黄芦射猎初。","小队韬弓驰马去，乱云堆里有穹庐。"]},{"t":"少年行","f":"七言绝句","c":["把酒高歌出汉关，少年豪气可移山。","宝刀脱赠还抽看，指点锋头战血斑。"]}]};